window.__D("text/ner-mitzva/c001",{"p":[[2800530077,"מצד כח עצמו ומהותו דוקא וד\"ל:\n<b>ומעתה</b> יש להבין פי' הב' דעצרת לשון אסיפה וכנישה כו'. דהנה באמת יש להפליא מ\"ש ו' ימים תאכל מצות וביום הז' עצרת דמשמע שאין חובה ומצוה ביום ז' כמו בו' הימים ובאמת ליל יום הא' חוב'<sup data-n=\"847\">15</sup> והו' ימים הן רשות ולא נבדל יום הז' מו' ימים שלפניו שכל הז' ימי' רשות ולא חוב' רק ליל יום א' לבד וז\"ש מה ז' רשות<sup data-n=\"848\">16</sup> אף ו' ימים רשות ולא חובה ומ\"ש ו' ימי' תאכל הוא רשו' גם הז' רשות כמוה' ולמה אמר וביום הז' עצר' כו' אך הענין הוא דגם שז' ימים אלו שוין לענין אכילת מצה למטה בכנ\"י כמ\"ש בכמה דוכתי מצות יאכל<sup data-n=\"849\">17</sup> את ז' הימי' ז' ימים מצות תאכלו<sup data-n=\"850\">18</sup> כו' וכה\"ג אך בענין אכיל' דמצה למעל' מעל' באצי' הוא שנבדל יום הז' מו' ימים שלפניו והוא מ\"ש ביום הז' עצרת לה' ופי' עצרת זה ל' כנישה ואסיפ' כו' וביאו' הדברי' הנה מבוא' למעל' בשרש ענין המצה למטה בכנ\"י שהוא ההמשכה דכח האמונה בנש\"י מלמעלה מן הדעת כמ\"ש ורעה אמונה<sup data-n=\"851\">19</sup> כו' ובכל ז' ימים דמל' נמשך מבחי' קטנו' דאבא שהוא הארת בחי' מהו\"ע שמלובש בקטנות דאבא דוקא ששרשו בחי' מ\"ה העצמי כמ\"ש והחכמה מאין<sup data-n=\"852\">20</sup> כו' כנ\"ל באריכות שע\"ז שואל חכם מה כו' וז\"ש מצות יאכל את ז' הימים דמל' אך מ\"ש כאן ו' ימים תאכל כו' הענין הוא דבזש\"פ מצד קי\"ס שעלה המל' במהו\"ע שלמעלה גם מפנימית אבא וע\"י כנ\"ל הרי אז צריך להמשיך לאור אבא מבחי' מצה זו שנק' מאכל ומזון לאור אבא עצמו מאחר שאז נאמ' עצרת לה' ל' מניעה ועיכוב שהוא כמו עצור במילין<sup data-n=\"853\">21</sup> לפי שכח החכ' עצמו עולה למעלה כנ\"ל וכמ\"ש בזהר אכלו רעים או\"א<sup data-n=\"854\">22</sup> הרי יש בחי' מזון עליון גם לאור אבא למעל' כו' וכה\"ג אמרז\"ל בפי' רעייתי שישראל מפרנסין<sup data-n=\"855\">23</sup> לאביהם שבשמים ופי' אביהם שבשמים הוא בחי' פנימית אור אבא למעלה כמ\"ש כי אתה אבינו<sup data-n=\"856\">24</sup> שזהו בחי' מקור ושרש הראשון דנש\"י שעלו במחשבה<sup data-n=\"857\">25</sup> עד בחי' מח' הקדומה כו' ופי' מפרנסין פרנסה זאת הוא בחי' מזון ומאכל דוקא והוא האור והשפע שנמשך ממהו\"ע המאציל לאור אבא שנק' אביה' שבשמים דוקא וכידוע דשמים הוא בחי' סוכ\"ע וזהו בדרך כלל ובדרך פרט כנ\"ל ובחי' זו\"נ נק' שמים וארץ<sup data-n=\"858\">26</sup> בדרך פרט כידוע ובחי' סובב הכללי נק' שמים בכלל והפרנסה לאביהם שבשמים היותר עליונים היינו הארת מהו\"ע דא\"ס ב\"ה בסובב הכללי והוא בחי' גאה גאה הנ\"ל שמאי' במח' הקדומ' דמל' דא\"ס וד\"ל וזהו ביום הז' דוקא עצרת לה' אלקיך שזהו לאביהם שבשמים בלשון אסיפה וכנישה והוא המשכת מצה העליונה להוסיף אור בפנימית ומקור החכמ' דאצילות עד רום המעלות כמו שהמצה נק' פרנסה לכנ\"י למטה ממש שע\"ז אמ' ו' ימים תאכל מצות תאכל לנוכח דקאי על כנ\"י שהוא בחי' מל' דאצי' למעלה שנמשך מקטנות דאבא בהעלם משא\"כ כל השנה כנ\"ל אבל ביום הז' דוקא פרנסה זו היא למעלה לאביהם שבשמים שהוא מ\"ש להוי' אלקיך וכמאמר מפרנסים לאביהם שבשמים כו' ובזה נבדל מעלת יום הז' מו' ימים שלא אמ' בו תאכל לנוכח כו' לפי שאז הוא הפרנסה דמצה למעלה באור אבא עצמו שהמל' עלה עמו למעלה במהו\"ע ממש כנ\"ל וד\"ל וזהו לכו לחמו בלחמי<sup data-n=\"859\">27</sup> לחמי היינו לחם ה' עצמו שנמשך לאור אבא ונמשך ע\"י מצה שנק' לחם למטה (או לחמו",[["847","15","<b>ליל יום הא' חוב'</b>: פסחים קכ, א. מכילתא ורש\"י בא יב, טו. שו\"ע אדה\"ז הל' פסח סתע\"ה סל\"ב."],["848","16","<b>מה ז' רשות</b>: נסמן בהערה שלפנ\"ז."],["849","17","<b>מצות יאכל</b>: בא יג, ז."],["850","18","<b>ז' ימים מצות תאכלו</b>: בא יב, טו."],["851","19","<b>ורעה אמונה</b>: תהלים לז, ג."],["852","20","<b>והחכמה מאין</b>: איוב כח, יב."],["853","21","<b>עצור במילין</b>: איוב ד, ב [ושם: ועצר]. כט, ט [ושם: עצרו במלים]."],["854","22","<b>אכלו רעים או\"א</b>: שה\"ש ה, א. זהר ויקרא ד, א."],["855","23","<b>רעייתי שישראל מפרנסין</b>: שה\"ש א, ט. ראה זהר ויקרא ז, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תרעט? הנחות תקע\"ז ע' קמז."],["856","24","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["857","25","<b>דנש\"י שעלו במחשבה</b>: ראה ב\"ר פ\"א, ד. מאמרי אדה\"א בראשית ע' כו? דברים ח\"ד ע' א'קע? הנחות תקע\"ז ע' מד ובהנסמן בהנ\"ל. לקמן מ, ב. נט, א. ס, א. סט, ב."],["858","26","<b>זו\"נ נק' שמים וארץ</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשיד. תו\"ח בראשית כא, ד ובהנסמן במ\"מ לשם."],["859","27","<b>לכו לחמו בלחמי</b>: משלי ט, ה."]]],[2800530078,"היינו שתי הלחם דשבועות תושב\"כ ושבע\"פ<sup data-n=\"860\">1</sup> שנמשך מלחמי דזש\"פ שנק' עצרת לה' אלקיך דוקא וד\"ל) (וביאור הדברים מובן עפ\"י הנ\"ל באריכות בענין מצה שבלא טעם שגבוה מאד בשרשו בהיותו בחי' מהות ועצמות הדבר כמו שהוא טרם שמתפשט להיות בטוב טעם ודעת כו' כך הוא למעלה גם במקור החכמה שכלולה מב' מדריגות א' טעם שבחכמה ונק' מוחין דאבא חכמה שבחכמ' כטעמים שבמאכל ונק' טוב טעם למעלה בחי' עונג המורגש בח\"ע ואמנם מהו\"ע דח\"ע הוא בא מלמעלה מן הטעם העליון הנגלה והוא בחי' העונג הנעלם שנק' עדן עלאה כו' שהוא מבחי' שעשועים העצמיי' דעצמות אא\"ס ממש שהוא כענין גאה גאה הנ\"ל בבחי' התנשאות שמצד עצמותו ממש שזהו מקור כל התפשטות עונג וטעם דחכמ' כו' זהו הנק' בחי' מצה דאבא שהוא מזון ולחם דוקא בבחי' מהו\"ע דאבא דהיינו שהוא זן ומפרנס לבחי' ג\"ר דאבא שנק' פרנסה לאביהם שבשמים עד רום המעלות כנ\"ל שהחכמה מאין ממש תמצא מאין העצמות כו' וע\"כ לא נאמר בו תאכל בגלוי כי הרי הוא בתכלית האין האמיתי ע\"כ נקרא עצרת לה' כו' וד\"ל) (ונמצא ב' הפי' דעצרת הנ\"ל עולין לסגנון א' והוא מה שעצרת ל' מניעה ועיכוב כמו עצור במילין שזהו בעליי' דאור אבא למעלה כו' הוא ענין פי' הב' דעצרת ל' כנישה ואסיפה שצריך מפני זה לפרנס לאבא במוחין חדשים כו'):\n(כא) <b>ומעתה</b> יש להבין מה שאמרו מה שביעי רשות אף ששת ימים רשות כו' דהנה לפי כל הנ\"ל הרי בו' ימים נמשך מקטנו' דאבא במל' בהלבשה ובשביעי כאשר כבר נשלם מזון המל' מאבא עולה עמו למעלה מעלה כנ\"ל ונמשך פרנסה לאור אבא כענין אכלו רעים כנ\"ל וא\"כ ודאי יש הפרש גדול בין ו' ימים ליום הז' שבזה היום הז' נמשך לבחי' אבא עצמו ממקורא דכולא שאין זה בו' הימים וא\"כ איך אמר אף ו' ימים רשות כיום הז' דלכאורה בו' ימים חובה מצד שצריך להמשיך במל' כנ\"ל משא\"כ ביום הז' ואע\"פ שנאמר ז' ימים תאכלו וכן מצות יאכל את ז' הימים כו' מ\"מ בזה נבדל מעלת יום הז' להיות עיקרו בפרנסה לבחינת אור אבא למעלה כנ\"ל אך הנה תחלה יש להבין מהו לשון רשות דייקא דהנה יש להבין מ\"ש כל מלאכת עבודה לא תעשו<sup data-n=\"861\">2</sup> ביום השביעי כמו ביום הראשון בפרשת פנחס ובפרשת אמור (ובפ' בא אמר בשניהם כל מלאכה<sup data-n=\"862\">3</sup> סתם) ובפ' ראה אמר ששת ימים תאכל מצות וביום הז' עצרת כו' לא תעשה מלאכה<sup data-n=\"863\">4</sup> ולא הזכיר מלאכת עבודה אלא מלאכה סתם דמובן מזה עכ\"פ דביום הז' כאשר קוראו עצרת לא יפול בו לשון עבודה ומה ענין עצרת לעבודה שאמר מלאכה סתם ולא מלאכת עבודה כשאר יו\"ט כשנקרא מקרא קדש וכמ\"ש בפ' פנחס ופ' אמור גם ביום הז' וביום הז' מקרא קדש<sup data-n=\"864\">5</sup> כו' כל מלאכת עבודה לא תעשו כו' אך הנה ידוע דענין העבודה למעלה הוא בחינת הבירורים דרפ\"ח כו' וזהו כמו ענין בירור הגשמי בטו\"ר שבתבואות הארץ ע\"י ל\"ט מלאכות<sup data-n=\"865\">6</sup> חורש וזורע וקוצר ודש כו' עד שאופה הפת כך בחי' הבירור בעה\"ד טו\"ר למעלה ע\"י בחי' המל' שהוא שם ב\"ן<sup data-n=\"866\">7</sup> המברר כו'",[["860","1","<b>שתי הלחם. . ושבע\"פ</b>: השמטות לזח\"א רס, א."],["861","2","<b>כל מלאכת עבודה לא תעשו</b>: פינחס כט, כה. יח. אמור כג, ח. ז."],["862","3","<b>ובפ' בא. . כל מלאכה</b>: יב, טז."],["863","4","<b>ובפ' ראה. . לא תעשה מלאכה</b>: טז, ח."],["864","5","<b>וביום הז' מקרא קדש</b>: אמור כג, ח."],["865","6","<b>ל\"ט מלאכות</b>: ראה שבת עג, א."],["866","7","<b>המל' שהוא שם ב\"ן</b>: נסמן לקמן קמה, א."]]],[2800530079,"ובכנ\"י למטה הוא בירור דטו\"ר בנפש במדות רעות ובכל תיקון הצריך שזהו עליות רפ\"ח הניצוצות שנפלו בק\"נ כו' כידוע שנקרא עבודה כמו עורות עבודין<sup data-n=\"867\">8</sup> וכו' אך כ\"ז בהתלבשות המל' בבי\"ע לברר בירורים כמ\"ש ותתן טרף רפ\"ח ע\"ה<sup data-n=\"868\">9</sup> כו' ובכל מועד וי\"ט יש עליות המל' למעלה באצי' כמ\"ש אלה מועדי הוי\"ה<sup data-n=\"869\">10</sup> דוקא וע\"כ נקרא מקרא קדש דהיינו מבחי' מוחין דאבא ואימא כו' נאמר כל מלאכת עבודה לא תעשו לרמז על עבודת הבירורים והעלא' דרפ\"ח כו' אבל ביום הזש\"פ כאשר קוראו בשם עצרת לה' כו' שהוא עליות המל' דאצי' עם אור אבא עד שנקרא עצרת גם להוי' דחכמ' בעצמו' כנ\"ל לא יתכן לומר כלל ענין אזהרה על בחי' עבודה דבירורים אלא או' לא תעשה מלאכה סתם ולא הזכיר היתר מלאכת אוכל נפש ג\"כ וז\"ש בו' ימים שתאכל מצות וביום הז' עצרת ע\"כ לא תעשה מלאכה כלל וד\"ל:\n<b>והנה</b> עפ\"ז יובן ג\"כ מה שא' דהוקשו ו' ימים לז' לענין רשות ולא חובה. דהנה ענין חובה היינו כמו שאמר מים אחרונים חובה<sup data-n=\"870\">11</sup> כו' לברר ולהמתיק הדינין שנאחזי' במל' שנקרא חובה<sup data-n=\"871\">12</sup> ע\"כ נקרא חובה כו' וכך הוא ענין אכילת מצה בליל הא' דפסח שהוא חובה שמלבד שאז עיקר המצוה במצה זו מטעם שנקרא מיכלא דמהימנותא<sup data-n=\"872\">13</sup> להוסיף כח האמונה בכאו\"א מישראל משרשו במוה\"ע<sup data-n=\"873\">14</sup> דוקא כנ\"ל באריכות הנה יש בזה עצמו ענין חובה ולא רשות והיינו להיות שיש טעם שני באכילת מצה זו לפי שעבדים היינו לפרעה ויוציאנו ה'<sup data-n=\"874\">15</sup> כו' ומפני שיצאו בחפזון דוקא כמ\"ש בפ' ראה לא תאכל עליו חמץ ז' ימים תאכל מצות לחם עוני כי בחפזון יצאת ממצרים למען תזכור<sup data-n=\"875\">16</sup> כו' והענין הוא כמ\"ש מצה זו שאנו אוכלים<sup data-n=\"876\">17</sup> על שום מה ע\"ש שלא הספיק כו' שזהו מ\"ש בחיפזון יצאת כי גורשו<sup data-n=\"877\">18</sup> כו' ע\"כ אפו הבצק עוגות מצות כו' ואע\"פ שזה היה אחר חצות גם מצה זו שאנו אוכלים בדרך מצוה וחובה קודם חצות הוא ג\"כ ע\"ש שלא הספיק כו' דהיינו הך והא בהא תליא כנ\"ל באריכות והוא רק מה שיצאו מאפילה לאור גדול<sup data-n=\"878\">19</sup> שלא רצו להשתקע בנש\"ט דמצרים וזהו כמו שאומרים בברכה שלא עשני גוי<sup data-n=\"879\">20</sup> דהיינו רק שאינו רוצה לחיות כחיי הגוים גם דקרו ליה אלוה<sup data-n=\"880\">21</sup> כו' אין בהם בחי' האמונה שהוא במהו\"ע כו' שזהו עיקר נקודת יהדותו א\"כ הרי היציאה מן העבדות לחירות זהו היציאה מאפילה דק\"נ לאור גדול כו' ה\"ז רק בחי' בירור הרע לבד לצאת מאפילה דנש\"ט והוא בא ממילא ע\"י כח האמונה שלפ\"ז יש במצה זו ב' דברים שבאים כא' ממש לצאת מאפילה ולבא לאור גדול דעיקר היהדות כו' וזהו כגר וכבע\"ת שיצא מן הרע וטומאה ושב אל ה' שזהו ענין א' וכך הוא במצה ב' דברים מצוה וחובה מצוה ליכנס בקדושה האלקי' באמונה זו שנק' מיכלא דמהימנותא ונקרא לחם עני וזה עצמו הוא מה שיוצא מאפילה דנש\"ט דזהו הנקרא חובה לברר הרע כו' ונמצא דמצוה זו חובה היא כמו שחובה על האדם לסור מן הרע וכמים אחרונים חובה להעביר הגבורות קשות דק\"נ כנ\"ל וזהו שאמר תאכל מצות לחם עני כי בחיפזון כו' שלחם עני הוא כעני בלחמו למצוא טרף לנפשו בלבד",[["867","8","<b>עבודה כמו עורות עבודין</b>: ראה שבת מט, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תתלח. וש\"נ. נ\"ך ע' תכט. וש\"נ. קונטרסים ע' תקפג."],["868","9","<b>ותתן טרף רפ\"ח ע\"ה</b>: משלי לא, טו. ראה מאמרי אדה\"א בראשית ע' קמו. וש\"נ."],["869","10","<b>אלה מועדי הוי\"ה</b>: אמור כג, ד."],["870","11","<b>מים אחרונים חובה</b>: עירובין יז, ב."],["871","12","<b>הדינין. . שנקרא חובה</b>: בסידור כאן (רפז, א) בזהר ? ראה שם שמות ו, א. תרומה קנד, ב. (היכלות) פקודי רנז, ב. רסו, ב."],["872","13","<b>במצה. . מיכלא דמהימנותא</b>: נסמן לעיל ח, ב."],["873","14","<b>במוה\"ע</b>: נסמן לעיל ב, א."],["874","15","<b>עבדים. . ויוציאנו ה'</b>: ואתחנן ו, כא."],["875","16","<b>לא תאכל. . תזכור</b>: פ' ראה טז, ג [ושם: עליו מצות. . מארץ מצרים]."],["876","17","<b>מצה זו שאנו אוכלים</b>: נוסח ההגדה."],["877","18","<b>כי גורשו</b>: בא יב, לט."],["878","19","<b>מאפילה לאור גדול</b>: פסחים קטז, ב (במשנה). הגדה פיסקא לפיכך."],["879","20","<b>שלא עשני גוי</b>: נוסח ברכות השחר."],["880","21","<b>דקרו ליה אלוה</b>: מנחות בסופה."]]],[2800530080,"והוא שזכו לקבל גלוי שכינה עד שלא הספיק כו' כי גורשו כו' דהא בהא תליא משום דאמונה זו היא המגעת למעלה ג\"כ במוה\"ע<sup data-n=\"881\">1</sup> כנ\"ל באריכות וזהו ענין מצה שהיא חובה וד\"ל אך זהו רק בליל א' דפסח לבד מפני שבשעת חצות נגלה עליהם כו' וע\"כ חובה לאכול מצה קודם חצות לחם עני דוקא מטעם הנ\"ל אבל בז' הימים אכילת מצה רשות ולא חובה ולא מצוה דוקא אלא רשות דהוקשו לשביעי מה שביעי רשות כו' ולכאורה מה יש יתרון מעלה לז' ללמוד ממנו דוקא לו' הימים אך הטעם הוא מפני שהוא נקרא עצרת לה' כו' ע\"כ המצה בז' ודאי רשות והוקשו כולם אליו כו' והענין הוא משום דבקי\"ס היה ההארה מבחי' גאה גאה הנ\"ל שזהו למעלה גם מהתנשאות על ימות עולם והוא למעלה גם מהיות מקור לגלוי רצון ותענוג להאציל ולברוא כו' כנ\"ל ונקרא עולם הא\"ס עצמו ומ\"ש ה' מלך גאות לבש<sup data-n=\"882\">2</sup> שהוא בחי' מל' דא\"ס הוא בחי' האחרונה שבעולם הא\"ס ונקרא יום הז' שהוא רשות והיינו מפני שהוא בא מעולם החירות<sup data-n=\"883\">3</sup> שלמעלה ממקור ההשתלשלות (כשנת החמשים שנק' יובלא עילאה) שאין שם<sup data-n=\"884\">4</sup> חובה לאכול מצה שנק' מיכלא דמהימנותא כלל רק רשות ולא כליל הא' שהיא חובה וביאור הדברים הנה יש להקדים תחלה ענין זה בעבודת ה' בנשמת אדם בגופו כל ענין יצ\"מ ואכילת מצה כו' דהנה אמרז\"ל חייב אדם לראות א\"ע כאילו הוא יצא ממצרים<sup data-n=\"885\">5</sup> ובכל יום דוקא וכמ\"ש למען תזכור את כו' כל ימי חייך והענין הוא כידוע שבכל יום ויום יצרו של אדם מתגבר עליו<sup data-n=\"886\">6</sup> במחשבות רעות ומדות ומעשים רעים כי יצר לב האדם<sup data-n=\"887\">7</sup> רק רע מנעוריו וצריך לפשפש בחדרי לבבו ודעתו להתעורר באמת בתשובה שבלב לצאת מחשך ואפילה דרע ומות וטומאת הנפש דמדות ומ\"ז הגופניים וחומריים כבהמה ממש הנה זהו הנקרא יצ\"מ ממש בכל יום וזהו בא רק מצד בחי' נקודת יהדותו שלא יחפוץ לחיות כחיי הגוים מושקע ברע וקליפה לבלתי ידח<sup data-n=\"888\">8</sup> כו' ואמנם לא כל העתים שוות בזאת ההתעוררות בנפש בכל יום לפעמים מתעוררת באהבה מפני שחשקה נפשו ליוצרו ע\"כ ימאס ברע ולפעמים תתעורר מצד היראה שלא ירצה ליפרד מאחד כ\"כ כו' ומרגיז על נפשו עד שיתמרמר ביותר על ריחוקו העצום כידוע וזה תלוי לפי אופן התעוררות שפע שיומשך מלמעלה על הנשמות לפעמים בבחי' חסדים דאברהם אוהבי בימין מקרבת<sup data-n=\"889\">9</sup> כו' שמזה יבא התעוררות הנפש ע\"י אהבה וחשק לדבקה בה' כו' כנ\"ל ולפעמים יאיר מלמעלה בבחי' פחד דיצחק<sup data-n=\"890\">10</sup> בחי' הגבורות לעורר בנפש המרירות כו' כידוע וד\"ל וזהו ענין יצ\"מ שחייב אדם בכל יום שיש לו עבודה מיוחדת בכל יום באופן איך לצאת מנש\"ט כו' וגם בכל שבת ויו\"ט מזכירים יצ\"מ כמו בקידוש ובש\"ע דיו\"ט<sup data-n=\"891\">11</sup> שאומר מקרא קדש זכר ליצ\"מ כו' דגם שבשבת ויו\"ט הן בחי' עליות העולמות בכלל ובפרט בנש\"י כידוע מ\"מ חייב לצאת ממצרים כו' רק בזה הובדל יו\"ט דזש\"פ שנק' עצרת לה' כו' שמאיר בו מבחי' עולם החירות שהוא מעצמות אא\"ס ב\"ה שלפני ההשתלשלות לגמרי כנ\"ל עד שמחמת זה הגלוי הגדול יוכל גם כל איש זר ורחוק שנתרחק מאד מאור פני אלקים חיים",[["881","1","<b>במוה\"ע</b>: נסמן לעיל ב, א."],["882","2","<b>ה' מלך גאות לבש</b>: תהלים צג, א."],["883","3","<b>מעולם החירות</b>: ראה זהר משפטים קיד, רע\"א."],["884","4","<b>שם</b>: כ\"ה בדפו\"ר. ובמהדורת לעמבערג: שום."],["885","5","<b>חייב אדם. . ממצרים</b>: פסחים קטז, ב (במשנה)."],["886","6","<b>שבכל יום. . מתגבר עליו</b>: סוכה נב, סע\"א."],["887","7","<b>כי יצר לב האדם</b>: נח ח, כא."],["888","8","<b>לבלתי ידח</b>: שמואל-ב יד, יד."],["889","9","<b>דאברהם אוהבי בימין מקרבת</b>: ישעי' מא, ח. סוטה מז, א."],["890","10","<b>פחד דיצחק</b>: ויצא לא, מב."],["891","11","<b>ובש\"ע דיו\"ט</b>: עד\"ז מובא בכ\"מ ? ומהם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתפא. תקס\"ב ח\"ב ע' תקמו. מאמרי אדה\"א דברים ח\"ד ע' א'מד. אוה\"ת נ\"ך כרך ג ע' א'שכב."]]],[2800530081,"ע\"י חטאיו וכה\"ג עד שנמכר לעבד וגוי כו' שהן יו\"ד כתרי דמסאבותא<sup data-n=\"892\">12</sup> שנק' עבדים<sup data-n=\"893\">13</sup> כו' יוצא לחירות והוא מה שיוכל להתקרב לה' גם הוא ולקבל גלוי שכינה מה שאין זה לפי ערכו כלל לפי אופן מעשיו כל השנה ולא לפ\"ע עבודתו בקודש בתורה ותפלה כלל רק מצד עוצם הגילוי ממקום גבוה מאד נעלה כזה שנקרא עולם החירות חירו דכולא<sup data-n=\"894\">14</sup> ששם גם העבדים יוצאים לחירות והכל יכולים לקבל ולהתקרב גם שאינו ראוי כראוי כענין ראתה שפחה על הים כו' שגם שפחה שהיא בבחי' ק\"נ<sup data-n=\"895\">15</sup> כידוע בענין עבד ושפחה כו' ראתה מה שלא ראה כו' וד\"ל. ועיקר הענין הוא כנ\"ל בענין עצרת כו' שהוא פרנסה לאביהם שבשמים לבחי' פנימית אבא שהוא פנימית ע\"י ששם מאיר מסוף עולם הא\"ס שנק' עולם החירות כנ\"ל מבחינת גאה גאה כו' שזה אור השפע אינו נק' חובה אלא רשות כו' דבליל הא' שבא השפע ופרנסה במצה למל' להמתיק הדינין הנאחזים בה לפי\"ע המיתוק והבירור דרפ\"ח כו' נקרא חובה כנ\"ל רק שזה בא מבחי' מוחין דאבא בקטנות כנ\"ל וגם בחי' המצה למעלה מזה והוא להמשיך מוחין חדשים בז\"א גם זה בא בדרך חובה בהיות כי צריך לבוא באופן שיהיה תוס' אורות בכלי' דחב\"ד דז\"א שמקבל מאו\"א ועד\"ז גם למוחין דאו\"א עד גם בחי' חכמה דאבא עצמה כמו שורש נשמת משה ששרשו בבחי' מ\"ה דאור אבא כמ\"ש ונחנו מה<sup data-n=\"896\">16</sup> היה עליו חובה במצה בליל א' כנ\"ל וכך הוא למעלה באור ושפע שבא כסדר ההשתלשלות מא\"א וע\"י לאו\"א כו' במד' ושיעור כו' שהרי אנו אומרים מצה זו שאנו אוכלים ע\"ש מה פי' ע\"ש מ\"ה דחכמה שרש כל נש\"י כו' וא\"כ ה\"ז חובה ולא רשות (כי גם יש אחיזה לגבורות קשות בז\"א עד מדות שבבינה דמינה דינין מתערין<sup data-n=\"897\">17</sup> כו' וצריך מיתוק ובירור כענין מים אחרונים חובה כנ\"ל) אבל למעלה מעלה מכל עיקר ההשתלשלות דמל' דא\"ס בנאצלי' שזהו מבחי' האחרונה שבעולם הא\"ס עצמו כנ\"ל שזהו קודם שעלה ברצונו ומחשבתו להאציל שיכול להאציל באופן אחר לגמרי כו' (כנ\"ל בענין גאה גאה שהוא בבלתי מוגבל למעלה ולמטה כלל) ולשנות סדר הראשון מן הקצה לקצה כמו קי\"ס שההעלם נעשה גילוי וכה\"ג הרי גם בחי' אור ושפע הפרנסה דמצה שמפרנס לפנימי' החכמה שנקרא אביהם שבשמים שנקרא עצרת להוי' למעלה מעלה ממש וה\"ז בא בבחי' החירות שמעולם החירות דעצמות אא\"ס שלא שייך שם ענין חובה להמתיק דינין או להוסיף אור ומוחין חדשים כו' מאחר שנבדל ומרומם לבדו כו' כנ\"ל בענין גאה גאה כו' וד\"ל. וזהו שאמרו מה שביעי רשות משום דזש\"פ נקרא עצרת לה' שלזה לא נזכר בו עבודה להיותו למעלה מעלה מבחי' עבודת הבירורים דרפ\"ח כו' כנ\"ל אלא לא תעש' מלאכה כלל ע\"כ המצוה דמצה בו רשות ולא חובה כלל להיותו מבחי' עולם החירות חירו דכולא (כיו\"כ שנק' שבת שבתון<sup data-n=\"898\">18</sup> וכמו כל יובל כידוע) והוקשו כל הו' ימים אל יום זש\"פ להיות גם הם רשות ולא חובה כי ו' ימים אלו מקבלים מבחי' ו\"ק דאבא שמשפיעי' למל' והמ' בעצמ' בשרשם עולי' בזש\"פ לקבל פרנס' מעול' החירות דזש\"פ",[["892","12","<b>יו\"ד כתרי דמסאבותא</b>: נסמן לקמן קמז, א."],["893","13","<b>כתרי. . עבדים</b>: ראה זהר וישלח קסו, ב."],["894","14","<b>חירו דכולא</b>: זהר תצוה קפג, א."],["895","15","<b>שפחה. . ק\"נ</b>: ראה בהערה כתרי."],["896","16","<b>ונחנו מה</b>: בשלח טז, ז. ח."],["897","17","<b>שבבינה דמינה דינין מתערין</b>: נסמן לקמן קכד, ב."],["898","18","<b>כיו\"כ שנק' שבת שבתון</b>: אחרי טז, לא. אמור כג, לב."]]],[2800530082,"ע\"כ גם בו' ימים דפסח הוקש' לז' להיות גם הם רשות ולא חובה כליל א' דפסח לפי שנכללו בזש\"פ בעלותם בבחי' עצרת להוי\"ה כו' עד בחי' מל' דא\"ס שלפני הקו\"ח שנק' יום הז' עצרת למעלה ממש שנק' סוף עולם הא\"ס עצמו כנ\"ל ובזה מתורץ הקושיא דלעיל על מ\"ש לשון הוקשו ו' ימים ליום הז' כו' דדוקא ע\"י יום הז' הוא שנעשים גם הם רשות ולא חובה ואע\"פ שבו' ימים אלו נמשך פרנסה למל' ממוחי' דאבא בקטנות אבל בעצם מהותם הרי הם בבחי' רשות מצד שהוקשו ליום הז' כנ\"ל וד\"ל:\n(כב) <b>ולהבין</b> בתוס' ביאור<sup data-n=\"899\">1</sup> ענין ביום הז' עצרת לה' כו' יש להקדי' ענין א' והוא בענין התבוננות מאין ליש שזה גם חסידי אוה\"ע<sup data-n=\"900\">2</sup> משיגים ומאמינים וקרו לי' אלקא<sup data-n=\"901\">3</sup> כו' ולמה נתייחד האמונ' לכנ\"י דוקא שמטעם זה נקרא המצה מיכלא דמהימנותא כנ\"ל והנה יש להקדים שיש ג' מדריגות בכלל בג' עולמות דבי\"ע נשמות ומלאכים וע' שרים<sup data-n=\"902\">4</sup> וכ\"א כלול מכמה מדריגות בעילוי אחר עילוי כו' ויש להבין תחלה ענין מדריגה התחתונה שזהו בחי' ע' שרים והוא שמכירים לבוראם בהשגה גמורה איך שמתהווים מאין ולמטה היינו דקרו לי' אלקא דאלקייא ואו' שירה ומשתחוים<sup data-n=\"903\">5</sup> באימה וביראה בקבלת עול מ\"ש וכמ\"ש מי לא יראך<sup data-n=\"904\">6</sup> מלך הגוים וכתיב מלך אלקים על גוים<sup data-n=\"905\">7</sup> וכן הבו לה' משפחות עמים<sup data-n=\"906\">8</sup> כל העמים תקעו כף הריעו לאלקים<sup data-n=\"907\">9</sup> וכה\"ג רבים בכתובים כמו הללו ה' כל גוים<sup data-n=\"908\">10</sup> כו' וכתיב יראו מה' כל הארץ ממנו יגורו<sup data-n=\"909\">11</sup> כו' שיש ביטול ופחד אלקים בכל הארץ ועכ\"ז אנו רואים ההיפוך גם כן והוא מה שהן בבחי' פירוד גמור ליש ודבר בפ\"ע עד שיכולים למרוד כשר של מצרים שאמר מי ה'<sup data-n=\"910\">12</sup> אשר אשמע בקולו כו' וכה\"ג בסנחרב<sup data-n=\"911\">13</sup> ורבים כיוצא בהם וכאמרם יודעים רבונם ומתכוני' למרוד<sup data-n=\"912\">14</sup> כו' וכן יש בבני אדם בגופים חומריי' לפעמים יהיה בו פחד אלקים וישוב בתשובה ויאמר שירות ותשבחות בביטול גדול כו' ולפעמים ילך בדרך עקלתון ויגבה לבו עד שיכול להיות נפרד גמור בפריקות עמ\"ש לגמרי לעשות הרע כמלכי ישראל וכה\"ג בכל דור ודור יש צדיקים ויש רשעים כו' וגם בינונים זה וזה שופטן<sup data-n=\"913\">15</sup> כו' כידוע אלא צ\"ל דעה\"ד טו\"ר מחמת חטא אדה\"ר שנמשך זוהמ' דנחש הקדמוני<sup data-n=\"914\">16</sup> כו' נתגב' הרע על הטו' והוא ק\"נ שרובו רע<sup data-n=\"915\">17</sup> ומיעוטו טוב וגם זה בא בתערוב' וערבובי'<sup data-n=\"916\">18</sup> גדול' ע\"כ חילוף זה מטוב לרע ומרע לטו' מתחלף משעה לשעה לפעמים כך ולפעמים בהיפך וחוזר כך בשנוי ע\"ד שאמר רשעים מלאים חרטות<sup data-n=\"917\">19</sup> שחוטא וחוזר ושב ומתחרט וחוזר ומתחרט עד שמלא חרטות כו' וד\"ל וכה\"ג בשרים דק\"נ בהתלבשותם באוה\"ע מעורבי' מאד טו\"ר לפעמים מתגבר הרע ומורד ולפעמים יגבור הטוב ויהיה לו פחד ויראה וכשרו של עשו<sup data-n=\"918\">20</sup> כו' וכ\"ז בבחי' כו\"מ שמקבלים משמרי האופנים<sup data-n=\"919\">21</sup> אבל האופנים וחיות הקדש המה בבחי' ביטול לאלקות תמיד מבלי שימצא בהן בחי' פירוד כלל וכמ\"ש וצבא השמים לך משתחוים<sup data-n=\"920\">22</sup> תמיד וברעש גדול אומ' שירה תמיד ומקבלים עליהם עמ\"ש ביראה תמיד לפי שבחי' התפעלות אלקו' שבהם בא מגלוי אור האלקי עליהם ביותר בלי הסתר וצמצום כ\"כ כמו בע' שרי' דנגה דעשי' ע\"כ יש בהם בחי' הביטול",[["899","1","<b>ולהבין בתוס' ביאור</b>: הבא להלן (פרקים כב-כח) מיוסד על סידור שחה\"מ רפז, ב ואילך."],["900","2","<b>חסידי אומה\"ע</b>: ראה גם סידור כאן רפז, ב. לקמן מט, א. ב."],["901","3","<b>וקרו לי' אלקא</b>: מנחות בסופה."],["902","4","<b>וע' שרים</b>: ראה זהר בראשית מו, סע\"ב. סידור שער המילה קמה, ג. הנסמן במ\"מ לשע\"ת עד, א."],["903","5","<b>ע' שרים. . שירה ומשתחוים</b>: ראה גם לקמן קמו, ב ובהנסמן במ\"מ לשם."],["904","6","<b>מי לא יראך</b>: ירמי' י, ז."],["905","7","<b>מלך אלקים על גוים</b>: תהלים מז, ט."],["906","8","<b>הבו לה' משפחות עמים</b>: תהלים צו, ז. דהי\"א טז, כח."],["907","9","<b>כל העמים. . לאלקים</b>: תהלים מז, ב."],["908","10","<b>הללו ה' כל גוים</b>: תהלים קיז, א [ושם: את ה' ? ראה מאמרי אדה\"א שמות ח\"ב ע' שיח]."],["909","11","<b>יראו מה'. . יגורו</b>: תהלים לג, ח."],["910","12","<b>כשר. . מי ה'</b>: וכ\"ה לקמן מט, א. שמות ה, ב [ושם: פרעה]."],["911","13","<b>סנחרב</b>: ראה מלכים-ב יח, יט ואילך. ישעי' לו, ד ואילך."],["912","14","<b>יודעים רבונם ומתכוני' למרוד</b>: ראה תו\"כ בחוקותי כו, יד. הנסמן במאמרי אדה\"א בראשית ע' צח."],["913","15","<b>בינונים זה וזה שופטן</b>: ברכות סא, ב. ראה גם מאמרי אדה\"ז הקצרים ע' שיז ואילך. שע\"ת ח\"ב ב, ג (ספ\"א). כא, ב. ד\"ח שער התפלה פס\"ח-פ\"ע."],["914","16","<b>דעה\"ד. . זוהמ' דנחש הקדמוני</b>: ראה שבת קמו, רע\"א."],["915","17","<b>ק\"נ שרובו רע</b>: ראה גם לקמן קמז, ב ובהנסמן במ\"מ לשם."],["916","18","<b>ק\"נ. . בתערוב' וערבובי'</b>: ראה גם לקמן פ, א. שע\"ת ח\"ב מה, ד."],["917","19","<b>רשעים מלאים חרטות</b>: ראה תניא ספי\"א. הנסמן במאמרי אדה\"א דברים ח\"ב ע' שסה. דרשות התורה [לרש\"ט אבן שם טוב פאדואה שכ\"ז] תולדות יד, א. אברבנאל שמו\"ב יג, טו. וראה גם לקמן פ, ב."],["918","20","<b>וכשרו של עשו</b>: וישלח לב, כה ואילך."],["919","21","<b>כו\"מ שמקבלים משמרי האופנים</b>: נסמן לקמן קיא, ב."],["920","22","<b>וצבא השמים לך משתחוים</b>: נסמן לקמן קיב, ב."]]],[2800530083,"יש לאין בהתפעלות תמידית בלי הפסק כלל משא\"כ בע' שרים דק\"נ שאור האלקי מוסתר בהם ביותר כמ\"ש אתה אל מסתתר<sup data-n=\"921\">23</sup> עד שמרחוק מאד מכירי' לבוראם והגם דקרו ליה כו' היינו בקריאה בפה לבד שמודים כולם שהוא מקור כל התהוות יש מאין ומאמיתת מציאותו נמצאו הכל<sup data-n=\"922\">24</sup> כו' שנק' כח הפועל בנפעל כידוע ועכ\"ז אין בהם התפעלות האלקו' בביטול במציאות כמלאכים רק בהשגה מרחוק לבד לפי שאין האלקי מאד מוסתר מהם ע\"כ לא בא אליהם רק בבחי' הודאה מרחוק בלבד כו' לכך יוכלו לבא לבחי' פירוד גמור גם כן כנ\"ל וכך הוא בגוף האדם למטה כו' אבל המלאכים קרובים לאור האלקי שכח האלקי אינו בא בהסתר בהם ומכירים התהוותם מאין האלקי בגלוי גמור (כמו לע\"ל שידע כל פעול כא\"פ<sup data-n=\"923\">25</sup> כו') ע\"כ יש בהם הביטול במציאות בהשתחוואה תמידי' כנ\"ל כי יש להם קרבת אור האלקי בפנימית ועצמות אלקות יותר וד\"ל ונמצא דגם שכ\"ז רק בבחי' התפשטות אור האלקי להחיות מאין ליש בלבד שאין זה רק בחי' מציאותו ולא מבחי' מהותו כלל כידוע עכ\"ז יש בזה ב' מדריגות שרחוקים זו מזו כמו מן הקצה לקצה כי הע' שרים דק\"נ יוכלו להיות בבחי' פירוד גמור מעוצם ריחוקם מאור האלקי ומלאכי' דעשי' הם תמיד בביטול במציאות כנ\"ל (וכענין הבו לה' בני אלים<sup data-n=\"924\">26</sup> מלאכי' דעשי' הבו בבחי' ביטול וג\"פ הבו ג' מדריגות דבי\"ע שבכל עולם כו' ובחי' ק\"נ שנק' משפחות עמים ג\"כ אמ' הבו לה' משפחו' כו' אבל רק לפרקי' כשאומרי' שירה כנ\"ל) והמדריגה הג' הן הנשמות ששרש' בעצמו' אלקו' ממש כידוע שנר הוי\"ה ממש נשמת אדם<sup data-n=\"925\">27</sup> והמלאכים נק' בני האלקים וכמ\"ש ויריעו כל בני האלקים<sup data-n=\"926\">28</sup> כידוע והענין הוא כידוע שבדרך כלל יש ב' מדריגות באלקות אחד בחי' מציאותו שהוא בחי' אור התפשטותו לבד להמשיך מאין ליש ונק' כח הפ\"ב כנ\"ל ומשם מקבלים המלאכים וכמו וברוח פיו כל צבאם<sup data-n=\"927\">29</sup> מבחי' אותיות הדיבור לבד אבל הנשמות בבחי' מהות ועצמות דאלקות וכענין ישראל עלה במח' פי' במח' העצמית שלמעלה מגלוי הדיבור די' מאמרות וע\"כ יש בנשמה בחי' ביטול עצמי כניצוץ הנמשך אחר השלהבת מאחר שנק' נר ה' ממש שלמעלה מהתפעלות וביטול היש לאין דמלאכים בכל עולם ועולם לפי ערכו וזהו ענין מס\"נ דנשמות באחד<sup data-n=\"928\">30</sup> על קדה\"ש שזהו בחי' התכללות לגמרי במהו\"ע אלקות דוקא משא\"כ ביטול המלאכים אינו רק בכח אלקי המהוה אותן מאין ליש כידוע וד\"ל ונמצא יש ג' מדריגות בכלל נשמות ומלאכים וע' שרים ונק' נר\"נ בכלל בחי' נפש הוא בבחי' חיצוניות דנוגה כביטול הע' שרים שיש בהם גם הפירוד לפעמים כנ\"ל ובחי' רוח הן המלאכים כמ\"ש עושה מלאכיו רוחות<sup data-n=\"929\">31</sup> כו' שהן בביטול תמידי כנ\"ל ונשמו' הן בבחי' עצמיו' הביטול בבחי' פנימי' אלקו' כנ\"ל ויש בכל עולם בחי' נר\"נ שנק' בי\"ע<sup data-n=\"930\">32</sup> שכל עולם מג' עולמו' דבי\"ע כלול מבי\"ע<sup data-n=\"931\">33</sup> מנר\"נ כידוע ויש בכ\"א מהם מדריגות חלוקות זו למעלה מזו (עד שגם נשמות כלולים מנר\"נ<sup data-n=\"932\">34</sup> כמ\"ש בראתיו יצרתיו אף עשיתיו<sup data-n=\"933\">35</sup> ובחי' נפש דעשי' גבוה מפנימי' דמלאכים דעשי' וחיצוני' דמלאכים דעשי' גבוה מפנימי' דנוגה שבעולם דעשי' כו') ובדרך כללות נשמה בבריא' ורוח דמלאכים ביצי' ונפש בעשי' עד נפש הגלגלים דעשי' כו' ואמנם מתחלקי' לריבוא רבבות מדריגות",[["921","23","<b>אתה אל מסתתר</b>: ישעי' מה, טו."],["922","24","<b>ומאמיתת מציאותו נמצאו הכל</b>: ראה רמב\"ם ריש הל' יסוה\"ת."],["923","25","<b>שידע כל פעול כא\"פ</b>: תפלת העמידה לר\"ה."],["924","26","<b>הבו לה' בני אלים</b>: תהלים כט, א. ראה פע\"ח (שער השבת) שי\"ח פ\"ח. מאמרי אדה\"א בראשית ע' מו. וש\"נ."],["925","27","<b>שנר הוי\"ה. . נשמת אדם</b>: משלי כ, כז."],["926","28","<b>ויריעו כל בני האלקים</b>: איוב לח, ז [ושם: אלקים]. ראה גם אגה\"ת פ\"ד. מאמרי אדה\"א במדבר ח\"ב ע' תתמח. וש\"נ. דברים ח\"ב ע' ת. וש\"נ."],["927","29","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו. ראה גם אגה\"ת שם. מאמרי אדה\"א הנחות תקע\"ז ע' קכ. וש\"נ."],["928","30","<b>מס\"נ דנשמות באחד</b>: ראה זהר (רע\"מ) משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["929","31","<b>עושה מלאכיו רוחות</b>: תהלים קד, ד."],["930","32","<b>נר\"נ שנק' בי\"ע</b>: ת\"ז סתכ\"ח (סח, סע\"ב)."],["931","33","<b>שכל עולם. . כלול מבי\"ע</b>: ראה ע\"ח (שער כללות אבי\"ע) שמ\"ב פ\"ד."],["932","34","<b>נשמות כלולים מנר\"נ</b>: ראה תניא פ\"ב."],["933","35","<b>בראתיו. . עשיתיו</b>: ישעי' מג, ז."]]],[2800530084,"בכל עולם ועולם בעילוי אחר עילוי לפי סדר ההשתלשלות עו\"ע שמקבלים דין מן דין<sup data-n=\"934\">1</sup> כו' עד שמדריגה התחתונה דעולם הבריאה שהוא בחי' נפש נעשה בחי' נשמה ביצירה ונפש דיצי' נעשה נשמ' בעשי' (שהוא השתלשלות בנשמו' דבי\"ע ועד\"ז הוא ההשתלשלו' עו\"ע ברוחו' דמלאכים ובנוגה דבי\"ע כו' וד\"ל) (ובמ\"א מבואר זה הענין בלשון אחר והוא שיש ג' מדריגו' בכל עולם והוא בחי' אור וכלי ולבוש אור בחי' נשמה אור הוי' והכלי הוא בחי' אלקי' דהיינו בחי' רוח דמלאך וחונה מלאך ה' סביב ליראיו<sup data-n=\"935\">2</sup> שהן הנשמות וע\"כ היש דמלאך בטל תמיד לאין שנק' כלי שטפל ובטל לגבי אור והלבוש הוא בחי' חיצוני נפרד והוא בחינת נוגה שבכל עולם כו' שאין היש בטל לאין תמיד רק לפרקים כנ\"ל כמו יגיה חשכי<sup data-n=\"936\">3</sup> כו' כאור הנראה בענן חשך כו' ובחי' אחרונה שבעליון הוא נעשה ראש ופנימי' בתחתון אבל לא שמבחי' לבוש נוגה דבריאה יהי' נשמה דיצי' וכה\"ג מנוגה דיצי' נשמה בעשי' אלא מבחי' נר\"נ דאור נשמה דבריאה מבחי' נפש דבריאה יהי' נשמה ביציר' ומנפש דיצירה נשמה בעשיה ועד\"ז בכלים דמלאכי' מבחי' עשי' דבריא' נעשה בריא' דיצי' ומלאכי' דעשי' דיצי' נעשה מלאכי' דבריא' שבעשי' ועד\"ז בנוגה דבי\"ע שבכל עולם יורד ומשתלשל עד נפש דעשי' שבעשי' ורוח ונוגה דעשי' שבעשי' שהוא<sup data-n=\"937\">4</sup> או\"כ ולבוש דעשי' שבעשי' והוא כמו נשמת האדם בעוה\"ז בגופו שנק' בחי' נפש דעשי' דעשי' שיש כלי לאור נשמתו זאת והוא המלאך שלו וגופו מנוגה דעשי' שבעשי' כו' וד\"ל) (ואמנ' גם נפש דנפש דעשי' כלול מבי\"ע<sup data-n=\"938\">5</sup> נר\"נ דכללו' וזהו שאו' בראת יצרת נפחת בי<sup data-n=\"939\">6</sup> כו' עד נשמה דבריאה בכלל וממילא כלול מרוח ונפש דמלאכים ונוגה דבריאה וזהו שבינונים זו\"ז שופטן כו' וד\"ל) (וז\"ש ושבתם וראיתם<sup data-n=\"940\">7</sup> בין צדיק לרשע כו' בחי' אור שהוא הנשמה נקרא צדיק כמ\"ש אור זרוע לצדיק<sup data-n=\"941\">8</sup> כי טוב<sup data-n=\"942\">9</sup> כו' ורשע הוא בבחי' לבוש נפרד דבחי' נוגה שרובו רע ובין עובד אלקים כו' הוא בחי' הכלי לאור כמלאכים שנקר' עובדי אלקים דוקא לאשר לא עבדו<sup data-n=\"943\">10</sup> כאשר אין בכלי ביטול לאור במלאכים שנקר' נפילים<sup data-n=\"944\">11</sup> וכה\"ג ויש כמ\"כ בכלים של נשמות שבגופים שיש עובד אלקים ויש שלא עבדו אבל אינו בכלל רשע והוא בחי' בינונים שזו\"ז שופטן וכה\"ג וד\"ל<sup data-n=\"945\">12</sup> :\n(כג) <b>אך</b> באמת לפ\"ז מוחלט הדבר שהנשמה בבחי' צדיק וטוב והגוף שמעורב ברע דק\"נ בבחי' רשע והממוצע שזו\"ז שופטן כו' והרי אנו רואים שיש בנשמות ג\"כ חילוק בין צדיק לרשע כמו נפש החוטאת<sup data-n=\"946\">13</sup> שהנפש האלקי' היא החוטאת וכמ\"ש ונפש כי תחטא<sup data-n=\"947\">14</sup> ונקרא נפש רשע<sup data-n=\"948\">15</sup> כמו שנראה בעליל בטבע נפשות הרשעים שנאמר ונר רשעים ידעך<sup data-n=\"949\">16</sup> כו' שהאור האלקי שבהם חשוך ונטמא בטומאת העון עד שימות ברשעתו ותלך הנפש ההיא לבאר שחת<sup data-n=\"950\">17</sup> וכמו ונכרתה הנפש ההיא מעמיה<sup data-n=\"951\">18</sup> הכרת תכרת הנפש<sup data-n=\"952\">19</sup> בעון שחייב כרת וכן חייבי מיתות ב\"ד כו' וכן לע\"ל נאמר אלה לחיי עולם<sup data-n=\"953\">20</sup> ואלה לחרפות כו' דקאי בנשמות שהולכות לחרפות עולם כו'",[["934","1","<b>שמקבלים דין מן דין</b>: ת\"י ישעי' ו, ג."],["935","2","<b>וחונה. . סביב ליראיו</b>: תהלים לד, ח."],["936","3","<b>יגיה חשכי</b>: שמואל-ב כב, כט. תהלים יח, כט."],["937","4","<b>שהוא</b>: כ\"ה בדפו\"ר. ובמהדורת לעמבערג: שהוי'."],["938","5","<b>נפש. . כלול. . מבי\"ע</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' רב."],["939","6","<b>שאו' בראת. . בי</b>: ראה ברכת אלקי נשמה."],["940","7","<b>ושבתם וראיתם</b>: מלאכי ג, יח."],["941","8","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["942","9","<b>לצדיק כי טוב</b>: ישעי' ג, י."],["943","10","<b>ובין עובד אלקים. . לאשר לא עבדו</b>: המשך הכתוב ושבתם."],["944","11","<b>במלאכים שנקר' נפילים</b>: בראשית ו, ד. ראה גם בענין הנפילים מאמרי אדה\"א ויקרא ח\"ב ע' תקלה. קונטרסים ע' רלד וע' שעג ובהנסמן בהנ\"ל. לקמן מא, ב."],["945","12","<b>וד\"ל</b>: אוצ\"ל: וד\"ל)."],["946","13","<b>נפש החוטאת</b>: יחזקאל יח, ד, כ [ושם: הנפש]."],["947","14","<b>ונפש כי תחטא</b>: ויקרא ה, א."],["948","15","<b>נפש רשע</b>: משלי כא, י."],["949","16","<b>ונר רשעים ידעך</b>: משלי יג, ט."],["950","17","<b>לבאר שחת</b>: תהלים נה, כד."],["951","18","<b>ונכרתה. . מעמיה</b>: לך יז, יד."],["952","19","<b>הכרת תכרת הנפש</b>: שלח טו, לא."],["953","20","<b>אלה לחיי עולם</b>: דניאל יב, ב."]]],[2800530085,"וכנשמות שאין להם חלק לעוה\"ב<sup data-n=\"954\">21</sup> בעונות ידועים שמזה נראה שיש טו\"ר בעצם הנשמות מפני שנפלו בעה\"ד טו\"ר ויש שיצאו בבחי' רע גמור כנשמו' שהיו במצרים שלא יצאו לטוב רק חלק החמשים<sup data-n=\"955\">22</sup> וכן בדורות הראשונים שלפני אברהם ויצחק היו נשמות טובות וקדושות מאד כנשמת חנוך ומשותלח ונח ונשמות גבוהות שהיו בבחי' רע כדור הפלגה<sup data-n=\"956\">23</sup> וכנמרוד<sup data-n=\"957\">24</sup> כו' עד גם המלאכים שנק' בני האלקים נפלו ברע גמור ונקר' נפילים כמ\"ש ויראו בני<sup data-n=\"958\">25</sup> כו' וכך בכל דור יש נשמות צדיקים בטבע תולדתם ויש נשמות רשעים בטבע תולדתם אע\"ג דצדיק ורשע לא קאמר<sup data-n=\"959\">26</sup> היינו בדבור לבד כמה שכתוב במ\"א וא\"כ מ\"ש ושבתם וראיתם בין צדיק ורשע היינו בשרש תולדתם כמו שיצאו מלמעלה למטה וכן במלאכים יש מלאכים טובים ומלאכים רעים עד למטה שנקרא יצר טוב ויצר הרע דבינונים זו\"ז שופטן כו' אלא צריך לומר דהנשמה בירידתה למטה באה בלבוש דנוגה מעורב טו\"ר שמצד זה יש נשמות טו\"ר צו\"ר וכן מלאכים טו\"ר כו' וזהו צדיק וטוב לו צדיק ורע לו וכן רשע וטוב לו רשע ורע לו<sup data-n=\"960\">27</sup> ויש בינונים שזו\"ז שופטן טו\"ר כו' לפי שהאור מורכב בכלי והכלי בלבוש דנוגה דטו\"ר ממש ולפ\"ז יכול להיות דרשע ולבוש טוב לו יותר נעלה מצדיק וטוב לו לפי שלבוש דנוגה שלו מבחי' הטוב דנוגה שהוא בא מעולם העליון יותר שיותר גבוה מנשמה דצדיק וטוב לו דעולם התחתון אם לבושו מנוגה דעולם שלו דטוב דנוגה דבריאה יותר עליון מנשמה טובה דיצירה כעלה או קליפה פרי טוב שבאילן יותר טוב מפרי הגס כו' וראיה מן רשע בן צדיק וצדיק בן רשע כו' ויובן זה מתשובת הרשעים שנהפך רע דנוגה שלהם לטוב יעלו יותר מנשמות הצדיקים בטבעם ותולדתם ואפשר מטעם דקליפה קדמה לפרי<sup data-n=\"961\">28</sup> כמ\"ש ואלה המלכים<sup data-n=\"962\">29</sup> כו' שיש שרש ללבוש חשמ\"ל דנוגה למעלה יותר נעלה מבחינת האורות דתיקון שמשם מחצב הנשמות וע\"כ יתעלה הנשמה מצד תיקון הגוף בעבודה שבלב בשר דוקא או ע\"י ביטוש הגוף סליק נהורא דנשמתא<sup data-n=\"963\">30</sup> דוקא וכמשי\"ת ב\"ה וד\"ל והנה ידוע שהנשמה עצמה א\"צ תיקון<sup data-n=\"964\">31</sup> כי הרי היא מבחי' אורות דשם מ\"ה דתיקון (עד נפש דנפש דעשי' גם היא יש לה שרש בחיצוניות הכלים דאורות דז\"א שהוא שם מ\"ה דאצי' כמ\"ש מה שמו<sup data-n=\"965\">32</sup> כו' וד\"ל) וכמבואר למעלה שבנשמות הוא ביטול עצמי במהו\"ע אלקות שלמעלה מבחי' ההתפשטות אור דכהפב\"נ כו' שנק' השגת המהות ולא השגות המציאות לבד (ולא כנשמות שנהנין מזיו<sup data-n=\"966\">33</sup> בג\"ע בהשגת שכל כו') אך עיקר ירידתה למטה הנה הוא כדי לברר לבחינת לבוש דנוגה שמעורב טו\"ר דהיינו גוף החומרי שנלקח מק\"נ שמשם שרש ע' שרים שלמטה כנ\"ל ולהבין זה איך יתחבר אור הנשמה שהיא דבוקה וקשורה במהו\"ע אלקות בצרור החיים את ה' ממש בגוף חומרי מלא תאוות בהמה גשמיית ולהיות בה כח לברר ולהפך חושך חומר הגוף לאור אלקי עד שאמר בזהר דמאן דלא מהפך<sup data-n=\"967\">34</sup> חשוכא לנהורא כו' בהאי עלמא לית ליה חולקא בההוא עלמא שהטעם הוא כי כאשר הפך חומר הגוף בעוה\"ז",[["954","21","<b>וכנשמות שאין להם חלק לעוה\"ב</b>: סנהדרין צ, א (במשנה)."],["955","22","<b>כנשמו' שהיו במצרים. . חלק החמשים</b>: מכילתא בשלח יג, יח."],["956","23","<b>ונשמות גבוהות. . כדור הפלגה</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' עב."],["957","24","<b>ונשמות גבוהות. . וכנמרוד</b>: ראה גם לקו\"ת להאריז\"ל לך יד, א [עה\"פ ויהי בימי אמרפל]."],["958","25","<b>ויראו בני</b>: בראשית ו, ב. ראה הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשס."],["959","26","<b>דצדיק ורשע לא קאמר</b>: ראה גם לקמן קלה, א ובהנסמן במ\"מ לשם."],["960","27","<b>צדיק וטוב. . ורע לו</b>: ברכות ז, א."],["961","28","<b>דקליפה קדמה לפרי</b>: ראה לקמן קמו, סע\"ב ובהנסמן במ\"מ לשם."],["962","29","<b>ואלה המלכים</b>: וישלח לו, לא."],["963","30","<b>ביטוש. . נהורא דנשמתא</b>: ראה זהר שלח קסח, א."],["964","31","<b>שהנשמה עצמה א\"צ תיקון</b>: ראה תניא פל\"ז (מח, ב) בע\"ח שער כ\"ו [שער הצלם פ\"א]. הנסמן במאמרי אדה\"א בראשית ע' עד? קונטרסים ע' שעח. שע\"ת ח\"ב סז, ב."],["965","32","<b>מה שמו</b>: שמות ג, יג."],["966","33","<b>כנשמות שנהנין מזיו</b>: ראה ברכות יז, א."],["967","34","<b>דמאן דלא מהפך</b>: ראה זהר בהקדמה ד, א. מאמרי אדה\"א בראשית ע' קפ. דברים ח\"ג ע' א'ס ובהנסמן בהנ\"ל."]]],[2800530086,"דוקא זוכה עי\"ז הנשמה לידבק וליכלל במהו\"ע אלקות בההוא עלמא שהוא העוה\"ב שנחיה לפניו<sup data-n=\"968\">1</sup> ממש בהשגת מהותו ולא מציאותו לבד כמו שאמר לע\"ל כל אחד מראה באצבעו<sup data-n=\"969\">2</sup> לומר הנה אלקינו זה<sup data-n=\"970\">3</sup> לנוכח במהות אמיתת עצמותו שבהשגת מציאותו לא יתכן לומר לשון זה שאינו אמיתת עצמותו וע\"כ אמר דלית מת\"ב כלל<sup data-n=\"971\">4</sup> כידוע ועוד יש להבין מה שאמרו בזהר דגופא דלא סליק ביה נהורא דנשמתא מבטשין ליה וסליק ביה<sup data-n=\"972\">5</sup> כו' דלכאורה איך יש חיבור ויחוס ערך לנשמה עם הגוף עד שבביטוש הגוף יתעלה אור האלקי שבנשמה בעילוי יותר כו' וכן יובן מענין התשוב' מעומקא דלבא שזהו עיקר ענין לאהפכא חשוכא לנהורא ומרירו למיתקא שהוא הרע גמור דק\"נ כו' עי\"ז דוקא יעלה אור הנשמה ביתרון מעלה מאור נשמות הצדיקים בעצם מדריגתם באור פני מלך חיים<sup data-n=\"973\">6</sup> כו' וכ\"ז יפלא מאד וביותר ממאמר הידוע דכד אתכפיא סט\"א<sup data-n=\"974\">7</sup> אסתלק יקרא דקוב\"ה בכ\"ע מהו ענין סילוק יקרא זה ע\"י דבר נמוך כזה שהוא הפיכת חשך הגס דסט\"א או אתכפיא סט\"א בלבד כו' אך הנה יש להקדים מ\"ש איוב מבשרי אחזה אלוה<sup data-n=\"975\">8</sup> דיפלא מאד איך יחזה אלוה בראיית המהות מבשרי דוקא שהבשר הרי הוא הדם שבלב הממולא כל אש תאוה זרה ורוח שטות כבהמה ממש איך משם יחזה אלוה דוקא ויש להקדים לזה מ\"ש אתה הראת לדעת<sup data-n=\"976\">9</sup> מהו לשון הראת דמשמע שיצא מן ההעלם לגלוי והרי הנשמה כבר היתה למעלה בגלוי אור זרוע לצדיק עליון באוצר הנשמות<sup data-n=\"977\">10</sup> כו' אלא הראית זה היינו ירידת אור הנשמה למטה בגוף חומרי דק\"נ שזהו לדעת כי ה' כו' שבזה יהיה יתרון עילוי לנשמה יותר משרשה בפנימית אלקים חיים<sup data-n=\"978\">11</sup> כו' וזה פלא גדול איך מהדעת גשמי וגופני שתדע הנשמה בגופה כי ה' כו' תעלה כ\"כ אמנם הנה באמת יש להבין במהות הנשמה האלקי' שבודאי יש בה בינה ודעת אלקי טרם בואה לגוף וכמו נשמת שדי תבינם<sup data-n=\"979\">12</sup> וכמו בחינת ההשגה האלקית שבנשמה בג\"ע שנהנין מזיו כו' אם הוא כמו ההשגה האלקית שבנשמה בהתלבשותה בגוף שתבין ותשכיל בהתבוננות מאין ליש וכה\"ג ותתפעל באוי\"ר אלקי' ממש הרי הנשמה מצד עצמה ומהותה היא נמשכת ונדבקת במוה\"ע אלקות כניצוץ כו' למעלה מן ההשגה וטעם כלל וא\"כ איך הנשמות בג\"ע משיגים בהשגת אלקות בעילוי אחר עילוי כמו ילכו מחיל אל חיל<sup data-n=\"980\">13</sup> ממדריגה למדריגה כו' כמו בשבת<sup data-n=\"981\">14</sup> וי\"ט כידוע אלא צ\"ל שהנשמה גם מצד עצמה כלולה מחו\"ב ומדות ודיבור כמו רוח ממלל'<sup data-n=\"982\">15</sup> וכמו ששמע ב' רוחות מספרים זע\"ז<sup data-n=\"983\">16</sup> וכמו במלאכים דכתיב וקרא זה אל זה<sup data-n=\"984\">17</sup> כו' כידוע וא\"כ מהו ההפרש בין נשמות שבג\"ע לנשמות שבגופים אחר שבאים לכלל השגה בבינה ודעת והתפעלות המדות אוי\"ר כו' וצ\"ל שיש הפרש גדול בזה לפי שהנשמות בג\"ע המה מופשטים לגמרי מכל בחי' גשם מגשמי החומר הטבעי כמלאכים שנק' רוחות רוח אלקי כך בחי' נשמה אלקי' ואם כלולה גם מבינה ומדות ודבור אבל הוא בבחי' כח אלקי ממש כי נר ה' נשמת אדם כי אתה תאיר נרי<sup data-n=\"985\">18</sup> וכה\"ג א\"כ גם חו\"ב ומדות",[["968","1","<b>שנחיה לפניו</b>: יהושע ו, ב."],["969","2","<b>כל אחד מראה באצבעו</b>: תענית בסופה."],["970","3","<b>הנה אלקינו זה</b>: ישעי' כה, ט."],["971","4","<b>דלית מת\"ב כלל</b>: ת\"ז בהקדמה (יז, א)."],["972","5","<b>דגופא. . וסליק ביה</b>: ראה זהר שלח קסח, א."],["973","6","<b>באור פני מלך חיים</b>: משלי טז, טו."],["974","7","<b>דכד אתכפיא סט\"א</b>: ראה זהר תרומה קכח, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' ה. לקמן סה, ב."],["975","8","<b>מבשרי אחזה אלו'</b>: איוב יט, כו [ושם: ומבשרי]. ראה הנסמן לקמן קלא, ב."],["976","9","<b>אתה הראת לדעת</b>: ואתחנן ד, לה."],["977","10","<b>באוצר הנשמות</b>: נסמן לקמן צח, א."],["978","11","<b>אלקים חיים</b>: ואתחנן ה, כג."],["979","12","<b>נשמת שדי תבינם</b>: איוב לב, ח [ושם: ונשמת ? ראה מאמרי אדה\"א נ\"ך ע' שכ. וש\"נ]."],["980","13","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["981","14","<b>ממדריגה. . בשבת</b>: נסמן לעיל לד, א."],["982","15","<b>רוח ממלל'</b>: ת\"א לבראשית ב, ז."],["983","16","<b>ב' רוחות מספרים זע\"ז</b>: ברכות יח, ב."],["984","17","<b>וקרא זה אל זה</b>: ישעי' ו, ג."],["985","18","<b>כי אתה תאיר נרי</b>: תהלים יח, כט."]]],[2800530087,"אוי\"ר ודבור והילוך וכל התוארים הכל בבחי' הרוחניות דאלקות כמלאכים שנק' בני האלקים שכלולים מהשגה ומדות ודיבור כידוע וגם נשמות דבי\"ע שהן מאין ליש כמ\"ש אלקי נשמה<sup data-n=\"986\">19</sup> כו' אתה בראת כו' לכבודי בראתיו יצרתיו<sup data-n=\"987\">20</sup> כו' אך ירידת הנשמה בגוף זהו תכלית ההגשמה שתתלבש בלבוש גס כזה כי הגם שיש לכל נשמה גם בעודנה למעלה במקור חוצבה לבוש שתתלבש וא\"ל לא תוכל לקבל פני שכינה וכמ\"ש בזהר ע\"פ ותלבש אסתר מלכות<sup data-n=\"988\">21</sup> דאתלבשת באוירא דג\"ע כו' והוא מלבוש זך דקדושה האלקי' שע\"י הלבוש זה דוקא תשיג ותהנה מזיו כו' אבל ירידה זאת שירדה בסתר המדריגות כ\"כ בלבוש גס דנה\"ט אין ירידה כמוה כמו מאגרא רמה<sup data-n=\"989\">22</sup> כו' והענין הוא כמבואר למעלה שבכל עולם יש בחי' נוגה שהוא בחי' יש גמור רק שבטל לפרקים כו' עד הע' שרים למטה שהוא נוגה דעשיה שיורד משם ומתגשם עוד להיות התהוות הנה\"ט שבגוף החומרי דגם שהוא נק' נפש אדם בעל שכל ונק' נפש המדברת<sup data-n=\"990\">23</sup> אבל הוא בא בתכלית ההגשמה לגבי רוחניות דרוחות דמלאכים עליונים גם בירידת השפע מהם בע' שרים מחיצוניות המרכבה דעשיה כו' והיינו ענין הנפש החיונית שכלולה מרצון ושכל ומדות ודיבור במוטבע בטבע הד\"י המורכבים בהרכבה גשמיות ולזה יש חכמי' להטיב בגשמיו' וחכמי' להרע וכן במדו' טו\"ר וכו' והכל להיותם בהגשמו' הלבוש דנוגה דעשי' וזהו כל ענין נפש השכלית והיא נפש הטבעי' יש שכל מתפעל בטבע הכלי מטה כלפי חסד להטיב ויש להיפך ועיקר מהותה הוא שכל אנושי ומדו' אנושי' מורכבי' בטבעיו' הגוף בדם ובשר כו' ששרשו מבחי' נוגה דעשי' שמעורב טו\"ר כו' וע\"כ יש שרובו רע מבפני' ומיעוטו טוב מבחוץ ויש להיפך כו' וטו\"ר שבק\"נ בגוף יש בו חילוקי מדריגות רבות מאד כו' ומעתה יפלא מאד מה שאנו רואים בחוש שיש לאיש הישראלי התפעלות אלקי' ממש בנפשו הטבעי' החומרי' דוקא בשכלו ובמדותיו הטבעי' דוקא וכמ\"ש ואהבת בכל לבבך<sup data-n=\"991\">24</sup> בכל לבבך ממש בלב בשר הגשמי כמו שאוהב א\"ע כו' ובשכלו שכל האנושי גשמי ישיג ויכיר לבוראו איך שמהוה מאין ליש בהשג' ודעת גמור ויתפעל מזה מאד שאין זה מסוג וערך הנה\"ט מצד עצם מהותה כלל כי שרשה למטה בק\"נ כו' ואם מצד שבשרשה בנוגה דעשי' כע' שרים וכה\"ג משיגי' גם הם ומתפעלי' ואומרי' שירה לפרקים וחוזרים להיות בפירוד כנ\"ל מ\"מ הנפש הזאת דנגה שבגוף חומרי כבר הורדה עוד בתערובו' דטו\"ר מאד עד שיצר לב האדם רק רע<sup data-n=\"992\">25</sup> ולא טוב כלל ואיך יתקבל בכלי מוחו ולבו התפעלות שכל והשגה אלקית יותר מע' שרים דנגה שהרי יוכל אדם להתפעל בכל לבו ובשרו כצדיק גמור כמו שכתוב לבי ובשרי ירננו<sup data-n=\"993\">26</sup> כו' ויותר ראי' מן בע\"ת שיצאו מגשם גופם ובשרם בכלות הנה\"ט כו' כראב\"ד שיצא נשמתו בבכי'<sup data-n=\"994\">27</sup> וכמס\"נ עקדה\"ש גם בקלים<sup data-n=\"995\">28</sup> כו' וכ\"ש מס\"נ דצדיקים גם בגופם בפו\"מ שאין זה חידוש כ\"כ כו' אלא צ\"ל שיש איזה הארה אלקי' בהעלם גדול בחומר הנה\"ט בב\"ו<sup data-n=\"996\">29</sup> הגשמי עד שיוכל לקלוט בו אור התפעלו' שכל רצון וענג אלקי ומדו' אוי\"ר כמו בגשמיו' גופו ממש וזה פלא גדול לכאורה כו' והענין הוא משום דיש שרש לנה\"ט שבק\"נ בשרשם",[["986","19","<b>כמ\"ש אלקי נשמה</b>: ברכות השחר."],["987","20","<b>לכבודי בראתיו יצרתיו</b>: ישעי' מג, ז [ושם: ולכבודי]."],["988","21","<b>ותלבש אסתר מלכות</b>: אסתר ה, א. ראה זהר שלח קסט, ב."],["989","22","<b>מאגרא רמה</b>: ראה חגיגה ה, ב. מאמרי אדה\"א דברים ח\"ב ע' תכה. וש\"נ. שמות ח\"א ע' קח."],["990","23","<b>נפש המדברת</b>: ראה גם לקמן קלה, ב. קמג, ב. תו\"ח נח עט, ג ובהערה 12."],["991","24","<b>ואהבת בכל לבבך</b>: ואתחנן ו, ה [בדילוג]."],["992","25","<b>שיצר לב האדם. . רע</b>: נח ח, כא."],["993","26","<b>לבי ובשרי ירננו</b>: תהלים פד, ג."],["994","27","<b>כראב\"ד שיצא נשמתו בבכי'</b>: ע\"ז יז, א. ראה סה\"מ תרמ\"ו ע' יט."],["995","28","<b>וכמס\"נ. . בקלים</b>: נסמן לעיל ט, ב."],["996","29","<b>בב\"ו</b>: בבשר ודם."]]],[2800530088,"הראשון שלפני השבירה בז' מלכים דתהו כו' משום דבחי' נוגה היא לבוש חשמל ששרשו בחשמל העליון דתוהו כו' דכתיב ביה ישת חשך סתרו<sup data-n=\"997\">1</sup> מגלה עמוקו' מני חשך<sup data-n=\"998\">2</sup> עד שיש יתרון האור מן החשך<sup data-n=\"999\">3</sup> דוקא (ולזה אמרו טוב מאד זה מ\"ה<sup data-n=\"1000\">4</sup> ) וכמו שאמ' בתורתו של ר\"מ היה כתוב כתנות עור אור באל\"ף<sup data-n=\"1001\">5</sup> שזהו לאחר בירור לבוש דנוגה דחשמל שנהפך מעור המסתיר לאור המזהיר ביותר יותר מן האור עצמו מצד יתרון האור שמן החשך דוקא וד\"ל:\n(כד) <b>ולהבין</b> זה הנה באמת ירידה זו שירדה הנשמה האלקי' בנה\"ט דלבוש גס דק\"נ ע\"ז אמ' אתה הראת לדעת כו' שהראת לדעת כי ה' כו' ע\"י לבוש זה דנה\"ט דוקא הגם שראיה זאת אינה ראיי' המהות דאלקו' כלל רק ראי' בדעת בבחי' מציאת התפשטותו מאין ליש לבד שאינו אלא ידיעה להכיר בוראו שברא מאין ליש כו' והנשמה מצד עצמה היתה עומדת לפני ה' בבחי' ראי' המהות כמו אשר עמדתי לפניו<sup data-n=\"1002\">6</sup> כו' אך ירידתה זאת אינה בשביל עצמה אלא לתקן לבוש זה דנוגה והוא במה שאמ' הראית פועל יוצא שתוכל להראו' גם לגוף שיהיה רואה ומכיר גם הוא לבוראו ויתפעל באוי\"ר טבעיי' שלו הגשמי' כמ\"ש בכל לבבך כנ\"ל כי הגם שיש שרש לנה\"ט בנוגה דעשי' דקרו לי' אלקא כו' אין זה רק הודאה מרחוק לבד אבל שיתפעל באוי\"ר באמת ובהשגה פנימי' כהשגה וראי' דנשמה ממש שרואה ומשיג באמית' העצמו' זהו ע\"י הנשמה שתלמד לנה\"ט שתראה גם היא כמוה כאדם שמראה לחבירו שיראה מהות הדבר שהוא רואה הרי יראה חבירו בעינו כמו שהוא רואה בעינו בלי הפרש כלל אע\"פ שהוא איש גס ואינו מכיר במעלת אותו הדבר מ\"מ רואהו בעיניו כו' רק שרואה לפי ערכו והשגתו כך הנשמה משפיע כח ודעת בנה\"ט שתשכיל ותכיר גם היא באלקו' אע\"פ שהשכלה והכרה זו דנה\"ט אינה רק לפ\"ע שרש' שהוא אחר הצמצ' דאור האלקי בתכלית שאינו רק בהשגת מציאותו איך שמחי' ומהוה מאין ליש עכ\"ז הוא ראיה במהות דאלקו' במה שהוא מהוה מאין עכ\"פ שז\"ש כי ה' הוא האלקי' דשם<sup data-n=\"1003\">7</sup> אלקים הוא כח האלקי המהוה מאין כו' וה' הוא מהו\"ע אלקו' שהנשמה הייתה דבוקה שם תמיד וכאשר תתלבש בנה\"ט תשיג ותראה בשם אלקי' דוקא בראיה במהות כח שם אלקי' זה שהוא כמו שם הוי' עצמו ולזה ירדה הנשמה בגוף רק לדעת את הנה\"ט שתדע גם היא שה' הוא האלקים הכל בבחי' אא\"ס ממש ע\"י התבוננו' בראי' שכליי' דנה\"ט דוקא וד\"ל:\n<b>והענין</b> הוא כמ\"ש שאו מרום עיניכם<sup data-n=\"1004\">8</sup> וראו מי ברא אלה הרי יתכן עכ\"פ בחי' ראי' ממש במי שברא אלה מאין ליש והוא התבוננו' דבחי' ממכ\"ע בבשכמל\"ו<sup data-n=\"1005\">9</sup> כידוע משא\"כ מ\"ש הביטו אליו<sup data-n=\"1006\">10</sup> אליו ממש שזהו בשם הוי' בחי' סובב<sup data-n=\"1007\">12</sup> כו' שבנשמה אמנם הרי עיקר הדע' והכרה זו הוא שהוי' הוא האלקי' כולא חד<sup data-n=\"1008\">13</sup> ממש וא\"כ כשרו' מי ברא אלה ה\"ז כרוא' במהות ועצמו' דהוי' בחי' סובב כו' רק שזהו כמשל מי שרואה במהות המלך בעינו ע\"י כלי ההבטה מזכוכי' לבנה ובהירה ביותר שה\"ז כרוא' בעיניו ממש אע\"פ שנרא' לו מהו' הדבר ע\"י הכלי איננו מפסיק כלל כך הראי' שם אלקי' ע\"י השגה וראי' שכליי'",[["997","1","<b>דתוהו. . ישת חשך סתרו</b>: תהלים יח, יב. ראה מאמרי אדה\"א דברים ח\"א ע' ו? ח\"ב ע' תקסח? ח\"ד ע' א'רמז ובהנסמן בהנ\"ל."],["998","2","<b>מגלה עמוקו' מני חשך</b>: איוב יב, כב."],["999","3","<b>יתרון האור מן החושך</b>: ע\"פ קהלת ב, יג."],["1000","4","<b>טוב מאד זה מ\"ה</b>: בראשית א, לא. ראה ב\"ר פ\"ט, י. פיה\"מ פקכ\"ח ואילך. מאמרי אדה\"א דברים ח\"א ע' ז. וש\"נ. בראשית ע' סג. שמות ח\"ב ע' תריג."],["1001","5","<b>בתורתו. . אור באל\"ף</b>: ראה לקמן קמ, א ובהנסמן במ\"מ לשם."],["1002","6","<b>אשר עמדתי לפניו</b>: מלכים-א יז, א. יח, טו. מלכים-ב ג, יד. ה, טז."],["1003","7","<b>דשם</b>: כ\"ה בדפו\"ר. ובמהדורת לעמבערג: דה'."],["1004","8","<b>שאו מרום עיניכם</b>: ישעי' מ, כו."],["1005","9","<b>ממכ\"ע בבשכמל\"ו</b>: ראה גם לקמן קמה, א ובהנסמן לשם."],["1006","10","<b>הביטו אליו</b>: תהלים לד, ו."],["1007","12","<b>הוי' בחי' סובב</b>: ראה גם לקמן שם."],["1008","13","<b>שהוי' הוא האלקי' כולא חד</b>: נסמן לעיל יב, ב."]]],[2800530089,"דנה\"ט זהו כמו הרואה ע\"י מחזה ומראה שמראה למהות הדבר עכ\"פ רק שרוא' ע\"י מראה ואמנם המראה בהירה בלתי מפסקת לעצם הדבר כלל כאילו רואהו בעין ממש בלי הפרש כלל כו' וד\"ל ולא עוד אלא שעל ידי ראיה והכרה זו שבעיני בשר בגוף ע\"י התבוננות דמי ברא אלה וכה\"ג ע\"ד הפשוט ממש זהו הגורם בנשמ' יתרון אור בראי' המהות ועצמו' כיתרון האור מן החשך דוקא כנ\"ל ויובן זה במ\"ש איוב מבשרי אחזה אלוה מבשרי ממש שהוא נה\"ט החומרי במוח ולב בשר כשהוא רואה בראית שכל האנושי בעיני בשר דוקא משם אחזה אלוה אחזה ממש בבחי' ראית המהות כמו שיהיה לע\"ל דכתיב ונגלה כבוד ה'<sup data-n=\"1009\">14</sup> וראו כ\"ב דוקא בראי' חושית וטבעית כו' ויש להקדים לזה ענין א' המבואר במ\"א בהפרש שבין שמיעה לראיה<sup data-n=\"1010\">15</sup> שהשמיעה מרחוק והראיה מקרוב ושרש השמיעה במוח הבינה<sup data-n=\"1011\">16</sup> שמתפשט באזן וכמו שמע ישראל<sup data-n=\"1012\">17</sup> כו' והראיה במוח החכמה<sup data-n=\"1013\">18</sup> דוקא ונקרא עין השכל ואיזהו חכם<sup data-n=\"1014\">19</sup> הרואה את הנולד וחכמים נק' עיני העדה<sup data-n=\"1015\">20</sup> כידוע ולפ\"ז יפלא מה שאנו רואים שהשמיעה יותר דקה<sup data-n=\"1016\">21</sup> במהות' מן הראיה שהרי יש באזן השמועה<sup data-n=\"1017\">22</sup> להבחין בין קול עצב לקול שמחה ובין דבר טוב או רע שזהו פעולה וכח רוחני הרבה יותר מן הראיה שפעולתה גשמי' להביט ולהסתכל בדבר גשם דוקא כו' ואם שרש הראי' במוח החכמה הי' ראוי שיהיה בראיה פעולה רוחניות יותר ולהיפך אנו רואים מעלה יתירה בראיה מבשמיעה והוא בענין השגת אמיתית הדבר כמו שהוא שאמר אינו דומה שמיעה לראיה<sup data-n=\"1018\">23</sup> דאע\"פ ששומע הדבר ומבין הטיב או שיצייר בשכלו ויתבונן בדבר מה ויכוין בהשגתו בשכלו כמו שהוא ממש מ\"מ אינו דומה לראיה כשרואה מהות הדבר ממש בעיניו ישיג לאמתתו ממש כידוע שא\"א לשמיעה והבנה להשיג כ\"כ לאמית' הדבר כמו ע\"י הראיה שע\"כ גזרו אומר דאינו דומה שמיעה לראיה כלל ועוד זאת אנו רואים הפרש גדול ביניהם בענין ההתפעלות של הנפש שאינו דומה כלל התפעלות הנפש בשמיעה ששומע דבר טוב או רע אע\"פ שיתפעל ביותר כי שמע והבין הטיב (עד שהוא בא באודנין דלבא<sup data-n=\"1019\">24</sup> הלב שומע<sup data-n=\"1020\">25</sup> כו') בהתפעלות הנפש מבשורה טובה ונפלאה בריוח הון רב או בן הנולד ופקוח נפשו וכה\"ג או להיפך מדבר רע ביותר כהיזק ורציחה וכה\"ג מ\"מ לא ידמה כלל להתפעלות הנפש מן הראיה כשרואה בעיניו דבר הבשורה הטובה או להיפך כשרואה ההיזק והרציחה בפו\"מ וכה\"ג ולפ\"ז יובן שיותר גדול כח הראיה מן כח השמיעה אבל במהותם נהפך הוא שהשמיעה יותר דקה מן הראיה כנ\"ל אך הנה להיות שבחי' הרוחניות דכח הראיה וכח השמיעה הרי כח הראיה במוח החכמה שהוא נעלה מן מוח הבינה דשמיעה ע\"כ יכוין יותר לאמיתת הדבר ויתפעל יותר בראיה מבשמיעה וזהו עצמו הטעם שיש בשמיעה רוחניות יותר מבראי' לפי שכל הגבוה גבוה יותר יותר יוכל להשפיל עצמו בדבר הנמוך<sup data-n=\"1021\">26</sup> ואדרבה טבעו להתמשך ולהתלבש בדבר שפל ונמוך ביותר וכל שאינו גבוה כ\"כ לא יבא למטה כ\"כ בדבר נמוך וגס רק בדבר רוחני ודק יותר וע\"כ השמיעה שהיא בבינה לא תבא",[["1009","14","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["1010","15","<b>בהפרש שבין שמיעה לראיה</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' רפז. תקס\"ד ע' רו. מאמרי אדה\"א הנחות תקע\"ז ע' רלח."],["1011","16","<b>השמיעה. . הבינה</b>: ראה זהר [אד\"ר] נשא קלח, ב. מאמרי אדה\"א הנחות תקע\"ז ע' כז. וש\"נ."],["1012","17","<b>שמע ישראל</b>: ואתחנן ו, ד."],["1013","18","<b>והראי'. . החכמה</b>: ראה מאמרי אדה\"א שם. וש\"נ."],["1014","19","<b>ואיזהו חכם</b>: תמיד לב, א."],["1015","20","<b>וחכמים נק' עיני העדה</b>: נסמן לקמן קסט, א."],["1016","21","<b>שהשמיעה יותר דקה</b>: ראה סה\"מ תקס\"ט ע' פט."],["1017","22","<b>השמועה</b>: בדפו\"ר: השמועת. וכנצ\"ל: השומעת."],["1018","23","<b>אינו דומה שמיעה לראיה</b>: נסמן לעיל ט, ב."],["1019","24","<b>באודנין דלבא</b>: ראה זהר (רע\"מ) משפטים קטז, ב. ת\"ז תנ\"ח (צב, א)."],["1020","25","<b>הלב שומע</b>: קה\"ר פ\"א, טז."],["1021","26","<b>שכל הגובה. . בדבר הנמוך</b>: ראה ש\"א שער הפורים ע' נח וע' סה. מאמרי אדה\"א הנחות תקע\"ז ס\"ע קכא. וש\"נ."]]],[2800530090,"רק ברוחניות להבחין בקול רוחני ובין טו\"ר כנ\"ל והראי' להיות שרשה במוח החכמ' מתפשטת למטה בדבר הנמוך בפעולה גשמיית שהוא לתפוס בראי' את הגשם וכדומם ולא יותר וזהו ג\"כ מצד הטעם הנ\"ל שהשמיעה מרחוק דוקא והראיה מקרוב דוקא כנ\"ל וד\"ל. ועוד יובן מטעם כלל הנ\"ל מה שאנו רואים עוד הפרש בין ראיה לשמיעה שהראיה תפול בדבר השפל ונמוך דוקא להיות שהראיה מקרוב דוקא אבל השמיעה לא תתכן רק בדבר הנעלה וגבוה ומופלא בערך דוקא כי השמיעה מרחוק והיא דק ביותר אבל הראיה להיותה גשמיית והיא מקרוב לא תתפס בדבר הגבוה ונעלה<sup data-n=\"1022\">1</sup> רק בדבר גשמי כדומם וכה\"ג והוא מטעם כלל הנ\"ל דכל הגבוה כו' וד\"ל. והדוגמא מראיה ושמיעה למט' בהפרש שביניהם כנ\"ל למעלה יובן ג\"כ עד\"ז ממש והוא להיות שאנו רואים בבחי' ראיה ושמיעה שבנשמ' האלקי' ג\"כ הפרש גדול ביניהם והוא שהשמיעה והשגת שכל בנה\"א אינו אלא מרחוק והוא בבחי' יח\"ע דוקא שמופלא בערך וגבוה מאד נעלה כו' כמו שמע ישראל ה' כו' שזהו יחוד ע\"ס דאצי' בעצמות המאציל וכה\"ג והראיה היינו דוקא מקרוב והוא בראיית העין בהתהוות יש מאין בבחי' יח\"ת דבשכמל\"ו וכה\"ג וכנ\"ל בענין מי ברא אלה שיפול בזה ל' ראיה דוקא להיות מקרוב בדבר השפל ונמוך ביותר שהוא בחי' דומם כו' והענין הוא כידוע שבחי' מל' המהוה מאין ליש בבחי' עולם נפרד נק' בחי' דומם לגבי עולם האצי' להיותו בחי' עשיה בפ\"מ ונקרא עפר אשר בקרקע המשכן<sup data-n=\"1023\">2</sup> וע\"כ נק' דל<sup data-n=\"1024\">3</sup> כמו מקים מעפר דל<sup data-n=\"1025\">4</sup> כו' להיות שמוסתר כח האלקי בבחי' יש בדבר השפל ביותר זהו כערך הדומם לגבי החי כו' ויתכן בו בחי' הראיה שהיא מתפשטת בדבר השפל דוקא מטעם הנ\"ל אבל התבוננות ההשגה ביח\"ע דאצי' כנ\"ל הוא דבר נעלה וגבוה מערך הנפש שהוא בחי' סוכ\"ע בדרך כלל שלמעלה הרבה מבחי' ממלא כו' כידוע ע\"כ יתכן בזה חוש השמיעה מרחוק כי מרחוק ה' נראה לו<sup data-n=\"1026\">5</sup> בהשגת שכל לבד כנ\"ל וד\"ל. וגם זהו הטעם שאנו רואים שתתפעל הנשמה ביותר מבחי' יח\"ת ומה שהמלאכים מתבטלים מיש לאין באמרם שירה ברעש גדול כו' הרבה יותר משתתפעל הנשמה בהתבוננות שלה ביח\"ע כו' שלא תתפעל כ\"כ ביח\"ע גם שמשיג בטוב טעם ודעת האלקי כל חד לפום שיעורא דיליה<sup data-n=\"1027\">6</sup> כידוע וזהו מטעם שבראיה מקרוב גם שהוא בדבר הנמוך יש התפעלות יותר מבשמיעה גם שהוא בדבר הגבוה כו' לפי שאינו דומה שמיעה לראיה כלל בעיקר הדבר שהוא בהשגת אמיתית הדבר כמו שהוא ואע\"פ ששומע ומשיג היטב מ\"מ לא נודע לו אמיתית הדבר כי מופלא הימנו ומרחוק ה' נראה לו כו' משא\"כ בראיה מקרוב ביח\"ת שרואה אמיתת הדבר כאילו רואה בעיניו ממש ולזה יתפעל ביותר וכנ\"ל הטעם דשרש הראיה במוח החכמה ע\"כ ההתפעלות בראיה יותר מבשמיעה וע\"כ יח\"ע אינו נתפס בראיה להיותו מרחוק בדבר הגבוה כו' ובשמיעה נתפס יח\"ע להיותו במוח הבינה לבד דשמיעה מרחוק כנ\"ל ונמצא שבדבר הגבוה מרחוק תתפעל חוש השמיעה יותר מן הראיה ובדבר השפל מקרוב תתפעל הראיה מקרוב יותר מן השמיעה וד\"ל:",[["1022","1","<b>ונעלה</b>: כ\"ה בדפו\"ר. ובמהדורת לעמבערג: ונעלם."],["1023","2","<b>מל'. . עפר אשר בקרקע המשכן</b>: נשא ה, יז. ראה רמ\"ז לזהר תזריע מו, ב. ביאוה\"ז ויצא קלה, א. דרמ\"צ קנט, א."],["1024","3","<b>מל'. . נק' דל</b>: נסמן לעיל כד, ב."],["1025","4","<b>מקים מעפר דל</b>: שמואל-א ב, ח."],["1026","5","<b>מרחוק ה' נראה לו</b>: ע\"פ ירמי' לא, ב."],["1027","6","<b>כל חד. . דיליה</b>: נסמן לעיל כב, ב."]]],[2800530091,"(כה) <b>ובזה</b> יובן מה שתיקנו אנשי כה\"ג לומר בשכמל\"ו בק\"ש שאמר משה ולא הזכירו רק יעקב ובניו כשאמרו כשם שאין בלבך<sup data-n=\"1028\">8</sup> אלא אחד כו' ואנשי יריחו<sup data-n=\"1029\">7</sup> היו כורכים ומדלגים בשכמל\"ו ואין הלכה כן לפי שהשבטים הן בעלמא דנוקבא<sup data-n=\"1030\">9</sup> שהוא בבחי' המל' שמתלבשת בעולמות בבחי' כהפב\"נ שזהו הארת אור האצי' שמוסתר בבי\"ע ולא בבחי' מהות ועצמות האצי' כידוע ע\"כ היה התפעלותם ביח\"ע שבעצמות האצי' בבחי' השמיעה מרחוק כנ\"ל וכמו שאמר משה לישראל שהן ענפים שמתפשטים מן השבטים בלשון שמיעה דוקא שמע ישראל ה' אלקינו כו' ולא בהתפעלות דראיה מקרוב ולזאת תקנו אנשי כה\"ג בשכמל\"ו שיהיה התפעלות כנ\"י בראיה מקרוב דוקא שהוא בדבר השפל ונמוך בחי' דומם עפר אשר כו' כדי שיתפעלו ביותר מן השמיעה שביח\"ע אע\"פ שהוא גבוה יותר כנ\"ל לפי שעיקר המצוה ביחוד אלקות היינו התפעלות הראיה מקרוב דוקא וכמ\"ש אתה הראת לדעת הראית בבחי' ראיה דוקא שאינה אלא מקרוב ובדבר השפל ונמוך ביותר ולא בגבוה ורחוק כנ\"ל וד\"ל אך מ\"ש משה שמע ישראל כו' היינו לפי שמדריגת משה היה בבחי' עצמות אור החכמה<sup data-n=\"1031\">10</sup> דאצי' שאצלו גם האצי' עצמו הוא בבחי' ראיה מקרוב שהרי נאמר בו וירא ראשית לו<sup data-n=\"1032\">11</sup> להיותו בבחי' החכמה דאצי' שהוא בבחי' ראיה דוקא רק לגבי ישראל שהן למטה בעולם הבריאה יש מאין האצי' הוא בבחי' שמיעה מרחוק ע\"כ אמר להם שמע ישראל כו' וע\"כ אין הלכה כאנשי יריחו לפי שבימי יהושע ירדו כנ\"י במדריגת המל' שהוא בחי' פני לבנה<sup data-n=\"1033\">13</sup> וע\"כ עיקר היחוד בק\"ש בראיה דבשכמל\"ו משא\"כ בימי משה שהוא כפני חמה<sup data-n=\"1034\">12</sup> היה מאיר לישראל מאור האצי' עצמו בקרוב כ\"כ עד שיקבלו בשמיעה כמו בראיה מקרוב ואתפשטותא דמשה<sup data-n=\"1035\">14</sup> בכל דרא כו' וד\"ל. והנה ע\"ד הנ\"ל בין שמיעה לראיה שאינו דומה שמיעה לראיה בב' דברים א' בהשגת אמיתית הדבר כמו שהוא ממש והב' בהתפעלות עצמיות ביותר כו' וזהו להיות הראיה מקרוב ובדבר הנמוך ביותר כו' כך יובן ההפרש בראיה עצמה בין ראיה רוחניות לראיה גשמיות דהנה גם בראיית השכל כמו חכם הרואה את הנולד וכה\"ג שרואה בעין השכל ולא בעין הגשמי אלא שנק' עין השכל שרואה ראיה שכליית (שלמעלה מהבנה והשגה דבינה מרחוק כו') נק' ראיה רוחניות וע\"כ נקראו חכמים עיני העדה כידוע כך הוא בראיית השכל האלקי' שרואה את הנולד פי' הנולד מאין ליש<sup data-n=\"1036\">15</sup> וכה\"ג שזהו בבחי' יח\"ת שנק' ראיה מקרוב כנ\"ל הרי זהו היפך הראיה גשמיות שרואה בעין הגשמי שנראה לעין הגשמי רק היש הנברא מאין האלקי ולא יראה כלל בבחי' אין האלקי המוסתר בו אבל ע\"י ראיה שכליית דוקא יראה בחי' האין האלקי המוליד ליש שהוא העיקר והיש טפל ובטל ממש וכלא חשיב ובדבר זה אינו דומה שמיעה לראיה דבהשגה והבנה דשמיעה מרחוק הנ\"ל לא יכוין לאמיתת הדבר שהוא בחי' אין של היש כמו שהוא ממש רק מרחוק כו' משא\"כ ע\"י ראי' עין השכל יכוין בו לאמתתו כמו שהוא ממש וכמ\"ש בר\"מ דבעין השכל דבלבא אתחזי כולא<sup data-n=\"1037\">16</sup> כו' וזהו",[["1028","8","<b>בלבך</b>: כ\"ה בדפו\"ר. ובמהדורת לעמבערג: בלבבך."],["1029","7","<b>שתיקנו. . ואנשי יריחו</b>: ראה פסחים נו, א. מאמרי אדה\"א הנחות תקע\"ז ע' רלח. וש\"נ."],["1030","9","<b>שהשבטים הן בעלמא דנוקבא</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ס\"ע רעח ואילך. וש\"נ. שע\"ת צב, ג ובהנסמן במ\"מ לשם."],["1031","10","<b>משה. . עצמות אור החכמה</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרלו־ ע' תתצה־ נ\"ך ע' סז ובהנסמן בהנ\"ל."],["1032","11","<b>וירא ראשית לו</b>: ברכה לג, כא."],["1033","13","<b>המל'. . לבנה</b>: ראה פרדס (שער ערכי הכינויים) שכ\"ג מערכת לבנה."],["1034","12","<b>יהושע. . לבנה. . חמה</b>: ב\"ב עה, סע\"א. ראה מאמרי אדה\"א נ\"ך ע' תסא."],["1035","14","<b>ואתפשטותא דמשה</b>: ראה ת\"ז תס\"ט [קיב, רע\"א. קיד, רע\"א-ס\"א] תכ\"א [נ, ב]. ב\"ר פנ\"ו, ז. מאמרי אדה\"א שמות ח\"ב ע' שצט."],["1036","15","<b>שרואה את הנולד. . מאין ליש</b>: ראה תניא פמ\"ג. מאמרי אדה\"א שמות ח\"ב ס\"ע שלב ואילך. וש\"נ. דברים ח\"א ע' רכא. וש\"נ. שע\"ת ח\"א ע, ג."],["1037","16","<b>דבעין השכל דבלבא אתחזי כולא</b>: נסמן לקמן ע' קיא, א."]]],[2800530092,"לפי שחומר הגופני מחשיך ראיה רוחניות ועיני בשר יראו היש הטפל לעיקר כו' אבל כשיוסר או שיזדכך החומר הגופני יוכל לראות גם בעיני בשר בראיה חושיות וטבעי' ממש כמו שהוא רואה בעין השכל הרוחני כמו לע\"ל דכתיב וראו כל בשר וכה\"ג אמר שאו מרום עיניכם וראו עיניכם ממש מי ברא אלה כו' בראיה גשמיית בעין הגשמי ואז יש בו יתרון מעלה על ראית עין השכל הרוחני לכוין לאמיתתו יותר ולהתפעל ביותר מפני שהוא מקרוב יותר ונמוך ביותר כנ\"ל בטעם יתרון מעלת הראיה מקרוב על השמיעה מרחוק בב' דברים הללו כו' (וכגילוי ראיית העין במראה הנבוא' דכתיב ואראה את ה'<sup data-n=\"1038\">1</sup> כו' בראית העין ממש וכמו בקי\"ס שאמרו זה אלי<sup data-n=\"1039\">2</sup> זה לנוכח וכן לע\"ל אלקינו זה<sup data-n=\"1040\">3</sup> ) ואז גם ההתפעלות הרבה יותר מהתפעלות דראית עין השכל (כהתפעלות הנביאים במראה הנבואה שנתבטלו מחושי גופם<sup data-n=\"1041\">4</sup> החומרי לגמרי בשגיונות וכו') וזהו כדמיון ניצוץ הנמשך לשלהבת בהיותו קרוב אליה כמו שאמר צדיקים כנר בפני האבוקה<sup data-n=\"1042\">5</sup> כו' (ולא כנשמות בג\"ע שנהנין ע\"י השגה דבינה<sup data-n=\"1043\">6</sup> כידוע) (ולא כראיה דג' רגלים<sup data-n=\"1044\">7</sup> שזהו ראיה רוחניות דעין השכל דכח מ\"ה שבנשמה כידוע ומבואר במ\"א) ומטעם זה הרי יובן עכ\"פ שבהגלות נגלות אור האלקי לעיני בשר דוקא כמו לעין השכל כמו לע\"ל וכה\"ג זהו יותר נעלה במדריגה מראיית עין השכל ע\"ד הנ\"ל שאינו דומה שמיעה לראיה בב' דברים הנ\"ל וד\"ל. ועם כ\"ז יובן מ\"ש מבשרי אחזה אלוה מבשרי דוקא כנ\"ל דהיינו בבחי' עיני בשר דוקא כאשר יזדכך החומר הגופני בתכלית הטהרה והקדושה האלקי' (כנביאים וכמו לע\"ל שיראו כל בשר כנ\"ל) להכיר את בוראו בראית העין ממש מה שעתה אינו רואה רק בעין השכל לבד אז אחזה אלוה ממש כמו לחזות בנועם ה'<sup data-n=\"1045\">8</sup> כו' שרואה לאמתת העצמות דאלקות ובהתפעלות כל העצמות הרבה יותר מראיית עין השכל וד\"ל (וזהו אל יתהלל חכם בחכמתו<sup data-n=\"1046\">9</sup> בבחי' כח ראיית עין השכל כו' כ\"א בזאת יתהלל<sup data-n=\"1047\">10</sup> כו' השכל וידוע אותי ממש כמו בידיע' והכרה שע\"י ראית העין הגשמי' ממש וזהו בזאת דוקא בבחי' יראה<sup data-n=\"1048\">11</sup> אותיות ראיה<sup data-n=\"1049\">12</sup> שהוא בגשמיות) (ודוגמא לדבר זה הוא גם עתה כאשר הלב בשר הוא רואה ראית עין השכל שהוא יותר טוב מראית עין השכל עצמו כמ\"ש בעין השכל דבלבא דוקא אתחזי ממש כו' וכידוע לטועמי' טעם ראית עין השכל בלב בשר דוקא כמו לבי ובשרי ירננו אל<sup data-n=\"1050\">13</sup> כו' כמ\"כ אמר טעמו וראו<sup data-n=\"1051\">14</sup> כי טוב ה' כו' וכה\"ג וזהו הנראה בחוש ההתפעלות יתירה פתאום בניגון שבקירת הלב בגשמיות מחמת שהלב בשר דוקא רואה כו' ונק' שיר פשוט<sup data-n=\"1052\">15</sup> וכמ\"ש במ\"א בענין קולו של משה<sup data-n=\"1053\">16</sup> כו') אך עדיין אינו מובן מ\"ש אחזה אלוה בל' תרגום דהל\"ל אראה כו' הענין הוא לפי שגם אחר הזדככות חומר הנה\"ט בתכלית כנ\"ל הרי שרשו מק\"נ שנק' לבוש החשמל דנגה כנ\"ל רק שנעשה לבוש בהיר ביותר כמו כתנות עור בא' כנ\"ל ע\"כ נק' בל' תרגום בשם חזיון כחזון ישעיהו<sup data-n=\"1054\">17</sup> כו' כתרגום ראי' חזי<sup data-n=\"1055\">18</sup> כו' מפני שהוא בבחי' בירור דאחורים דחכמה ומ\"מ יש בזה תוס' אור הראיה במהות ועצמות לכוין",[["1038","1","<b>וארא את ה'</b>: ישעי' ו, א."],["1039","2","<b>זה אלי</b>: בשלח טו, ב."],["1040","3","<b>אלקינו זה</b>: ישעי' כה, ט."],["1041","4","<b>שנתבטלו מחושי גופם</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ז ה\"ב וה\"ו. קו\"א לתניא קנו, א ובהנסמן במ\"מ לשם."],["1042","5","<b>צדיקים כנר בפני האבוקה</b>: ראה פסחים ח, א. מאמרי אדה\"א ויקרא ח\"א ע' קעז. וש\"נ. דברים ח\"ג ע' תשסח. שע\"ת ח\"ב יח, א."],["1043","6","<b>כנשמות בג\"ע. . דבינה</b>: ראה ברכות יז, א. מאמרי אדה\"א בראשית ע' פט. במדבר ח\"ב ס\"ע שפח. וראה גם מאמרי אדה\"א ויקרא שם."],["1044","7","<b>כראיה דג' רגלים</b>: ראה גם סידור שער החנוכה רעו, ג."],["1045","8","<b>לחזות בנועם ה'</b>: תהלים כז, ד."],["1046","9","<b>אל יתהלל חכם בחכמתו</b>: ירמי' ט, כב."],["1047","10","<b>כ\"א בזאת יתהלל</b>: שם ט, כג."],["1048","11","<b>בזאת. . יראה</b>: ראה זהר אחרי נו, ב. בהר קח, א. מאמרי אדה\"א ויקרא ח\"א ע' סב. וש\"נ."],["1049","12","<b>יראה אותיות ראי'</b>: נסמן לעיל יג, ב."],["1050","13","<b>לבי ובשרי ירננו אל</b>: תהלים פד, ג."],["1051","14","<b>טעמו וראו</b>: תהלים לד, ט."],["1052","15","<b>שיר פשוט</b>: ראה זהר (רע\"מ) פינחס רכז, ב. ת\"ז בהקדמה (ג, א). מאמרי אדה\"א נ\"ך ע' תקנח. וש\"נ."],["1053","16","<b>קולו של משה</b>: ברכות מה, א. ראה ביאוה\"ז ויצא קלד, ג. מאמרי אדה\"א קונטרסים ע' קנה. וש\"נ."],["1054","17","<b>כחזון ישעיהו</b>: ישעי' א, א."],["1055","18","<b>כתרגום ראי' חזי</b>: בסידור כאן (רפז, ד) ניתוסף: כמו וחזי — ראה ת\"א לבראשית א, ד. ועוד."]]],[2800530093,"לאמיתתו יותר כנ\"ל דהיינו כאשר נתאמת אמיתת אא\"ס בעין בשר כמו הרואה בעינו הגשמי שמכיר ויודע הדבר יותר משיודע ומכיר ע\"י ראית עין השכל כמו השכל וידוע אותי כנ\"ל וכל שיזדכך החומר יותר מלבוש דנגה שהיה מסתיר יותר יראה בתוס' אור במהו\"ע וכמו לע\"ל שיראו כל בשר מצד שרוח הטומאה יתעבר<sup data-n=\"1056\">19</sup> לגמרי וגם יבא גלוי שם הוי\"ה בהסרת הנרתק ומגן דשם אלקים<sup data-n=\"1057\">20</sup> דהיינו ששם הוי\"ה יאיר כמו בחי' שם אלקים עכשיו ולא ע\"י הסתר כלל כי יהיו שניהם שוין ממש וזהו שיבואו במערות<sup data-n=\"1058\">21</sup> כו' מפני פחד ה' כו' שיהיה פחד אלקים<sup data-n=\"1059\">22</sup> על כל הברואים<sup data-n=\"1060\">23</sup> וכל פחד אינו אלא כשהוא מקרוב<sup data-n=\"1061\">24</sup> לעין הרואה בגשמיות ולא בראית עין השכל לבד שאינו מפחד כ\"כ כמו שאינו דומה שמיעה לראיה בזה כנ\"ל וא\"כ יהיה גלוי עצמות א\"ס בקירוב כ\"כ עד שיהיה פחדו על כל הברואים לפי שראו כ\"ב<sup data-n=\"1062\">25</sup> כו' וכן בעה\"ב שאמר ונחיה לפניו<sup data-n=\"1063\">26</sup> ממש בראית המהו\"ע וכל נשמה יאמר אלקינו זה לנוכח וכ\"ז לפי שמבשרי אחזה עתה בהזדככות לבוש המסתיר דק\"נ וכמשל הקליפת אגוז כשהיא קשה ועבה מסתרת הפרי שבתוכה ובשבירתה מיד תגלה הפרי ולע\"ל נאמר ולא יכנף עוד<sup data-n=\"1064\">27</sup> כו' והיו עיניך רואות לפי שישבר הקליפה והוא המסך מבדיל דנגה ולא עוד אלא שיאיר על ידו בתוס' אור לראות במהו\"ע יותר והיינו מה שיבא בנשמה בכח מ\"ה בראית עין השכל תוס' אור לראות בראית המהות כנ\"ל זהו מחמת שתראה הנה\"ט בעיני בשר דוקא לאחר ההזדככות אע\"פ שאינו אלא כמו מחזה עכשיו שאינו מזוכך כ\"כ אבל יתרון האור בעצם הראיה דנשמה מן החשך דק\"נ כשנזדכך הוא בא מטעם שיש שרש ללבוש דנגה בעולם התוהו שמגלה עמוקות מני חשך וכאשר יאיר בחי' החשך וההעלם הזה ה\"ז גלוי אמיתת עצמות אא\"ס כמו שהוא כמלך שמסתיר ומעלים א\"ע ואח\"כ מתגלה כו' כמ\"ש ישת חשך סתרו חושך העליון שקדם לאור החכמה כידוע וזהו מבשרי דנגה דוק' אחז' אלוה ממש וזהו אתה הראי' להראו' לנה\"ט בעיני בשר כנ\"ל ועי\"ז דוקא תתעלה הנשמה באמיתת ראי' החכמה בעין השכל וכמ\"ש הביטו אליו אליו ממש והביטו בעיני בשר שגבוה מעין השכל מטעם הנ\"ל וד\"ל:\n(כו) <b>וזהו</b> עין בעין יראו<sup data-n=\"1065\">28</sup> כו' פי' עין בעין כמו שהאדם רואה את רעהו פא\"פ שעינו רואה על עין רעהו ועין רעהו רוא' על עינו שזהו נק' עין בעין יראו ע\"ד הפשוט כו' וכך יובן בבחי' הרוחניות עפ\"י כל הנ\"ל דהנה כתיב עין ה' אל יראיו<sup data-n=\"1066\">29</sup> וכן עיניו כיונים<sup data-n=\"1067\">30</sup> שזהו מלמעלה למטה מהקב\"ה לכנ\"י וכתיב עיניך יונים<sup data-n=\"1068\">31</sup> מכנ\"י להקב\"ה וכן עיני כל אליך<sup data-n=\"1069\">32</sup> כו' וכמו הראי' בג' רגלים דיראה כל זכורך<sup data-n=\"1070\">33</sup> את פני ה' ממש וכשם שבא לראות<sup data-n=\"1071\">34</sup> כו' כ\"ז בראית עין השכל דנשמה האלקית וכמו במ\"ת שכל העם רואים<sup data-n=\"1072\">35</sup> אע\"פ שראו בעין גשמי ואיך יראו קול שצריך שמיעה ולא ראיה אלא כמו שאמרו רואין את הנשמע<sup data-n=\"1073\">36</sup> ושומעין את הנראה והיינו דמה שבא בכח ההשגה והבנה דבינה באזן שומעת ראו בראיי' עין השכל דבחי' כח מ\"ה שבנשמתם כנ\"ל בר\"מ דבעין השכל דבלבא",[["1056","19","<b>שרוח הטומאה יתעבר</b>: זכרי' יג, ב."],["1057","20","<b>הנרתק. . אלקים</b>: נסמן לקמן קמד, ב הערה שמש."],["1058","21","<b>שיבואו במערות</b>: ישעי' ב, יט."],["1059","22","<b>פחד אלקים</b>: תהלים לו, ב. דהי\"ב כ, כט."],["1060","23","<b>פחד אלקים. . הברואים</b>: נסמן לעיל לד, א הערה ובכן."],["1061","24","<b>פחד. . מקרוב</b>: ראה מאמרי אדה\"א נ\"ך ע' שצ. וש\"נ. הנחות תקע\"ז ע' ריד וע' שטו."],["1062","25","<b>שראו כ\"ב</b>: ישעי' מ, ה."],["1063","26","<b>ונחי' לפניו</b>: הושע ו, ב. ראה גם לעיל יא, ב."],["1064","27","<b>ולא יכנף עוד</b>: ישעי' ל, כ."],["1065","28","<b>עין בעין יראו</b>: ישעי' נב, ח."],["1066","29","<b>עין ה' אל יראיו</b>: תהלים לג, יח."],["1067","30","<b>עיניו כיונים</b>: שה\"ש ה, יב."],["1068","31","<b>עיניך יונים</b>: שה\"ש א, טו. ד, א."],["1069","32","<b>עיני כל אליך</b>: תהלים קמה, טו."],["1070","33","<b>דיראה כל זכורך</b>: פ' ראה טז, טז. וראה גם לקמן צד, ב."],["1071","34","<b>וכשם שבא לראות</b>: חגיגה ב, א."],["1072","35","<b>שכל העם רואים</b>: יתרו כ, טו."],["1073","36","<b>רואין את הנשמע</b>: רש\"י ומכילתא יתרו כ, טו. ראה מאמרי אדה\"א קונטרסים ע' שפט. וש\"נ."]]],[2800530094,"אתחזי וע\"כ על כל דיבור ששמעו דוקא פרחה נשמתן<sup data-n=\"1074\">1</sup> והיינו רואים את הנשמע בשמיעה דבינה (והוא ענין הבן בחכמה שומעים את הנראה כו' וחכם בבינה<sup data-n=\"1075\">2</sup> רואים את הנשמע כו') אבל ראית העין הגשמי אינו אלא כמו לע\"ל שיראו כל בשר והיינו מה שיאמרו אלקינו זה כל אחד מראה באצבעו וכן זה אלי דקי\"ס וכה\"ג שזה בא ע\"י ראי' עין בגשמיו' דנה\"ט עתה כמו וראו מי ברא אלה<sup data-n=\"1076\">3</sup> וכמו מבשרי אחזה אלוה ממש כנ\"ל רק שעכשיו לא נזדכך חומר הגופני דשכל האנושי ולב החומרי ולע\"ל שיזדכך לגמרי בו דוקא יהי' בחי' ראיה עין ממש במהו\"ע ממש כמו שהוא לאמיתתו כנ\"ל. ואמנם הא בהא תליא דלפ\"ע הזדככות חומר הנה\"ט בבחי' מחזה שמבשרי אחזה כנ\"ל שהוא עין שלמטה כך יהיה ערך ראי' עין החכמה שבמ\"ה דנה\"א בראי' מהות ועצמות דא\"ס לומר אלקינו זה לנוכח דקאי בנשמו' לפי שהראי' דעין בגשמיות דנה\"ט בשרשו יותר עליון מראיי' דעין השכל שבנשמה כנ\"ל והיינו מה שכתוב עין בעין ב' עינים א' עין שלמט' בהזדככות נה\"ט שמבשרי אחזה שמזה דוקא יבא יתרון האו' בעין שלמעלה שהו' מה שהנשמ' תראה במהו\"ע וכמו ותמונ' ה' יבי'<sup data-n=\"1077\">4</sup> שעכשיו נא' כי לא יראני האדם וחי<sup data-n=\"1078\">5</sup> וכן ופני לא יראו<sup data-n=\"1079\">6</sup> גם בנשמת משה ולע\"ל עין בעין יראו כו' וכן והיו עיניך רואות<sup data-n=\"1080\">7</sup> כו' והיינו מה שעין ה' אל יראיו עכשיו בהעלם ולא בגלוי ולע\"ל יבא בגלוי אור הראי' עליונה בלתי התלבשות גם בחכמה עילאה ברוחניות אלא עין ה' ממש אל יראיו כמו מלמטה למעלה בנשמות שיהיו בגופי' דכתיב ונחי' לפניו ממש וכנ\"ל בענין פחד ה' שיהיה על כל כו' שזה מורה בחי' הגלוי אור למטה ממש כמו שהי' קודם החטא אדה\"ר יותר מזה כידוע וד\"ל ועם כ\"ז יובן מארז\"ל דהמתפלל צריך שיתן עיניו למטה ולבו למעלה<sup data-n=\"1081\">8</sup> דזה פלא לכאורה דלמה לא יהיה גם עיניו למעלה כמו לבן וכמאמר תנה עיניך ולבך לי<sup data-n=\"1082\">9</sup> כו' ולמה יהיו עיניו למטה ולא למעלה אך הנה ע\"פ הנ\"ל יובן בהיות שידוע שיש ב' מיני עבודה א' בעבודה שבמוח ששם משכן הנשמה האלקי'<sup data-n=\"1083\">10</sup> ונק' עובדי ה' בנשמתם והב' עבודה שבלב בשר ומוח גשמי ונק' עובדי ה' בגופם<sup data-n=\"1084\">11</sup> כו' והענין הוא כנ\"ל בהפרש שבין עין השכל לראי' עין גשמי דהנה בחי' התפעלות הנשמה מצד שרשה למעלה ה\"ז למעלה מן השכל ולב האנושי רק רוח התעוררות האלקי בבחי' מהות ועצמות דוקא והיינו בחי' עין דראי' הרוחניות שתשוקתה ליכלל במהו\"ע אלקות למעלה מן הטעם והתבוננות דמאין ליש וכה\"ג ותשוקה זו רוחניות היא בערך רוחניות אור הנשמה וע\"כ נק' שלהבת י\"ה<sup data-n=\"1085\">12</sup> ואש הוי'<sup data-n=\"1086\">13</sup> ובל' הגמ' אש שלמעלה<sup data-n=\"1087\">14</sup> אבל בחי' התפעלו' המוח והלב הטבעי ע\"פ ראיי' עין השכל והלב הטבעי להכיר לבוראו כנ\"ל כמ\"ש לבי ובשרי ירננו וכה\"ג זהו אש שלמטה שהוא רשפי אש התשוקה שבלב בשר גשמי והתפעלות המוח גשמי כהתפעלותו באהב' עצמו וכך לאהבה כי הוא חייך<sup data-n=\"1088\">15</sup> ממש וכמ\"ש בכל לבי דרשתיך<sup data-n=\"1089\">16</sup> כו' (וזהו צמאה לך נפשי<sup data-n=\"1090\">17</sup> נה\"א כמה לך בשרי נה\"ט כו') וזהו עיקר ההפרש בין עובדי ה' בנשמתם לעובדי ה' בגופם כידוע שזהו ההפרש שבין התפלה דחול לשבת<sup data-n=\"1091\">18</sup> ואמנם הנה ב' מיני עבודה והתפעלות הנ\"ל רחוקים בערך זמ\"ז ומבלבלי' זא\"ז כידוע לכל מבין שבהיות ההתפעלות העצמיות ברוחניות שבנשמות בעצמות",[["1074","1","<b>על כל דיבור. . פרחה נשמתן</b>: נסמן לעיל ט, ב."],["1075","2","<b>הבן בחכמה. . וחכם בבינה</b>: ס\"י פ\"א מ\"ד."],["1076","3","<b>וראו מי ברא אלה</b>: ישעי' מ, כו."],["1077","4","<b>ותמונ' ה' יבי'</b>: בהעלותך יב, ח."],["1078","5","<b>כי לא יראני האדם וחי</b>: תשא לג, כ."],["1079","6","<b>ופני לא יראו</b>: תשא לג, כג."],["1080","7","<b>והיו עיניך רואות</b>: ישעי' ל, כ."],["1081","8","<b>דהמתפלל. . ולבו למעלה</b>: יבמות קה, ב."],["1082","9","<b>תנה עיניך ולבך לי</b>: ראה משלי כג, כו. ירושלמי ברכות פ\"א ה\"ה. של\"ה שער האותיות אות ל (סט, א). מאמרי אדה\"א קונטרסים ע' תפג (ע' תקיב)."],["1083","10","<b>שבמוח. . הנשמה האלקי'</b>: תניא פ\"ט."],["1084","11","<b>עובדי ה' בנשמתם. . בגופם</b>: ראה גם מאמרי אדה\"א במדבר ח\"ג ע' תתפג. וש\"נ."],["1085","12","<b>שלבת י\"ה</b>: שה\"ש ח, ו."],["1086","13","<b>ואש הוי'</b>: ראה מלכים-א יט, יב. מאמרי אדה\"א נ\"ך ע' טו ואילך. שמות ח\"ב ע' תרעג. וש\"נ."],["1087","14","<b>אש שלמעלה</b>: ראה שהש\"ר פ\"ח ו, ד."],["1088","15","<b>לאהבה כי הוא חייך</b>: נצבים ל, כ [בדילוג]."],["1089","16","<b>בכל לבי דרשתיך</b>: תהלים קיט, י."],["1090","17","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["1091","18","<b>ההפרש. . דחול לשבת</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' קצא ואילך ובהנסמן שם בע' קפה."]]],[2800530095,"אלקות אז כאשר ישכיל בעיני בשר בטעם ושכל שבמוח ולב גשמי כנ\"ל יבלבל זה להתפעלות העצמיות לפי שהוא כמסתיר על ידי הגשמת המוח ולב ואם יעמיק בהתפעלות המוח ולב גשמי יסתלק אור התפעלות הרוחניות ולא ישכנו כא' וע\"כ אם היו גם עיניו למעלה כמו שלבו למעלה דוקא לא ישכנו יחד אלא צריך שיהיו עיניו למטה ולבו למעלה דהיינו שישכיל בעיני בשר בהתבוננות מאין ליש בבחי' ראיה והכרה חושיי' דוקא כנ\"ל שזהו הנק' עיניו למטה בהתפשטות אלקי בנבראי' כמו ענין מי ברא אלה הנ\"ל ויבא לכלל התפעלות המוח והלב גשמי כמו לבי ובשרי ירננו כו' כנ\"ל ולבו יהיה למעל' היינו שנקודת לבבו בבחי' התקשרות העצמיות דנשמתו ורוחו תשוב אל ה' בהתפעלות רוחניות ועצמיות במהו\"ע האלקות שלמעלה מהתבוננות ושכל וטעם שבמוח הגשמי שנק' עין ראיה הרוחניות כנ\"ל וזהו לבו למעלה במהו\"ע בבחי' סובב כו' כי אם עיניו יהיה בראיה ברוחניות למעלה מצד הנשמה ולבו בלב בשר למטה לא יהיה יתרון אור התפעלות בנשמה כלל רק דוקא ע\"י שעיניו למטה בראיה והכרה חושיי' דוקא כנ\"ל מזה יבא יתרון אור התפעלות העצמות דנשמה מטעם שיתרון האור העליון יבא מתוך החושך דנוגה דוקא כנ\"ל בפי' עין בעין שלפי עין שלמטה יהיה עין שלמעלה בראיה הרוחניות דנשמ' האלקית וכמ\"ש מבשרי אחזה אלוה מבשרי דוקא ואז לא יפול הנופל לעולם בפתחו עיניו לראות גשמיות העולם כי הרי נתאמת גם בעיני בשר אחדות ה' בעולמות דוקא וכמו מי ברא אלה שאין דבר חוץ ממנו ית' וכולא קמי' כלא<sup data-n=\"1092\">19</sup> כו' בראי' והכרה חושיו' משא\"כ אם הי' עיניו למעלה רק בראי' רוחניות דעין השכל דנשמה לא היה מועיל לאחר זמן התפלה כשילך בשוק כשיגבור עליו חומר גופו ועניני העולם שיפול בנפילות רבות לתפוס הטפל לעיקר וישכח על ה' המהוה הכל מאין כו' מאח' שלא היה התפעלות שלו רק בנשמתו ברוחניות הגם שלבו היה למטה הרי מצד רוחניות הנשמ' לבד שהיו עיניו כלפי מעלה יהיה להיפך אחר זמן שעיניו הגשמיי' יתפסו הטפל לעיקר ומה שהי' לבו למטה בהתפעלות לב בשר חלף ועבר במעט זמן שבתפלה רק דוקא כשעיניו למטה ולבו למעלה יחקק ראי' והכרה חושיו' בעינו ולבו גם כל היום לא יפרד כו' וד\"ל. ובכ\"ז יובן מה שאמ' ריב\"ז<sup data-n=\"1093\">20</sup> לתלמידיו שאינו יודע באיזה דרך מוליכין אותו אם לג\"ע או לגיהנם דזה יפלא מאד הרי ידע בנפשו בתום לבו בעבודתו ותורתו כל ימיו שלא זז מאהל תורה ועבודה בירא' אלקי' כל ימיו כי הי' יחיד בדורו בתו\"מ ובמס\"נ בק\"ש ותפלה כו' אך הנה עפ\"י כל הנ\"ל יובן בהיות שיש הפרש גדול בין הנשמ' האלקי' לחומר הנה\"ט שבגוף ויריד' הנשמה לברר לגוף כנ\"ל שתשכיל בעיני בשר בראי' והכרה ממש עד שתוכל גם היא לידבק למעלה בכל כוחותיה הטבעיי' כו' וריב\"ז לרוב ענוה שלו לא ידע בנפשו האלקי' אם בירר בכי טוב לנה\"ט שלו בכל כחותיה על ידי תו\"מ ועבודה שלו בתפלה כו' הגם שמצד נשמתו היה יודע היטב שהיתה דבוק' וחשוק' תמיד למעלה ליכלל במהו\"ע כניצוץ בפני אבוקה מצד עצם התקשרו' שלה כנ\"ל ובפרט בתו\"מ ויראה ואהב' האלקי' בשלהב' י\"ה",[["1092","19","<b>וכולא קמי' כלא</b>: ראה זהר בהקדמה יא, ב. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1093","20","<b>שאמ' ריב\"ז</b>: ברכות כח, ב. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תקנז. וש\"נ. דברים ח\"א ע' עט. וש\"נ. ח\"ב ע' תקא. וש\"נ."]]],[2800530096,"כנ\"ל:\n<b>(וראי'</b> לזה מר\"ע שהיה מצטער בנפשו על בכל נפשך אפי' נוטל<sup data-n=\"1094\">1</sup> כו' מתי יבא לידו בפו\"מ במס\"נ הגוף כו' הרי גם שהיה יודע בכי טוב במס\"נ שבנשמתו שהיא אמיתית מצד עצם מהותה בשרשה עכ\"ז היה מצטער על מס\"נ שבנה\"ט שבגוף עד שהיה מסופק בזה כי גם שהיה לבו למעלה ועיניו למטה כנ\"ל שגבר אור הנשמה והיה לו התפעלות האמיתית במוח ולב הטבעי ג\"כ כענין לבי ובשרי כו' וכמו מבשרי אחזה כנ\"ל הרי לא היה זה בפו\"מ רק בכח<sup data-n=\"1095\">2</sup> לבד רק שהיה מוכן לזה כמ\"ש במ\"א) וביאור הדברים הנה ידוע ענין הגיהנם שהוא אש דק דנוגה שמברר לרע דנה\"ט שמעורב בכל חלקי רע דק\"נ באש זרה שיתברר ויצורף כל הרע ואמנם אחר הבירור נעשה לבוש טהור לנשמה ונק' לבושי דכיא<sup data-n=\"1096\">3</sup> וטרם הבירור בגיהנם נקרא לבושי מסאבותא<sup data-n=\"1097\">4</sup> והיינו לבושים הצואים שנעשו מכל עון וחטא ואיסור קל של ד\"ס<sup data-n=\"1098\">5</sup> וכמו ביהושע כה\"ג שלא מיחה<sup data-n=\"1099\">6</sup> בנשים נכריות שאמרו עליו הסירו הבגדים הצואי' מעליו<sup data-n=\"1100\">7</sup> כידוע (ואמנם גם לנשמה עצמה יש בירור באש הגיהנם במה שנתלכלך עצם מהותה בפגם וחסרון ע\"י טומא' העון עד שתטה' וכמ\"ש ונפש כי תחט'<sup data-n=\"1101\">8</sup> כו' וכמו שאו' בוידוי דק\"ש<sup data-n=\"1102\">9</sup> שפגמתי באות יו\"ד כו' כידוע) וענין הג\"ע הוא תכלית העונג והוספ' האור האלקי בבחי' נועם ה' לנשמה בפנימית עצמות' כמו הנשמות שנהנין מזיו בג\"ע כידוע ובפרט בכל חדש ושבת שעולין הנשמות<sup data-n=\"1103\">10</sup> בעילוי אחר עילוי וא\"כ יובן מזה עכ\"פ בענין בירור שמברר' הנשמה לגוף שזהו מה שיכול להיות עלי' הנפש השכלית הטבעית לעלות גם היא לקדוש' האלקי' ומה שלא בירר' בזה העולם יהיה הבירור שלה בגיהנם עד שלא ידח גם אחד מן הנפשות הטבעית כו' וד\"ל ויש להבין בזה דאיך אפשר שנה\"ט החיונית כמו שכל במוח גשמי ומדות טבעית שבלב גשמי ששרשם בק\"נ שהרע גובר שם יוכל גם הוא לעלות ממש כמו הנשמה בעלותה בעילוי אחר עילוי מאחר שנעשה הנה\"ט לבוש טהור לנשמה אחר הבירור שלה כנ\"ל אך הענין הוא דאם היה שרש הנה\"ט ברע דק\"נ לא היה באפשר שתבורר ואמנם באמת שרש שרשה למעלה הרי הי' בבחי' הממוצע שבין אור הקדושה האלקי' להיכלות הקליפות דק\"נ וכה\"ג והוא הנקרא בחי' צלם שזהו מה שיש חיבור על ידם אור ושפע האלקי מחיצוניות הכלים דע\"ס דקדושה להיכלות הנוגה שהוא חיצוניות שמרי האופנים ופנימית המזלות הרוחניי' (כמ\"ש במ\"א ע\"פ והיה העטופי'<sup data-n=\"1104\">11</sup> כו'):\n(כז) <b>ויובן</b> זה במה שאנו רואים בחיבור וקשר שיש בין הנשמה האלקי' ששרשה בע\"ס דעשיי' דקדושה ובין נה\"ט החומרית ששרשה בנוגה דעשייה כי אנו רואים שהתפעלות העונג האלקי ממש שבנשמה בראי' הרוחניות כנ\"ל יומשך מיד לבחי' התפעלות גשמיות דעונג גשמי שבמוח ולב בשר גשמי כענין עבדו ה' בשמחה<sup data-n=\"1105\">12</sup> הרי שמחה וטוב לב הזה בא בלב ומוח גשמי דוקא אע\"פ שהשמחה לאלקי' הוא ברוחניות דנשמה האלקי' וכן ואהבת בכל לבבך<sup data-n=\"1106\">13</sup> בלב בשר דוקא אע\"פ שהאהבה זו שרשה",[["1094","1","<b>מר\"ע. . אפי' נוטל</b>: ברכות סא, ב."],["1095","2","<b>מר\"ע. . רק בכח</b>: ראה שע\"ת ח\"א מה, ד ואילך. מאמרי אדה\"א שמות ח\"א ע' רסב."],["1096","3","<b>לבושי דכיא</b>: זהר שלח קסט, ב."],["1097","4","<b>לבושי מסאבותא</b>: תניא פ\"ו."],["1098","5","<b>ואיסור קל של ד\"ס. . שלא מיחה</b>: ראה גם תניא פ\"א."],["1099","6","<b>ביהושע כה\"ג שלא מיחה</b>: ראה סנהדרין צג, סע\"א. מאמרי אדה\"א נ\"ך ריש ע' קצב. הנחות תקע\"ז ע' ריב. וש\"נ."],["1100","7","<b>הסירו הבגדים הצואי' מעליו</b>: זכרי' ג, ד."],["1101","8","<b>ונפש כי תחט'</b>: ויקרא ה, א."],["1102","9","<b>שאו' בוידוי דק\"ש</b>: סידור אדה\"ז. ראה הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'פא."],["1103","10","<b>בכל חדש ושבת שעולין הנשמות</b>: נסמן לעיל לד, א."],["1104","11","<b>והי' העטופי'</b>: ויצא ל, מב. ראה ד\"ה זה במאמרי אדה\"ז על פרשיות התורה ח\"א ע' קסט ואילך. שע\"ת ח\"א נז א ובהנסמן במ\"מ לשם."],["1105","12","<b>עבדו ה' בשמחה</b>: ע\"פ תהלים ק, ב."],["1106","13","<b>ואהבת בכל לבבך</b>: ואתחנן ו, ה [בדילוג]."]]],[2800530097,"העצמי ברוחניות דנשמה כנ\"ל אלא צ\"ל שיש בחי' ממוצע שמחבר רוחניות דנשמה לגשמיות דנה\"ט במוח ולב גשמי והן הנק' פרקי הצלם והיינו בחי' כחות הממוצעים שמחברים וממשיכים ומביאים אור השפע האלקי לנה\"ט בכל פרט מפרטי השפע אלקי ברצון ושכל ומדות וגם מעשה המצוה בפ\"מ ותשובה בפ\"מ וכה\"ג והן הצריכים בירור ועלי' שהם יוכלו לעלות בעלות הנשמה ויכולים להמשיך כל אור אלקי שבנשמה בגוף כמו בעונג ושמחה אלקי' שיבא לגוף וכן בתשובה ומע\"ט כו' וכל שלא בירר לפרקי הצלם דנה\"ט שנקרא מזלא כו' הממוצע לא יבא כל אור הנשמה בגוף לבררו וישאר בלא בירור לפי שהמה בחי' מקוריים לשפע הבאה בבחי' נוגה ונקרא לבוש החשמל כו' ואמנם בתכלית בירורו יהיה לבוש מזהיר לנשמה בעלות' בג\"ע וכו' (וכמ\"ש בכתבי האריז\"ל בשער הצלם<sup data-n=\"1107\">14</sup> ) וזהו שהיה ריב\"ז מסופק אם יוליכו אותו לג\"ע או לגיהנם כי לא ידע בנה\"א אם בירר בכי טוב לבחי' צלם הנפש המחבר לנה\"א בנה\"ט שבלתי זה לא בא בירור דנשמה בגוף מן הכח הרוחני אל הפועל בגשמיו' ומבואר למעלה שלפ\"ע הזדככות החומר דראיה חושיות בגוף ובהתפעלות גשמיות דמוח ולב בש' וכל כחותיה הטבעיי' דוקא תבא הנשמה לבחי' ראיה הרוחניות האלקי' במהו\"ע כו' דע\"י הבירור דנשמה לגוף תעלה למעלה משרשה כנ\"ל הטעם ביתרון האור שבא מתוך החושך דוקא וזהו עין בעין כו' ומבשרי אחזה דוקא ע\"כ לא היה יודע אולי יוליכוהו לגיהנם לברר לבחי' הצלם דנה\"ט שנקרא מזלא כו' כדי שעי\"ז יוכל לבא לראית הרוחניות דנשמה בג\"ע כו' ובלתי זה לא יהיה לו דרך לבא לראי' הרוחניות דנשמה בזיו השכינה בג\"ע מטעם הנ\"ל וד\"ל (וזהו ג\"כ הטעם שהיה ר\"ע מצטער על מס\"נ בפו\"מ בגוף דוקא שעי\"ז יהיה לנשמה עלי' גדולה במהו\"ע משא\"כ במס\"נ בכח ולא בפ\"מ וד\"ל) ובכל הנ\"ל יובן מה שמצינו בכל סיפורי השבחים שבספר תהלים מדבר הכל בדברים פשוטים שהם בסוף כל השתלשלות עולמות הרוחניי' עד הללו את ה'<sup data-n=\"1108\">15</sup> מן הארץ תנינים כו' אש וברד שלג כו' עץ פרי וכו' וכה\"ג בכל מזמורי תהלים שבפסד\"ז וכמו בברכי נפשי<sup data-n=\"1109\">16</sup> כו' שמספר הכל בריבוי הנמצאים ונבראים גשמיי' ואיך שכולם תחת ממשלתו והוא ית' בורא הכל כו' הגם שכללותם אינם רק בחי' הארה בעלמא מעצמותו כו' ועיקר המכוון הוא דוקא לספר בשבח הנפלאות שבמעשיו כמו שאמר רבות עשית<sup data-n=\"1110\">17</sup> כו' נפלאי' מעשיך<sup data-n=\"1111\">18</sup> וכו' וכמובן בכמה כתובים שמכוין לספר בשבח המעשה דוקא וזה פלא דבאמת כולא קמי' כלא חשיבי כו' אפי' העולמות הרוחניי' עד רום המעלות כידוע ומכ\"ש בחי' העשיה בפ\"מ שמקורם רק בחי' דיבור בצירופי אותיות כידוע וכמ\"ש כולם בחכמה עשית<sup data-n=\"1112\">19</sup> כו' וא\"כ למה אומר בדרך שבח גדול מה רבו מעשיך ה'<sup data-n=\"1113\">20</sup> כו' אך הנה עפ\"י כל הנ\"ל יובן הטעם להיות שבחי' גלוי אלקות דוקא בדברים תחתונים כמו בעולם השפל הזה בהתהוות יש מאין בבריאה גשמיות דוקא שנקרא פועל ה' ממש כמ\"ש לכו חזו מפעלות אלקים<sup data-n=\"1114\">21</sup> כו' וכן נפלאים מעשיך",[["1107","14","<b>בשער הצלם</b>: ע\"ח שכ\"ו פ\"א."],["1108","15","<b>הללו את ה'</b>: תהלים קמח, ז. ח."],["1109","16","<b>בברכי נפשי</b>: תהלים קאפיטל קד."],["1110","17","<b>רבות עשית</b>: תהלים מ, ו. בסידור כאן (רפח, א) לא הובא פסוק זה."],["1111","18","<b>נפלאי' מעשיך</b>: שם קלט, יד."],["1112","19","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["1113","20","<b>מה רבו מעשיך ה'</b>: התחלת הכתוב כולם בחכמה עשית."],["1114","21","<b>לכו חזו מפעלות אלקים</b>: תהלים מו, ט. וראה במנחת שי שם. זהר בראשית נח, ב ובמפרשים שם. אמ\"ב פתח השער יא, ג [אבל ראה שם ח, ד]. תו\"ח שמות קט, סע\"ב. קיא, א. קלח, ב. תעח, א. מאמרי אדה\"א דברים ח\"ב ע' תקס. נ\"ך ע' תעב."]]],[2800530098,"ממש שם יפול ענין הראיה הגשמיות כמ\"ש שאו מרום עיניכם וראו כו' כמו הרקיע וכל צבאם וכן הארץ וכל אשר בה כעץ פרי כו' ושלג ואש וכו' שאע\"פ שזה בא מן הצמצום כח אלקי היותר אחרון שהוא מל' דמל' דעשי' שמוסתר בחיצוניות הכלים דעשי' אבל הרי הוא ראי' מקרוב ברוחניות שבגשם פועל האלקי שמזה דוקא יבא יתרון האור בראי' הרוחניו' דנשמ' גם בעולמו' הרוחניי' היותר עליוני' כג\"ע העליון ולמעלה מעלה כו' מטע' כל הנ\"ל ולפי שזה בחי' ההסת' אלקי כ\"כ שבא בבחי' מסך מבדיל עד נוגה דעשי' הרי שרשו הראשון הי' בבחי' ז' מלכי' קדמאין דתהו שלפני האצי' שהי' שם השבירה בכלי' שירדו ונפלו עד למטה מטה להיות בחי' הסתר אחר הסתר במסכי' דלבוש החשמל עד לבוש דנוגה דעשי' א\"כ כאשר יראו אור האלקי בפועל המעשה דוקא זהו ענין יתרון האור שבא מן החשך דתהו שקדם לתקון דאצי' וכמו לאחר הבירור בתכלית כמו לע\"ל שיגלה כבוד ה' ויוסר ההסתר והמסך הזה (כמ\"ש רז\"ל לע\"ל יוציא הקב\"ה חמה מנרתקה<sup data-n=\"1115\">1</sup> שזהו הסרת שם אלקים שירד בהסתר אחר הסתר כו' שהוא הנרתק המכסה ומסתיר על שם הוי' ע\"כ יראו אז כל בשר בשם הוי' דוקא ובתוס' אור כיתרון האור<sup data-n=\"1116\">2</sup> כו') לפי שיתעלה אז המתברר למעלה מן המברר כידוע דשם ב\"ן לאחר הבירור יעלה לשרשו בס\"ג<sup data-n=\"1117\">3</sup> דתהו שלמעלה מבחי' שם מ\"ה<sup data-n=\"1118\">4</sup> דתיקון המברר כו' ע\"כ גם עכשיו ששם אלקי' מסתיר ומעלים לשם הוי' כמ\"ש שמש ומגן ה' אלקי'<sup data-n=\"1119\">5</sup> מ\"מ ע\"י ראי' והכרה חושיי' בכח אלקי זה המהוה מאין ליש בבריאה גשמיי' דשמים וארץ הלזו הגשמיים דוקא יהי' יתרון האור דראי' עין השכל שבנשמה עד רום המעלו' כנ\"ל ולכך כל השבחי' בגדולת הבורא אינו אלא בגילוי אור אלקי בפעולותיו הגשמיי' דוקא כנ\"ל (וכנ\"ל<sup data-n=\"1120\">6</sup> דראי' מקרוב הוא בדבר השפל ונמוך ששרשו למעל' מן השמיע' דבינה מרחוק גם באורו' היותר עליונים והוא הגורם ראי' עין הרוחני דנשמה במהו\"ע כמו לע\"ל משום דנעוץ תחלתן בסופן<sup data-n=\"1121\">7</sup> דוקא וכמ\"ש ראו עתה<sup data-n=\"1122\">8</sup> כי אני אני הוא פי' ראו<sup data-n=\"1123\">9</sup> בראי' חושיי' בכח הפועל אלקי בפעולותיו הגשמיית גם שאינו רק בבחי' מל' דמל' דעשי' בשמים וארץ וכל אשר בהם כנ\"ל שזהו אני בסוף כל המדריגות אבל זהו אני שבראש כל דרגין שהוא בחי' מל' דא\"ס עצמו שלפני הצמצו' הראשון כידוע בענין אני ראשון ואני אחרון<sup data-n=\"1124\">10</sup> דאותו אני ראשון שהוא מל' דא\"ס שמאי' בקו\"ח הוא אני שבאחרית ההשתלשלו' עד מל' דמל' דעשיה וזהו אני אני הוא בלי הפרש כלל ודוקא ע\"י בחי' ראי' מקרוב כמ\"ש ראו כי אני אני כו' וכמ\"כ מ\"ש הביטו אליו ממש כו' משום דהא בהא תליא כנ\"ל וכמשל הרואה בעינו את המלך שרואה כל פנימיותו עם חיצוניותו ובלבושיו ממש בשוה וד\"ל משא\"כ בראית השכל שאינו משיג לפנימיותו כמו שהוא באמיתת עצמותו כמ\"ש למת\"ב<sup data-n=\"1125\">11</sup> כו' וכ\"ש שאינו משיג ללבושיו ומעשיו ופעולותיו כי איך יצייר בראיית השכל הרוחני מהות כח פעולותיו כמו שהוא מוסתר בפעולה כו' אבל בראי' חושיות הרי יכיר במהות כח המלובש בפעולתו ויכיר במהות ועצם פנימיות שלו כאשר רואה בעיני בשר כח פעולתו עם",[["1115","1","<b>לע\"ל. . חמה מנרתקה</b>: ראה ע\"ז ג, סע\"ב. תו\"ח בראשית לה, א ובהערה 12."],["1116","2","<b>כיתרון האור</b>: קהלת ב, יג."],["1117","3","<b>דשם ב\"ן. . בס\"ג</b>: נסמן לקמן קמא, ב."],["1118","4","<b>בס\"ג. . שם מ\"ה</b>: נסמן לקמן שם."],["1119","5","<b>שמש ומגן ה' אלקי'</b>: נסמן לקמן קמד, ב."],["1120","6","<b>(וכנ\"ל</b>: גם בדפו\"ר לא נדפס סיום החצע\"ג."],["1121","7","<b>דנעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א מ\"ז."],["1122","8","<b>ראו עתה</b>: האזינו לב, ט. ראה גם לקמן נח, ב."],["1123","9","<b>ראו</b>: ניתוסף ע\"פ דפו\"ר."],["1124","10","<b>אני ראשון ואני אחרון</b>: נסמן לקמן קיד, א."],["1125","11","<b>למת\"ב</b>: ת\"ז בהקדמה (יז, א)."]]],[2800530099,"פנימי' שלו כמו שהוא שא\"א לציירו בראי' שכל כלל כמו שהוא ממש כנ\"ל בענין אינו דומה שמיעה לראיה באריכות ונמצא דראי' המהות עם ראית כח פעולתו הכל אחד בראיה חושיית וז\"ש הביטו אליו ממש והוא כאשר הראיה חושיית היא בכח פעולתו דוקא דהכל אחד משא\"כ בראיית השגת השכל ולזה אמר ראו כי אני כו' וד\"ל ובזה יובן מ\"ש בזהר<sup data-n=\"1126\">12</sup> ע\"פ לכבודי בראתיו<sup data-n=\"1127\">13</sup> כו' רק בגין דישתמודעין<sup data-n=\"1128\">14</sup> ליה שידעו ויכירו אותו בפעולותיו דוקא שהוא שם אד' שם הפעולה ולא שם העצם דעי\"ז דוקא יכירו במהו\"ע דוקא מטעם הנ\"ל בענין עין בעין כו' וד\"ל וכל ב\"נ דלא אשתדל למנדע ליה<sup data-n=\"1129\">15</sup> לקוב\"ה בהאי עלמא לית ליה חולקא בההוא עלמא דזה פלאי לכאורה דבהאי עלמא לא ישיג הידיעה רק במציאות התפשטות אלקות בנבראים גשמיים לבד כנ\"ל ואיך יגיע בזה דוקא לבחי' ידיעת מהו\"ע כו' בההוא עלמא שהוא בעוה\"ב שיאמר אלקינו זה כו' אך הענין הוא משום דמידיעה זו בראיית עיני בשר כמו מבשרי אחזה אלוה כנ\"ל דוקא יגיע מזה לידיעה והכרה במהו\"ע דלע\"ל שכולם ידעו אותו כנ\"ל דהא בהא תליא וזהו שאמר דלית ליה חולקא לנשמתו בראיית המהות בההוא עלמא אם לא ישתדל בכל כח יגיעתו בנפש הטבעית להכיר במוח ולב בשר למינדע ליה לקוב\"ה בהאי עלמא דוקא בכח פעולותיו בסיפורי השבחים שבתהלים בכל נפלאות ה' במעשיו הגשמיים דוקא דעוה\"ז השפל כו' וד\"ל (וזהו<sup data-n=\"1130\">16</sup> שלא זכה כל צ\"ג לגלוי אליהו ורוה\"ק עד שתחלה הגיע למדריגה זו דראיה והכרה חושיית בכח הפועל האלקי בנפעל כמו שיהיה לע\"ל שידע כל פעול כו' שזהו דוקא ע\"י מס\"נ האמיתית בהזדככות גדולה מאד בנה\"ט בכל כחותיה החומריים להפוך כל תאוה חומריית מן הקצה לקצה דוקא שאז דוקא עינים לו לראות בראי' חושיי'<sup data-n=\"1131\">17</sup> בכח אלקי שבכל בריאה ופעולה גשמיית (וכידוע בהה\"מ ז\"ל שהגיע בסוף ימיו לזה אחר כל הצומות וסיגופים ועוצם הטהרה וקדושה בעבודה תמה שבמוח ולב בשר דוקא כמו שאמ' בפירוש על מה שהכיר לפועל הכלי<sup data-n=\"1132\">18</sup> מתוך הכלי שהיה סומא בעין א'<sup data-n=\"1133\">19</sup> כו' שא\"א להיות זה כ\"א במי שיכול להכיר בכל רוחני שבגשם עד כללו' אור החיות האלקי הרוחני שהוא כח ומקור לכל פעולה ובריאה מאין ליש והוא זכה לזה שזהו בחי' התלבשות דראיה הרוחניות לראות בגשמיות גם מסוף העולם עד סופו<sup data-n=\"1134\">20</sup> ולראות העתידות עד שקרוב לנבואה ורוה\"ק דהכל ענין אחד כמובן מתוך כל הנ\"ל וד\"ל):\n(כח) <b>ובכל</b> הנ\"ל יובן מ\"ש במ\"ת אנכי ה' אלקיך<sup data-n=\"1135\">21</sup> אשר כו' אנכי דוקא דהנה לפי המובן מכל הנ\"ל יש ג' מדריגות דרך כלל הא' בחי' השגת המציאות שאינו בא בראית שכל אנושי אלא בהשגת שכל לבד וגם זה אינו רק בבחי' מציאת התפשטות אלקות בנבראים ולא במהותו כלל והיינו כל מדריגות המלאכי' עליונים שאומרי' שירה<sup data-n=\"1136\">22</sup> שזהו רק בבחי' השגת אור מציאת אלקות הבא בדרך צמצום גדול באיכות התהוות בריא' מאין ליש והיינו מה שאינו משיג רק אור כח אלקי שמשם מציאת חיותו והתהוותו לבד וזהו אופן",[["1126","12","<b>בזהר</b>: ראה (רע\"מ) בא מב, ב."],["1127","13","<b>לכבודי בראתיו</b>: ישעי' מג, ז [הובא ברע\"מ שם ע\"א]."],["1128","14","<b>לכבודי. . בגין דישתמודעין</b>: כ\"ה בכ\"מ — ראה תו\"ח בראשית כה, ג. מאמרי אדה\"א ויקרא ח\"א ע' רלב. במדבר ח\"ג ע' א'פט. דברים ח\"א ע' קכ וע' רעח. ח\"ג ע' א'נו וע' א'סח."],["1129","15","<b>וכל ב\"נ. . למנדע ליה</b>: ראה זהר תרומה קסא, ב."],["1130","16","<b>(וזהו</b>: גם בדפו\"ר לא נסמן סיום החצע\"ג."],["1131","17","<b>עינים לו לראות בראי' חושיי'</b>: ראה גם או\"ת יתרו לד, א [מהדורת קה\"ת]."],["1132","18","<b>בהה\"מ. . שהכיר לפועל הכלי</b>: ראה מאמרי אדה\"א נ\"ך ע' קפד ”כוס של כסף\". וש\"נ."],["1133","19","<b>בהה\"מ. . סומא בעין א'</b>: ראה גם לקו\"ש (שבת חזון) כרך כט ע' 23. ס' השיחות תשמ\"ט ח\"ב ע' 590 בהערה."],["1134","20","<b>בהה\"מ. . מסוף העולם עד סופו</b>: ראה גם ס' החקירה נ, א. סה, א."],["1135","21","<b>אנכי ה' אלקיך</b>: יתרו כ, ב."],["1136","22","<b>המלאכי'. . שירה</b>: ראה גם מאמרי אדה\"א קונטרסים ע' שעז."]]],[2800530100,"השירה שלו וזה הבא בהשתלשלות מדריגות בכל עו\"ע לפי ערך כל א' וכל עול' לפי ערכו היינו לפי ערך הצמצום וההסתר כו' עד שבעולם העשי' שם נתמעט האור האלקי יותר בהסתר בחיצונית הכלים דמל' דעשיה על ידי ריבוי המסכים כו' עד בחי' נוגה דעשיה בע' שרים<sup data-n=\"1137\">1</sup> של מטה כשיורדים להשפיע בהגשמה דדצח\"מ יש בהם טוב ורע פירוד וביטול לפרקים כו' כנ\"ל שיש יראה ופחד אלקים לפרקים גם במלכי אדמה כמו מי לא יראך<sup data-n=\"1138\">2</sup> כו' יראו מה'<sup data-n=\"1139\">3</sup> כו' וכמו חסידי אוה\"ע שמודי' בהודאה וביטול ממש וקרו לי' אלוה<sup data-n=\"1140\">4</sup> כו' ולהיפך הרבה יש שהן בבחי' פירוד גמור למרוד כו' כנמרוד וכה\"ג וכמו בשר של מצרים שאמ' לי יאורי<sup data-n=\"1141\">5</sup> כו' ואמ' מי ה'<sup data-n=\"1142\">6</sup> כו' כי הם מקבלים ממ\"ח צירופי' האחרונים<sup data-n=\"1143\">7</sup> דשם אלקי' דעשיה כו' וזהו אשר הוצאתיך מארץ מצרים שהן י' כתרין<sup data-n=\"1144\">8</sup> דק\"נ ופרעה כתר דקליפה<sup data-n=\"1145\">9</sup> שכולל נש\"ט והיינו אלקי מצרים<sup data-n=\"1146\">10</sup> שעשה בהם שפטים ואותו' ומופתים כו' שהוא ביטול ושבירה למסך דק\"נ המעלי' ביותר וכמ\"ש בזהר דתבר שלשוליהון לעילא<sup data-n=\"1147\">11</sup> כו' וזהו ויסר את אופן מרכבותיו<sup data-n=\"1148\">12</sup> לעילא כו' וזה נק' יציאה מן המיצר וחושך ואפילה לאור גדול אך מה שיצאו ממצרים דנש\"ט אין זה שיצאו רק מבחי' הפירוד גמור דק\"נ דמצרים להיות בבחי' הביטול בהשגת מציאות אלקות כביטול והתפעלות המלאכים דקדושה שהן תמיד בביטול היש לאין כי הרי נגלה עליה' ה' בכבודו ובעצמו והוא הנק' אנכי מי שאנכי<sup data-n=\"1149\">13</sup> כו' וכמ\"ש אנכי ה' אשר הוצאתיך מא\"מ אנכי דוקא וכידוע שזה הי' השגת המהות ולא השגת המציאות לבד וכמו בקי\"ס שאמרו זה אלי<sup data-n=\"1150\">14</sup> כו' וכנ\"ל בענין ראתה שפח'<sup data-n=\"1151\">15</sup> על הים מה שלא ראה יחזקאל כו' דזה למעלה מן הנבואה שהנבואה באה בהשתלשלות במראה ומחז' דבחי' המל' לבד שנק' מראה דמות כבוד ה'<sup data-n=\"1152\">16</sup> וכמו חזון ישעיה<sup data-n=\"1153\">17</sup> כו' אבל ראיה זו שאמר זה אלי זה ממש בחי' ראיית המהות שלמעלה מבחי' השתלשלות דהעלם וגלוי כו' וזהו מדריג' הב' בראיית המהות שלמעל' מראי' והשג' במציאו' לבד אבל זהו ג\"כ בא' בשני מדריגות הא' הוא בגלוי שנגלה עליהם במצרים ע\"י בחי' מצה שנק' מיכלא דמהימנותא<sup data-n=\"1154\">18</sup> כנ\"ל שמאיר מבחי' מהו\"ע דאבא אבל בבחי' הלבשה בקטנות לבד כענין התינוק שיודע לקרות אבא כו' כנ\"ל והב' בחי' ראיית מהו\"ע ממש שלא ע\"י הלבשה בקטנות דמצה וזה היה בקי\"ס שהוא מעין העוה\"ב ולא כמו במ\"ת שהיה גלוי מהו\"ע ולא בראי' חושיית דמה שכל העם רואי' זהו בראיי' העין רוחניות דנשמה עכ\"פ כנ\"ל אבל לא בראיי' עין הגשמי ובקי\"ס היה בראיה חושיי' דזהו מ\"ש ראתה שפחה כו' ראתה ממש מטעם הנ\"ל ונמצא דבראיי' המהות יש ג' מדריגות א' בבחי' הלבשה בקטנות שזהו בימי הפסח ע\"י מצה והב' בראיי' עין דנשמה שבגוף ברוחניות כמו במ\"ת והג' בראיי' חושיית דנפש הטבעי' כמו לע\"ל שכולם ידעו אותו וכן בקי\"ס הי' זה מצד עוצם הגלוי מלמעלה למטה אע\"פ שלא היה בהן הזדככות החומר כלל וז\"ש הפך ים<sup data-n=\"1155\">19</sup> כו' בנהר יעברו ברגל שם נשמחה בו שם דוקא לפי שיהיה גלוי מהו\"ע למטה כמו למעלה ממש מצד הזדככות החומר כו' וכנ\"ל בענין עין בעין יראו כו' וד\"ל ויובן זה דרך פרט עפ\"י כל הנ\"ל בענין מצה ופסח ובענין עצרת לה' בזש\"פ בקי\"ס כו' דהנה כל השנה אור האלקי בא דרך השתלשלות בצמצומי'",[["1137","1","<b>בע' שרים</b>: נסמן לעיל מ, א."],["1138","2","<b>מי לא יראך</b>: ירמי' י, ז."],["1139","3","<b>יראו מה'</b>: תהלים לג, ח."],["1140","4","<b>חסידי אוה\"ע. . אלוה</b>: נסמן לעיל מ, א."],["1141","5","<b>בשר. . לי יאורי</b>: נסמן לקמן קמו, ב."],["1142","6","<b>בשר. . מי ה'</b>: ראה גם לעיל מ, א ובהנסמן לשם."],["1143","7","<b>ממ\"ח צירופי' האחרונים</b>: נסמן לקמן קמו, ב."],["1144","8","<b>י' כתרין</b>: נסמן לקמן קמז, א."],["1145","9","<b>ופרעה כתר דקליפה</b>: ראה זהר בא לד, א ובהגהת הרח\"ו שם. מאמרי אדה\"א בראשית ע' תצא. דברים ח\"ב ע' תקמג ובהנסמן בהנ\"ל."],["1146","10","<b>אלקי מצרים</b>: בא יב, יב."],["1147","11","<b>דתבר שלשוליהן לעילא</b>: ראה זהר בא לז, ב. מ, א. בשלח מט, א."],["1148","12","<b>ויסר את אופן מרכבותיו</b>: בשלח יד, כה."],["1149","13","<b>אנכי מי שאנכי</b>: נסמן לעיל יג, א."],["1150","14","<b>זה אלי</b>: בשלח טו, ב."],["1151","15","<b>וכנ\"ל. . שפח'</b>: לד, א."],["1152","16","<b>המל'. . מראה דמות כבוד ה'</b>: יחזקאל א, כח. ראה זהר ויקהל רטו, א ובהגהת הרח\"ו שם."],["1153","17","<b>חזון ישעיה</b>: ישעי' א, א."],["1154","18","<b>מצה שנק' מיכלא דמהימנותא</b>: נסמן לעיל ח, ב."],["1155","19","<b>הפך ים</b>: תהלים סו, ו."]]],[2800530101,"רבים מאד בכל עולם לפי ערכו כנ\"ל ובזה הובדל ימי הפסח שמאיר בנש\"י מבחי' עצמות מוחין דאבא ששם גלוי אור מהו\"ע דא\"ס ב\"ה כנ\"ל אך זהו בא בדרך הלבשה בקטנות דטעם מצה שהיא האמונה שהיא נתייחדה לכנ\"י לבד שלמעלה הרבה מביטול דמלאכים עד חסידי אוה\"ע דקרו לי' כו' כנ\"ל וביאור הדברים מבואר למעלה בענין הלבשה זו דקטנות כמשל התינוק שיודע לקרות כו' שידיעה זו למעלה מידיעה שע\"י השגת שכל שאינו מגיע רק במציא' ולא במהו' אבל מהו' ועצמות שלא יוכל לבוא בשום השגה רק בהלבשה זהו כמשל ידיעה זאת דתינוק שיודע לקרות אבא משום דיודע במהו\"ע אביו רק שמלובש בקריאה זו בהעלם מה שיהי' לע\"ל בידיע' והכרה גמורה שכולם ידעו אותו כבן גדול שיודע ומכיר לאביו כך עתה בנש\"י שהן בבחי' הקטנות כתינו' שקורא אבא מצד בחי' עצם התקשרותם במהו\"ע דוקא כנ\"ל אע\"פ שאינו משיג ומכיר במהותו ממש שהרי כל א' או' אבינו כו' אע\"פ שאינו יודע אותו בהכרת עצם מהותו כלל ולפי שלא יוכלו להשיגו במהותו ממש לזאת נתלבש במצה בקטנות המוחין והוא אמיתית כמו שהי' מכירו ממש כתינוק שקורא לאביו שזהו אמיתית הדבר כמו שהו' מצד שהוא אביו באמ' נמשך נפשו אחר אביו אע\"פ שאינו יודע טעם ודע' בזה כלל כך כל נשמ' אומר' אבינו מצד האמת כמו שהו' ממש וד\"ל וזהו ששת ימים תאכל מצות<sup data-n=\"1156\">20</sup> הגם שהוא גלוי מהו\"ע שבא בידיעה שלמעלה מן הדעת אלא כמו בראי' המהות אבל הוא בא בהלבשה כנ\"ל אבל ביום הז' עצרת לה' כו' שהוא בראיי' המהות שלא ע\"י הלבשה כלל כמ\"ש זה אלי זה ממש שלמעלה ממ\"ת אע\"פ שנא' אנכי ה' כו' אנכי זה בא בגלוי להם בראיי' עין השכל דנשמה רק שהיה פועל גם בגופם שהרי על כל דיבור<sup data-n=\"1157\">21</sup> פרחה נשמתן שהוא מעין העוה\"ב ממש כמ\"ש ז\"ל ישראל שעמדו בהר סיני פסקה זוהמתן<sup data-n=\"1158\">22</sup> שהיו מופשטי' מכל חומר רע דעה\"ד טו\"ר שבא מזוהמא של נחה\"ק כו' והיו חירו' ממ\"ה<sup data-n=\"1159\">23</sup> כו' וכ\"ז מצד ההכנ' לזה שהיה בקי\"ס שהיה גלוי מהו\"ע ממש כמו לע\"ל ממש ולזה העבירם בי\"ס כדי שיוכלו לקבל גלוי אור עצמות א\"ס בנשמות שבגופים ואם לא העבירם בי\"ס בגלוי גדול כזה לא היו יכולים לקבל אור דאנכי שבמ\"ת וזהו אנכי אשר הוצאתיך כו' וד\"ל. (אך לפ\"ז היה צ\"ל אנכי שקרע לך הים שזה היה עיקר הגלוי ממהו\"ע כו' ולמה אמ' אשר הוצאתיך מא\"מ וכתיב כימי צאתך מא\"מ<sup data-n=\"1160\">24</sup> אראנו נפלאות ולא הזכיר קי\"ס וכתיב למען תזכור<sup data-n=\"1161\">25</sup> יום צאתך כו' כל ימי חייך אפי' לעוה\"ב ולא הזכיר קי\"ס ועו' שאמר ועברתי בא\"מ<sup data-n=\"1162\">26</sup> כו' היינו במהו\"ע בכבודו ובעצמו וכמ\"ש במורא גדול<sup data-n=\"1163\">27</sup> זו גלוי שכינה אלא צ\"ל דמצד הגלוי מלמעלה היה זה דוקא כמו לע\"ל ממש עד דגם שיהיה גלוי אלקות לע\"ל תזכור כו' אבל מצד קבלת נש\"י בגופם היה במצרים בדרך הלבשה לבד כנ\"ל ובקי\"ס הי' בגלוי אור ממש מעין העוה\"ב וזה היה הכנה לקבלת התור' בנשמות שבגופים כנ\"ל וזהו שאמ' אנכי אשר הוצאתיך אנכי זה שהיה בגלוי בצאת' ממצרים דוקא שיצ\"מ מן נש\"ט לאור גדול היה זה בכח מהו\"ע ממש למעלה מבחי' גלוי אור העצמות בקי\"ס רק לע\"ל אראנו נפלאות וד\"ל):",[["1156","20","<b>ששת ימים תאכל מצות</b>: פ' ראה טז, ח."],["1157","21","<b>על כל דיבור</b>: נסמן לעיל ט, ב."],["1158","22","<b>ישראל. . פסקה זוהמתן</b>: ראה שבת קמו, רע\"א."],["1159","23","<b>חירו' ממ\"ה</b>: נסמן לעיל יט, ב."],["1160","24","<b>כימי צאתך מא\"מ</b>: מיכה ז, טו."],["1161","25","<b>למען תזכור</b>: נסמן לעיל ב, ב."],["1162","26","<b>ועברתי בא\"מ</b>: בא יב, ב."],["1163","27","<b>במורא גדול</b>: תבוא כו, ח [ושם: ובמורא] ובספרי שם. הגדה של פסח."]]],[2800530102,"(כט) <b>ולהבין</b> זה<sup data-n=\"1164\">1</sup> איך היה קי\"ס הכנה למ\"ת הנה יש להקדים מ\"ש במ\"א ע\"פ אז ישיר משה ובנ\"י<sup data-n=\"1165\">2</sup> אז משמע לשעבר מקדמת דנא<sup data-n=\"1166\">3</sup> וישיר משמעו להבא כו' ואיך יחדיו כאחד נאמר אז ישיר ומהו משה ובנ\"י כו' והנה כתיב מגיד מראשית אחרית<sup data-n=\"1167\">4</sup> ומקדם כו' ומבואר במ\"א בענין קשה לזווגן כקי\"ס<sup data-n=\"1168\">5</sup> דמה זה שתלה ענין הזיווג דוקא שקשה כקי\"ס ולמה היה הנס דקי\"ס קשה מכל הנסים ונפלאות שבמצרים כו'. אך הנה ידוע בענין לרוקע הארץ על המים<sup data-n=\"1169\">6</sup> דתחלה היו המים ע\"ג הארץ מקיפים וסובבים כדור הארץ ואח\"כ ציוה ה' יקוו המים<sup data-n=\"1170\">7</sup> כו' ותראה היבשה וירדו המים למטה והארץ נעשה בגובה על המים וז\"ש יורדי הים<sup data-n=\"1171\">8</sup> שמן הארץ לים שייך לשון ירידה וז\"ש לרוקע הארץ כו' והענין למעלה בהיות מבואר למעלה בענין שמים קדמו או ארץ קדמה<sup data-n=\"1172\">9</sup> כו' ויש להקדים לזה שיש ב' מיני השתלשלות יש מיש ויש מאין כידוע ויש מיש הוא כסד' ההשתלשלו' עו\"ע כמו מן המח' אל הדבו' דאותיות המחשבה הן בחי' יש ומתלבשים באותיות הדיבור שהן יש ומהות בפ\"ע וכן אותיות השכל במחשבה דאין התחדשות דבר מעיקרו כלל רק מה שהמציא בשכל נתגלה במח' ומן המח' בא בדיבור וזהו הנק' העלם וגלוי שהוא מיש ליש דמה שהיה בהעל' בא בגלוי ואין זה דבר מחודש מעיקרו כלל אע\"פ שהשינוי בא ממהות למהות דהיינו מה שהיה בשכל בא בהתלבשות מהות מח' ומה שהיה במח' בא במהות הדיבו' אבל הוא אותו הדבר עצמו ואין כל חדש בו כלל כי אין כאן חידוש מהות למהות שלא נשתנה מהות השכל להיות במהות מחשבה להיות המח' דבר מחודש כו' ולזה נק' יש מיש (רק שהמח' היה כלול' בשכל בהעלם ויצא לגלוי לבד וכן מה שידבר כלול תחלה במח' ויצא לגלוי לבד וכן המדו' היו כלולי' בשכל ויצאו לגלוי ונמצא שאין כאן בחי' חידוש בעצם מהות השכל או מח' כו') ולפ\"ז הרי לא נק' יש מיש ג\"כ אלא מיש לאין היינו שהשכל עיקר היש והמחשבה הכלולה בו כאין וכלא וכן הדיבור לגבי המחשבה היה בטל בתכלית תחלה רק שיצא לגלוי ועכ\"ז נק' יש מיש רק שהיה כלא וכאין בהיות העלול בעילה ואח\"כ יצא לגלוי יש בפ\"ע)<sup data-n=\"1173\">10</sup> ויהיה איך שיהיה יש להבין למה נק' ההשתלשלות בשם יש מאין הלא נהפוך הוא דלפ\"ז כל הגבוה גבוה יותר הכל הי' בהעלם בו ולא נחשבו שם למציאות בפ\"ע כלל וכמו הדיבור היה בתכלי' הביטול במח' ומח' בשכל ושכל בכח שלמעלה מן השכל עד קמי' ממש כלא חשיב הכל ונמצא למעלה הוא עיקר היש באמת דקמי' כלא חשיב הכל וכל שנשתלשל יותר למטה מהעלם לגלוי בשכל ומו\"ד כנ\"ל בבי\"ע עד עוה\"ז השפל יותר כלא חשיב כאות ה\"א דנברא בו העוה\"ז<sup data-n=\"1174\">11</sup> דכלא ממש חשיב לגבי אות א' שבמח' והמח' בטל לשכל כו' ולהיות כן איך יקרא מאין ליש נהפוך הוא שנק' מיש לאין כנ\"ל אך הענין הוא דב' מיני השתלשלות הם א' מיש לאין או יש מיש והב' מאין ליש שהוא התחדשו' דבר מעיקרו היינו מאין ממש שלא היה כלול תחלה באיזה מציאו' גם לא בבחי' העלם ועיבור<sup data-n=\"1175\">12</sup> כלל ואמנם בחי' מאין ליש אינו אלא בב' מקומות היינו בתחל' ובסוף ולא באמצע והענין הוא דבתחל' היינו מאור התחלת השפע מעצמו' המאציל כשעלה ברצונו להאציל<sup data-n=\"1176\">13</sup> (אע\"פ דקמי' כלא כו' שזהו מיש לאין היינו בחי' הרצון הזה שנק' אור הכתר",[["1164","1","<b>ולהבין זה</b>: להבא להלן פכ\"ט-מ\"א ראה הנרשם בריש המאמר (ח, ב)."],["1165","2","<b>אז ישיר משה ובנ\"י</b>: בשלח טו, א. ראה (הנחת כ\"ק אדה\"א ב)מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רפב. (והנחת הר\"מ בן כ\"ק אדה\"ז ב)סה\"מ תקס\"ה ח\"א ע' רלח."],["1166","3","<b>אז. . מקדמת דנא</b>: להלן פמ\"ג (ע, ב): כתרגומו — ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רפג. תו\"ח בראשית טו, ב. וש\"נ. לקמן עד, א. וש\"נ."],["1167","4","<b>מגיד מראשית אחרית</b>: ישעי' מו, י."],["1168","5","<b>קשה לזווגם כקי\"ס</b>: סוטה ב, א. ראה [הנחת הר\"מ ב]סה\"מ תקס\"ה ח\"א ע' רכב ואילך. ס\"ע רלד ואילך."],["1169","6","<b>לרוקע הארץ על המים</b>: תהלים קלו, ו."],["1170","7","<b>יקוו המים</b>: בראשית א, ט."],["1171","8","<b>יורדי הים</b>: תהלים קז, כג. ראה מאמרי אדה\"ז תקס\"ה כאן ע' רכב. מאמרי אדה\"א שמות ח\"א ע' קצז. וש\"נ. אוה\"ת קהלת (כרך ב) ע' א'קד."],["1172","9","<b>שמים. . ארץ קדמה</b>: לעיל לד, ב ואילך."],["1173","10","<b>בפ\"ע)</b>: גם בדפו\"ר לא נסמן התחלת החצע\"ג."],["1174","11","<b>כאות ה\"א. . בעוה\"ז</b>: מנחות כט, ב."],["1175","12","<b>שלא היה. . בבחי' העלם ועיבור</b>: ראה גם תו\"ח בשלח ע' קעט. ד\"ה לה\"ע קי\"ס מכ\"ק אדה\"א [קה\"ת תשמ\"ט] ע' 13."],["1176","13","<b>כשעלה ברצונו להאציל</b>: ראה לקמן ע' קטו."]]],[2800530103,"דאוכ' הו' לגבי עה\"ע<sup data-n=\"1177\">14</sup> ממש כו') אבל מאור הרצון בירידתו להיות בחי' חכמה נק' מאין ליש היינו שלא הי' מציאו' חכ' תחלה כלול גם בהעלם אלא מאין ממש נמצ' ליש וכמ\"ש והחכ' מאין תמצ'<sup data-n=\"1178\">15</sup> (והו' אין דכת' דכאין חשיב לגבי העצמו') וכמ\"ש דבראשי' נמי מאמ' הוא<sup data-n=\"1179\">16</sup> (כידוע דאור אבא יונק ממזל הח' ונוצר<sup data-n=\"1180\">17</sup> כו' וגם מה שיש בחי' חכמה סתימאה בהעלם הרצון ונק' טעם כמוס לרצון<sup data-n=\"1181\">18</sup> גם זה בא מאין ליש עד רום המעלות והוא מ\"ש והחכמה מאין גם חכמה דא\"ק<sup data-n=\"1182\">19</sup> כו') וזה חידוש יש מאין בראש ובתחל' שהוא בבחי' החכמה שמאין תמצא ליש בהתחדשות גמורה כנ\"ל וכמ\"כ בסוף הכל דוקא הוא בבחי' חידוש יש מאין והוא סוף המעשה כאשר בא מן הדיבור אל המעשה דהנה השכל ומחשבה ודיבור יש להם שייכות וערך זא\"ז עד שמתייחס השתלשלות אותיות השכל לבא במחשבה ומן המחשבה שחושב ידבר מיד אבל מה שידבר אינו מתייחס זה להביא לידי מעשה כלל דאע\"פ שאנו רואים שהמעשה מסתעפת מן הדיבור כדבר מלך שיצוה ויעשו כמו שיצוה בדיבור או כאשר יבנה אדם בנין או איזה מעשה ועסק יצוה בדבור לעשות כך וכך דוקא ויעשה כדבריו אבל הנה המעשה שעושה מה שדיבר אינו מהות וערך הדיבור כלל כי הרי היא פעולה ביד ורגל וכה\"ג שאינה מתייחסת כלל עם הדיבור (גם לעשי' שבדיבור שהוא מה שיצוה בדבור לעשות גם עקימת שפתיו<sup data-n=\"1183\">20</sup> כו') אלא הוא ענין ודבר מחודש לגמרי שלא היה במציא' כלל תחלה בדיבור רק חדש מעיקרו ולא שייך כלל אל הדיבור רק הדיבור הוא הגורם שיתחדש המעשה אבל גוף המעשה הוא ענין דבר מחודש שלא הי' כלל אפילו בהעלם בדברו בדיבור איך לעשות שאינו אלא בדיבור לבד ולא נק' בשם מעשה אז כלל רק כשבא לעשות בפועל דוקא משא\"כ הדיבור במח' עולה במח' מה שידבר ונק' דיבור שבמח' עד שאין כל חדש בדיבור רק שיצא מן ההעלם לגלוי בלבד כנ\"ל אבל מה שעושה אחר שידבר אינו נק' גילוי ההעלם רק פועל מחודש ממש כי הפועל את הפעולה ה\"ז מחדש הפעולה מכחו הנעלם שזהו כמו דבר שמתחדש מאין ממש כצורף שפועל הכלי למעשהו או בונה ואורג דגם שהעץ מוכן כבר והחוטים מוכנים מ\"מ פועל מעשהו בבנין מסודר ובאריגה גם זהו דבר מחודש ממש כו' (אע\"פ שבונה ואורג עפ\"י אופן הדיבור דוקא אין זה דומה כלל להמדבר עפ\"י אופן המחשבה שיש להם ערך ויחוס זע\"ז אבל סדר הפעולה נמשך אחר כח הנעלם המניע ועושה שזהו מאין ליש ממש וד\"ל) כמו בבריא' אדם כשנברא חומר גופו נק' מעשה כמ\"ש אף עשיתיו<sup data-n=\"1184\">21</sup> זהו חידוש יש מאין ע\"כ נק' בשם עשי' משא\"כ בנשמתו ורוחו שהיו בהעלם ויצאו לגלוי אין זה מאין ליש כ\"כ כמו ויפח באפיו נשמת חיים<sup data-n=\"1185\">22</sup> כו' ע\"כ נאמר ע\"ז בראתיו יצרתיו שהן נגד מו\"ד<sup data-n=\"1186\">23</sup> כידוע (אע\"פ שעכשיו הנשמות שיוצאים מלמעלה נק' בשם תולדה ממש כידוע בענין אור זרוע לצדיק<sup data-n=\"1187\">24</sup> עליון כדמיון מ\"ד המוליד שהוא כמו בזווג זו\"נ שנק' מאין ליש ממש אבל מה שחומר גופו מתהוו' בבטן ע\"ז נאמר אף עשיתיו זהו עיקר התולדה שהיא ג\"כ כמו חידוש יש מאין ממש שבארץ להוציא צמחה כמשי\"ת מפני שגופו שנעשה בפועל הוא דוקא חידוש גמור מאין ליש כנ\"ל וד\"ל) ונמצא מובן שבתחלה ובסוף בלבד",[["1177","14","<b>דאוכ' הו' לגבי עה\"ע</b>: ראה ת\"ז ת\"ע (קלה, ב). מאמרי אדה\"א דברים ח\"ד ע' א'תה. וש\"נ."],["1178","15","<b>והחכ' מאין תמצ'</b>: איוב כח, יב. ראה גם מאמרי אדה\"א בראשית ע' ד. וש\"נ."],["1179","16","<b>דבראשי' נמי מאמ' הוא</b>: ר\"ה לב, א."],["1180","17","<b>דאור אבא יונק ממזל הח' ונוצר</b>: נסמן לקמן קכז, א."],["1181","18","<b>חכמה סתימאה. . לרצון</b>: נסמן לעיל כו, ב."],["1182","19","<b>והחכמה מאין. . דא\"ק</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'ריג."],["1183","20","<b>עקימת שפתיו</b>: נסמן לקמן קמג, ב."],["1184","21","<b>אף עשיתיו</b>: ישעי' מג, ז."],["1185","22","<b>ויפח באפיו נשמת חיים</b>: בראשית ב, ז."],["1186","23","<b>בראתיו יצרתיו. . מו\"ד</b>: ראה סה\"מ תקס\"ג ח\"ב ע' תר. לקו\"ת בלק סז, א. מאמרי אדה\"א בראשית ע' תמא. וש\"נ."],["1187","24","<b>אור זרוע לצדיק</b>: תהלים צז, יא. ראה גם ביאוה\"ז בלק קה, א. מאמרי אדה\"א דברים ח\"ב ע' תקנג. שע\"ת ע, ב ובהנסמן לשם."]]],[2800530104,"נק' יש מאין היינו בחכמה שמאין תמצא ליש ובמעשה שבא' בבחי' יש מאין כנ\"ל אבל מחכמה ולמטה עד המעשה הכל הוא מיש ליש שנק' העלם וגלוי ולא חידוש בעיקר המציאות כנ\"ל וזהו נעוץ תחלתן בסופן<sup data-n=\"1188\">1</sup> וסופן בתחלתן דהתחלה הוא בבחי' אין דחכמה שהוא אין הכת' שהחכ' תמצא משם ליש ונעוץ כח זה בסוף דוקא שהוא המעשה שהיא עצמה יש בה כח המחדש מאין ליש שזהו למעלה מבחי' החכמה שבראש דגם שהחכמה נק' ראשית כמ\"ש בראשית ברא<sup data-n=\"1189\">2</sup> כו' כידוע הרי בראשית נמי מאמר הוא והוא יש מאין כמ\"ש והחכמה מאין כו' אבל המעשה הוא מחדש מאין ליש כמו כח הכתר שמאין דכתר נמשך החכמה תמצא ליש כנ\"ל וד\"ל (והיינו מ\"ש כתר מל' דאיהו כ\"ע<sup data-n=\"1190\">3</sup> ובציור הקוין הרי המל' עומדת תחת הקו האמצעי דת\"י<sup data-n=\"1191\">4</sup> שעולה לפנימית הכתר<sup data-n=\"1192\">5</sup> שאין ב' הקוין עולין לשם משום דנעוץ תחלתן בסופן היינו אור הכתר במל' וכמ\"כ נעוץ סופן כו') ונמצא מובן עכ\"פ שיש כח גדול בסוף מה שאין בראש דחכמה שנקרא ראשית כי הגם שהחכמה נק' ראשית הגלוי מן ההעלם דעצמו' כידוע הרי היא עצמה נתהווה ונתחדשה מאין ליש כמ\"ש החכמה מאין תמצא כנ\"ל אבל אין בה כח המחדש מאין ליש כלל אדרבה מה שנמשך שפע ואור מן החכמה לבינה הגם שהבינה נק' יש והחכמה אין<sup data-n=\"1193\">6</sup> כידוע מ\"מ אין זה חידוש מאין ליש ממש אלא רק מן ההעלם לגלוי בלבד כידוע לפי שבחי' החכמה נק' נקודה ומתפשטת אח\"כ לאורך ורוחב בהשגה דבינה וא\"כ אין כל חדש בזה כלל כמו מעין הנובע ונמשך נהר שאין כל חדש במי הנהר כי מן המעיין הוא נמשך רק שהיה במעיין בהעלם ובא לידי גלוי בנהר כך בחכמה בבחי' נקודה היה בהעלם עדיין ובבינה יצא לידי גלוי ליש ואין זה חידוש יש מאין כלל (וכן בטיפה המוליד שנתהווה אח\"כ הולד אין כל חדש ממש רק שיצאו האברים בהתפשטות יש מן ההעלם שלהם שבטיפה דדכורא והגם שמבואר למעלה דגוף הולד דוקא נק' חידוש יש מאין יותר מיצירת נשמתו ורוחו הרי גם בגוף גשם החומר היה בטיפ' הכל בהעלם כל אבריו ואח\"כ יצא לגלוי לבד כו') ויובן כ\"ז בדרך כלל בע\"ס דאצי' דחו\"ב ומדות דאצי' הכל הוא נמשך ובא בסדר השתלשלות עילה ועלול מחכמה לבינה מהעלם לגלוי מיש ליש כנ\"ל וכן מבינה דאצי' למדות הרי המדות היו תחלה במציאות בהעלם בתוך ההשגה כמו שאנו רואים שהתפעלות המדות שבלב היו כלולים בהשגה שבמוח ויצאו לגלוי בלב בלבד כנ\"ל במח' ושכל כו' אך במל' דאצי' שנק' סוף הכל הוא בחי' המעשה יש בה כח התחלה דעצמות א\"ס שבאור הכתר דאצי' לחדש יש מאין ממש מה שיש בקדמון לכל הקדומים<sup data-n=\"1194\">7</sup> שמחדש את החכמה מאין ליש כנ\"ל לפי שנעוץ תחלתן בסופן וסופן כו' כי סוף מעשה עבמ\"ת<sup data-n=\"1195\">8</sup> במהו\"ע שלפני ההשתלשלות דע\"ס כידוע אמנם זהו כדבר פלא מפני מה בסוף הכל ימצא בחינה ומדרגה שלמעלה מהכל (גם למעלה מן תחלה וסוף מאחר שעולה בעצמות שאין לו תחלה וסוף כו') וכמשל המעשה שאע\"פ שהיא ע\"פ הרצון שנק' תחלה מ\"מ הרי אנו רואים גם בהחלט הרצון כך וכך כשבא למעשה",[["1188","1","<b>נעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א מ\"ז."],["1189","2","<b>בראשית ברא</b>: נסמן לעיל יג, א. לקמן ס\"פ ל."],["1190","3","<b>כתר מל' דאיהו כ\"ע</b>: נסמן לעיל כד, ב."],["1191","4","<b>המל' עומדת. . דת\"י</b>: נסמן לעיל שם."],["1192","5","<b>הקו האמצעי. . הכתר</b>: נסמן לקמן קכה, א."],["1193","6","<b>שהבינה נק' יש והחכמה אין</b>: ראה לקמן קכז, סע\"א ובהנסמן במ\"מ לשם."],["1194","7","<b>בקדמון לכל הקדומים</b>: ת\"ז תי\"ט (מב, א). ראה הנסמן במאמרי אדה\"א דברים ח\"ב ע' תנט."],["1195","8","<b>סוף מעשה עבמ\"ת</b>: ע\"פ פיוט לכה דודי."]]],[2800530105,"לפעול הדבר בפו\"מ יתיישב מחדש היינו שמתיישב אם יהיה הרצון כך כי בבוא הדבר למעשה דוקא בפו\"מ יוכל להתחרט מן הרצון הקדום שהיה לו וכמו וינחם ה' על הרעה אשר<sup data-n=\"1196\">9</sup> כו' דגם שודאי היה הרצון למעלה מן הטעם שנקרא חכמה סתימאה טעם כמוס לרצון בהגיע למעשה נתחרט ועשה להיפוך כמו יהי רצון מלפניך<sup data-n=\"1197\">10</sup> שיכבשו רחמיך כו' מלפניך דוקא כידוע וזהו הוראה על היות שרש המעשה במהו\"ע ממש שלפני הרצון ג\"כ ומכ\"ש למעלה מן החכמה והטעם אף על פי שהחכמה והטעם הוא בחינת ראש ופנימית למעשה שהרי בלתי שכל וטעם לא יעשה דבר וחצי דבר כלל וישנה במעשיו מהיפוך להיפוך מ\"מ עצם המעשה למעלה מן השכל וטעם וגם למעלה מן הרצון וראיה לזה מן הבנין (והתולדה ג\"כ) שבסוף מעשה דוקא נשלם הפנימיות והעצמות שהיה בזה עד שכל רצונו וחכמתו כו' הכל הי' טפל לזה וע\"כ מובן ממילא מ\"ש כולם בחכמה עשית<sup data-n=\"1198\">11</sup> דגם שהחכמה ראשית והעשיה סוף אבל שרש העשיה למעלה מן החכמה וגם למעלה מן התענוג והרצון (ולזה גם בתולדה בסוף מעשה בהולדה גשמי' מן הטפה שם דוקא מכח העצמות דאב ולא בהמשכת מ\"ד ומ\"ן בלא התהוות ולד בפו\"מ שכל התענוג הרוחני וגשמי שבזה הזווג אינו כלום) ועדיין אין הקושיא הנ\"ל מתורץ דאיך נק' מאין ליש גם בתחלה ובסוף הלא קמיה כלא ה\"ז מיש לאין כנ\"ל ועוד דהשתלשלות שמחכמה עד דיבור מזה בא כל התהוות העולמות והברואים כידוע וכמו י' מא'<sup data-n=\"1199\">12</sup> יהי אור יהי רקיע<sup data-n=\"1200\">13</sup> שהוא בבחינת דיבור כמ\"ש בדבר ה' שמים<sup data-n=\"1201\">14</sup> כו' שזהו יש מיש דוקא ולא יש מאין כנ\"ל ואיך אנו אומרים שהבריאה יש מאין ואם מצד התחלה והסוף שהוא העיקר שהוא יש מאין כנ\"ל הרי העיקר ומקור הבריאה הוא בדבור די' מא' שאחר שאמר יהי רקיע ויהי אור אז נתהווה כן כמ\"ש ויאמר אלקים יהי אור ויהי אור<sup data-n=\"1202\">15</sup> כו' וד\"ל:\n(ל) <b>אך</b> הנה באמת גם מה שנק' יש מאין גם בבחי' התחלה והסוף בבחי' כתר ומל' כנ\"ל היינו רק כלפי מטה לגבי דידן שאנחנו בבחי' ההשתלשלות יש מיש מחכמה ולמטה עד בחי' הדבור שבדבר ה' כו' כנ\"ל ע\"כ נק' התחלה וסוף בבחי' יש מאין כנ\"ל. אבל לגבי עצמותו ית' נהפוך הוא דקמיה כולא כלא כו' ונק' הוא בחי' יש אמיתי וההשתלשלות בחי' אין דכלא באמת חשיב ומה שנק' יש מאין בין בחכמה שבראש כנ\"ל ובין במל' שבסוף הוא<sup data-n=\"1203\">16</sup> רק שם המושאל היינו מה שמחדש החכמה מאין שאינו מושג בנאצלים וכמ\"ש והחכמה מאין כו' דכל דבר שאינו בגדר המושג לעין נקרא אין בהעלם ולא שהוא ענין אין אמיתי כו' שבאמת נהפוך הוא דקמי' כלא שזהו מיש לאין דהיינו בחי' אין דחכמה כלא ממש חשיב וכמ\"ש במ\"א בענין אל דעות הוי\"ה<sup data-n=\"1204\">17</sup> שדיעה עליונה היינו כמו שהוא קמיה מיש לאין היפך דיעה שלמטה שהוא מאין ליש כו' (ועדיין אין זה מתיישב לנכון דא\"כ שגם התחלה וסוף כמו שהוא קמיה ממש הן ג\"כ מיש לאין ומה שנקראים מאין ליש זהו רק שם המושאל לגבי דידן כנ\"ל א\"כ מהו יתרון מעלת התחלה",[["1196","9","<b>וינחם ה'. . אשר</b>: תשא לב, יד."],["1197","10","<b>יהי רצון מלפניך</b>: נסמן לעיל כא, ב."],["1198","11","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["1199","12","<b>י' מא'</b>: אבות רפ\"ה (בראשית א, א ואילך)."],["1200","13","<b>יהי אור יהי רקיע</b>: בראשית א, ג. ו."],["1201","14","<b>בדבר ה' שמים</b>: תהלים לג, ו."],["1202","15","<b>ויאמר. . ויהי אור</b>: בראשית א, ג."],["1203","16","<b>הוא</b>: ניתוסף ע\"פ דפו\"ר."],["1204","17","<b>אל דעות הוי\"ה</b>: נסמן לעיל ב, א."]]],[2800530106,"וסוף בזה יותר מבאמצע שהוא יש מיש כי זהו עיקר הרבותא מה שתחלה וסוף יש בהן מבחי' כח העצמות והוא שמחדש מאין המוחלט בלי שיעור שזהו כח של בחי' א\"ס ממש שאין זה רק בתחלה ובסוף דוקא כמשי\"ת בסמוך אלא צ\"ל דגם כמו שהוא קמי' כלא שזהו מיש לאין כנ\"ל מ\"מ בחי' התחלה והסוף יש בהן בחי' כח החידוש מאין ליש דוקא כי א\"ס עצמו כולל ב' דעות<sup data-n=\"1205\">1</sup> הללו כא' מיש לאין ומאין ליש כמ\"ש במ\"א וד\"ל) והנה עדיין אינו מובן איך הבריאה בחי' יש מאין אחר שהעיקר הוא דיבור העליון די' מא' כמו ויאמר אלקים יהי אור כנ\"ל והדבור הוא בא בסדר השתלשלות מראשית דחכ' בבחי' יש מיש כנ\"ל אך בהכרח צ\"ל שעיקר התהוות הבריאה בגשם חומרה הוא מבחי' המעשה בפ\"מ שנבדלת מן הדיבור הרוחני כנ\"ל באריכות שאין המעשה מתייחסת כלל עם הדיבור ע\"כ במעשה יש בחי' התחדשות גמור מאין ליש דוקא כנ\"ל ואעפ\"כ הדיבור הוא העיקר כמו בדבר ה' כו' והענין הוא כמ\"ש במ\"א שיש ב' דברים בכל בריאה<sup data-n=\"1206\">2</sup> צורה וחומר<sup data-n=\"1207\">3</sup> ויש שרש לצור' בפ\"ע שהוא בחי' הרוחניות של כל בריאה ושרש הראשון הוא החכמה כמ\"ש כולם בחכמה עשית ואמנם שרש הגשם והחומר של הבריאה הוא למעלה מן החכמה והיינו למעלה הרבה ממקור הרוחניות וזהו כמו דכל השתלשלות עו\"ע הכל ברוחניות עד הדיבור הוא בא מבחי' החכמה אבל סוף מעשה שבפו\"מ היינו בחי' התהוות עצם החומר של הבריאה שרשו מלמעלה מן ההשתלשלות דעו\"ע שמן החכמה והוא בבחי' עצמות א\"ס שבכתר מקור החכמה וע\"ד דוגמא הנה הגלגלים וכל צבא השמים נתהוו בדיבור ברוח פיו כו' שהוא בחי' הרוחניות שלהם דוקא ונק' נפש הגלגל וצורתו אבל חומר ויש שלו יש לו שרש מלמעלה מהדיבור עד מקור הראשון שהמציא גם החכמה מאין ליש וזהו ענין בחי' המעשה בפו\"מ כאשר עשה לגולם וחומר הבריאה הוא בא בחידוש גמור מאין ליש כנ\"ל וכמו כשאמר בדיבור יהי רקיע או יהי אור נתהוו רק הרוחניות שלהם אבל כשנעשה גוף הרקיע הגשמי וגוף האור הגשמי זהו חידוש גמור שבפ\"מ והוא מ\"ש ויהי אור כמו כי הוא אמר ויהי<sup data-n=\"1208\">4</sup> הנה זה בא מלמעלה גם ממקור הראשון של המא' הזה והיינו מבחי' קדמון לכל הקדומים שאין לו תחלה כו' דהיינו מה שנעוץ תחלתן בסופן דוקא כנ\"ל ומ\"ש כולם בחכמה עשית לא שמן החכמה נעשה גוף הפועל בחומר הבריאה אלא רק הרוחניות שבו אבל הגשמיות שבו נעשה מאותו מקור שמשם נמצאת החכמה מאין וכנ\"ל דנעוץ סופן בתחלתן דהמעשה בפועל גבוה מן החכמה מאחר שהחכמה עצמה נתהווה מאין ליש ובמעשה בפועל הגשם יש כח המחדש מאין ליש כמו בכח התחל' ממש כנ\"ל באורך וד\"ל וע\"פ הקדמה זו יובן ג\"כ בענין הי' מאמ' דגם שהדבור הוא עיקר היינו שמצוה להיות התהוות הבריאה אבל גוף התהוות הבריאה היא בחידוש גמור מאין ליש בפו\"מ גבוה ממנו בשרשו (וז\"ש כי הוא צוה ונבראו<sup data-n=\"1209\">5</sup> ומבואר במ\"א בפי' ונבראו ממילא נבראו מכח העליון שלמעלה מצווי הדיבור כו'). ובזה יתורץ ענין הנ\"ל דהבריאה בפועל ליש גמור דוקא",[["1205","1","<b>א\"ס. . ב' דעות</b>: ראה בהנסמן לעיל שם."],["1206","2","<b>בכל בריאה צורה וחומר</b>: ראה שערי אורה ע' עח. מאמרי אדה\"א דברים ח\"ד ע' א'רפד ואילך. נ\"ך ע' קמז."],["1207","3","<b>צורה וחומר</b>: ראה הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'קעו."],["1208","4","<b>כי הוא אמר ויהי</b>: תהלים לג, ט."],["1209","5","<b>כי הוא צוה ונבראו</b>: תהלים קמח, ה. ראה גם שערי אורה ע' פט."]]],[2800530107,"ודאי הוא בא בחידוש מאין ליש דוקא ועכ\"ז הדיבור הוא המקור לבריאה כמ\"ש בדבר ה' שמים נעשו וברוח פיו כו' ושניהם אמת אבל הדיבור הוא בא בסדר השתלשלות יש מיש עד החכמה שנק' ראשית שבאה מאין ליש כנ\"ל והוא מקור כל שפע רוחניות דכל הברואים מעיל' לעלול וד\"ל ומעתה הנה יובן בענין המא' שבמע\"ב הי' בהן ב' מדריגו' א' כמו מא' יהי אור ומא' יהי רקיע דאע\"פ שכלול האור ורקיע מחומר וצורה אין זה חידוש גמור להיות חומר האור והרקיע אחר שבדיבור כבר נתהווה הרוחניות שלהם כנ\"ל<sup data-n=\"1210\">6</sup> רק בא מן ההעלם לגלוי כשאמר יהי אור ויהי אור שיצא לגלוי ועכ\"ז כשיצא לפועל ממש חומר האור והרקיע הרי זהו בא משרש היותר עליון מן הדיבור מאחר שנק' בשם מעשה בפועל כמ\"ש ויעש ה' את הרקיע<sup data-n=\"1211\">7</sup> או כמ\"ש ידי יסדה<sup data-n=\"1212\">8</sup> כו' וימיני כו' והמדריגה הב' במע\"ב יותר עליון מזה והוא מ\"ש תדשא הארץ דשא<sup data-n=\"1213\">9</sup> תוציא הארץ נפש חיה<sup data-n=\"1214\">10</sup> מיד הוציאה הארץ כל אשר גזר או' ברואים גשמיים שזה מכח הארץ עצמה באה כמ\"ש הכל הי' מן העפר<sup data-n=\"1215\">11</sup> כו' שמזה מובן שיש בארץ עצמה כח המחדש מאין ליש ממש שהוא למעלה מן הדיבור דיהי אור ויהי רקיע כו' והיינו טעם המ\"ד דארץ קדמה לשמים כידוע ומ\"מ בלא גזרת מא' שאמר תוציא הארץ לא היה יוצא מן הארץ ומא' תוציא הארץ הוא הכח האלקי שנתלבש בארץ להוציא כל נפש חיה וכל דשא עץ פרי ע\"י מאמר תדשא הארץ ועד היום הוא מחדש בטובו מע\"ב יש מאין דוקא הכל עד\"ז דוקא וד\"ל ובאמת יש להבין זה מאין יבא כח גדול בארץ שהוא יסוד העפר חומרי שיהי ביכולתו להוציא בריאה חדשה לגמרי מאין ליש וכמאמר בצביונן ובקומתן נבראו<sup data-n=\"1216\">12</sup> שזהו חומר וצורה כא' (משא\"כ באור ורקיע כו') והנה לכאורה יפלא על מ\"ד ארץ קדמה לשמים דאם כונתו רק בסדר הבריאה הרי ודאי שמים קדמו לארץ כמבואר ומפורש בכתובים דמעשה בראשית שמאמר יהי רקיע קדם למאמר תדשא הארץ ותוציא הארץ כו' ואם הכונה על גוף כדור הארץ שקדם לשמים כמ\"ש והארץ היתה תוהו<sup data-n=\"1217\">13</sup> שזה קדם ליהי רקיע הרי אז היתה הארץ מובלעת בתוך מים עליונים שעליה כמ\"ש ורוח אלקים מרחפת<sup data-n=\"1218\">14</sup> ע\"פ המים כידוע ומים ואש נתחברו יחד ונעשה בריא' השמים אש ומים<sup data-n=\"1219\">15</sup> יחד שזהו מאמר יהי רקיע כו' ובפירוש אמר בראשית ברא השמים ואח\"כ את הארץ דהיינו ודאי שהשמים וכל צבאם קדמו לארץ וכל אשר בה כידוע ומה שהביא ראיה ממ\"ש ביום עשות ה' אלקים ארץ ושמים<sup data-n=\"1220\">16</sup> זהו בגמר סוף כל המעשה כמובן בכתובים ומה זו ראיה שקדמה הארץ בסדר הבריאה אלא צ\"ל שכונתו שקדמה ארץ במחשבה תחלה משום דסוף מעשה עבמ\"ת כידוע ומבואר למעלה ואמנם יש להבין היא גופא למה קדמה ארץ תחלה למח' דבריאת שמים שנבראו בחכמה שנק' ראשית כמ\"ש בראשית ברא בחוכמתא<sup data-n=\"1221\">17</sup> כו':\n(לא) <b>אך</b> הנה באמת אנו רואים דבר פלא בארץ אשר אין זה בשמים אע\"פ שקדמו לארץ בסדר הבריאה כנ\"ל דהנה בעפר ארץ החומרי ימצא כח ההתחדשות בריא' יש מאין ממש שאין זה בשמים כלל",[["1210","6","<b>כנ\"ל</b>: ניתוסף ע\"פ דפו\"ר."],["1211","7","<b>ויעש ה' את הרקיע</b>: בראשית א, ז. ראה גם מאמרי אדה\"א במדבר ח\"ג ע' א'רנה."],["1212","8","<b>ידי יסדה</b>: ישעי' מח, יג."],["1213","9","<b>תדשא הארץ דשא</b>: בראשית א, יח."],["1214","10","<b>תוציא הארץ נפש חיה</b>: בראשית א, כד."],["1215","11","<b>הכל הי' מן העפר</b>: קהלת ג, כ."],["1216","12","<b>בצביונן ובקומתן נבראו</b>: ראה חולין ס, א."],["1217","13","<b>והארץ היתה תהו</b>: בראשית א, ב."],["1218","14","<b>ורוח אלקים מרחפת</b>: המשך הכתוב והארץ היתה."],["1219","15","<b>השמים אש ומים</b>: חגיגה יב, סע\"א."],["1220","16","<b>ביום עשות. . ושמים</b>: בראשית ב, ד."],["1221","17","<b>בראשית. . בחוכמתא</b>: ראה תרגום ירושלמי לבראשית א, א."]]],[2800530108,"שהרי אנו רואים בראיה חושיית שהשמים וכל צבאם בכו\"מ<sup data-n=\"1222\">1</sup> המה עומדים מוי\"ב בלי תוס' ומגרעת כלל וכלל ובלי שינוי כלל כי מעולם לא נתחדש כוכב אחד או מזל ברקיע השמים נוסף על המספר הקצוב לפי סדר בריאותם בתחלה מה שלא היה בתחלת הבריאה שאמר יהי מארת ברקיע<sup data-n=\"1223\">2</sup> וכן הרקיע עצמו אין בו כל חדש בעצם שלא ניתוסף באור עצם מהותו דבר רק אותה הבריא' שהיה בו ובכו\"מ בסדר מצבן ומהלכן כך המה עתה בלי תוס' ומגרעת ובלי שינוי כלל וכמ\"כ בגידול הרכבת ד\"י הרוחניים ארמ\"ע כמו שהן בראשית הבריאה לא נתחדש בהן דבר להיות מולידים דבר חדש רק כמו שהן לבד שהרי ביסוד האש לא נתחדש ממנו דבר חדש כלל וכן ביסוד המים ויסוד הרוח ויסוד העפר כולם במהותם וגם בהרכבתם בלתי שינוי וחידוש כלל וכלל (וכמו במלאכים עליונים שהמה עומדים מוי\"ב<sup data-n=\"1224\">3</sup> לא יתוספו ולא יגרעו ולא ישנו תפקידם כל אחד כפי שרשו אם בבחי' אש או רוח כו' שלא ימצא הוספת תולדה חדשה<sup data-n=\"1225\">4</sup> כלל מהם כי מוציא במספר צבאם<sup data-n=\"1226\">5</sup> והיינו במספר אותיות וצירופים וכל מלאך יש לו אות וצירוף מיוחד וא\"א שיהיה מאות אחת ג' וד' אותיות חדשים ע\"כ כל אחד במעמדו לא יוסיף ולא יגרע לעולם עד שאין מלאך אחד עושה ב' שליחות<sup data-n=\"1227\">6</sup> כמ\"ש במ\"א) אך הארץ יש בה כח החידוש שמחדש דבר מעיקרו שלא היה במציא' תחילה כלל שהרי אנו רואים שהארץ תגדל ותוציא צמחה דשא וכל עץ פרי עושה פרי וכל תבואת הארץ יצמיחו בתוספת מרובה על עיקר הזריעה לאין שיעור וקץ כלל מה שלא הי' תחלה במציאות כלל וגם אחר שיכלה הצמיחות דתבואות ופירות ועשב הארץ בקצירה וכליון אחר חוזר ותצמיח מחדש הכל בתוס' מרובה כמו מדי שנה ושנה שצומח הכל מחדש ואין שיעור והפסק לזה כלל לעולם ולא עוד אלא שגם בחי' ד\"י הרוחניי' ארמ\"ע ודצח\"מ שמקבלים מהכו\"מ שברקיע כאשר יבואו בארץ יבא בהן כח ההתחדשו' גמור' מאין ליש בתוס' מרובה לאין שיעו' כלל כמו יסוד המים שאין בהם התחדשו' בעצם כלל טרם בואם בעפ' האר' כמי' עליונים שע\"ג הארץ ובארץ עצמה הרי מתחדשי' שם למים שנק' מים חיים דוקא כידוע הן בלתי שיעור כלל כי מתחדשים בעיקר המציאות בסיבת כח הארץ עצמה דוקא וכמ\"ש במ\"א בענין מים חיים דאפר פרה<sup data-n=\"1228\">7</sup> כו' באריכו' וכן יסוד הרוח ויסוד האש וכל צומח ודומם שבארץ מצד כח הארץ דוקא יבא בהן התחדשות להצמיח ולהוליד לאין שיעור וראי' מעץ עושה פרי לאין שיעור שהוא מצד שרשיו שבארץ דוקא וע\"כ בירך על פירות האילן<sup data-n=\"1229\">8</sup> בפה\"א יצא דמארעא קא רבי כו' וכמ\"ש<sup data-n=\"1230\">9</sup> במ\"א<sup data-n=\"1231\">10</sup> וכמ\"ש הכל היה מן העפר דכל התחדשות דבר מעיקרו הוא מן העפר דוקא משא\"כ בשמים שלא יבא בה שום התחדשות כלל (אע\"פ שאין לך עשב<sup data-n=\"1232\">11</sup> שאין לו מזל המכה ומגדלו היינו רק בחי' הרוחניות שלו לבד אבל עיקר מהות ומציאת גשם העשב מתחד' מן כח הצומח שבאר' דוקא כמ\"ש כי כארץ תוצי' צמחה<sup data-n=\"1233\">12</sup> תוצי' מכח עצמה רק המזל הוא מגדל חיות רוחניות' וכמ\"כ ממגד תבואת שמש<sup data-n=\"1234\">13</sup> כו' וכמ\"ש אני אענה את השמים והם יענו את הארץ<sup data-n=\"1235\">14</sup> וד\"ל) וזהו שהיה במע\"ב שצוה ה' לארץ להוציא הכל כמ\"ש תדשא הארץ דשא תוצא",[["1222","1","<b>בכו\"מ</b>: בכוכבים ומזלות."],["1223","2","<b>יהי מארת ברקיע</b>: בראשית א, יד."],["1224","3","<b>במלאכים. . מוי\"ב</b>: ראה איכ\"ר פ\"ג, ח. טואו\"ח סנ\"ט. מאמרי אדה\"א בראשית ע' קכו. ויקרא ח\"ב ע' תרמג ואילך [נדפס גם ב]הנחות תקע\"ז ע' לג ובהנסמן בהנ\"ל."],["1225","4","<b>במלאכים. . תולדה חדשה</b>: ראה ביאוה\"ז נח ה, סע\"ד ואילך [נדפס גם בסה\"מ תקס\"ח ח\"א ע' תעה]. לקו\"ת שה\"ש לח, ד. מ, א. מאמרי אדה\"ז תקס\"ה ח\"א ע' מד. תקס\"ח ח\"ב ע' תרטז ואילך. מאמרי אדה\"א דרושי חתונה ח\"ב ע' תעא ואילך."],["1226","5","<b>מוציא במספר צבאם</b>: ישעי' מ, כו."],["1227","6","<b>שאין מלאך. . ב' שליחות</b>: נסמן לקמן קלא, ב."],["1228","7","<b>מים חיים דאפר פרה</b>: ראה גם מאמרי אדה\"א נ\"ך ע' קמו. ויקרא ח\"ב ע' תקלח. ס\"ע תרב ואילך. במדבר ח\"ד ע' א'שצב ואילך. אמ\"ב שער הק\"ש ל, ג ואילך."],["1229","8","<b>בירך על פירות האילן</b>: ראה ברכות מ, א."],["1230","9","<b>וכמ\"ש במ\"א</b>: תיבות אלו ניתוספו ע\"פ דפו\"ר."],["1231","10","<b>וכמ\"ש במ\"א</b>: ראה סה\"מ תקס\"ח ח\"ב ע' תריז ואילך. אמ\"ב שם. מאמרי אדה\"א דברים ח\"ג ע' תתקו. וש\"נ."],["1232","11","<b>שאין לך עשב</b>: נסמן לקמן קמו, א."],["1233","12","<b>כי כארץ תוצי' צמחה</b>: ישעי' סא, יא."],["1234","13","<b>ממגד תבואת שמש</b>: ברכה לג, יד."],["1235","14","<b>אני אענה. . הארץ</b>: נסמן לעיל לד, ב."]]],[2800530109,"הארץ כו' וכמ\"ש בזהר דארץ אפיקת<sup data-n=\"1236\">15</sup> ועביד' תולדו' חדשים כו' שהוא חידוש הבריאה ממש מאין ליש שאין זה ברקיע כלל וד\"ל:\n<b>והנה</b> הטעם לזה ידוע משום דנעוץ תחלתן בסופן וסופן בתחלתן דלפי שהארץ היא היות' תחתון וסוף הכל דוקא ע\"כ יש בה מכח התחלה שהוא כח של בחי' א\"ס שבפנימי' הכתר כנ\"ל והו' בחי' מל' דא\"ס עצמו שסוף מעשה עבמ\"ת כנ\"ל שזהו טעם דמ\"ד ארץ קדמה לשמי' שקדמה במחש' תחלה כו' ולכך יש לארץ דוקא כח זה המחדש מאין ליש ממש בלי שיעור וקץ כלל כנ\"ל שזהו אותו הכח החידוש יש מאין דא\"ס עצמו שבמל' דא\"ס שבכתר שהחכמה משם תמצא ג\"כ מאין ליש כנ\"ל דנעוץ סופן בתחלתן כו' אבל שמים וכל צבאם הרי נתהוו מן החכמה דמא' בראשית בבחי' סדר השתלשלות עו\"ע שהוא בבחי' הרוחניות כנ\"ל בחכמה ודיבור די' מא' כו' ע\"כ אין בהם כח החידוש הזה מאין ליש כלל אלא כמו שהן מוי\"ב בלי תוס' וגירעון כלל ובלי שינוי כלל כנ\"ל וד\"ל. (וזהו ענין מדריגה הב' במע\"ב במא' תדשא הארץ תוצא הארץ כו' שהוא הרבה יותר עליון מן הדיבור דיהי אור יהי רקיע ועפ\"י הקדמה הנ\"ל דשרש התהוות החומר שהוא חידוש גמור הוא יותר עליון כו' וע\"כ מן הארץ יצאו בצביונן חומר וצורה כא' מפני שבארץ דוקא יש שרש התהוות החומר הפשוט מאין המוחלט שאין זה במקור התהוות הרוחניות והצורה של כל הברואי' שנבראו רוחניות צורתם מן החכמה כנ\"ל וד\"ל). ובכ\"ז יובן טעם המחלוק' שטעם מ\"ד שמים קדמו לארץ היינו בשכלול שהוא בסדר השתלשלות הרוחניות דעו\"ע כנ\"ל כמו השכל שקדם למחשב' ומחש' קדם לדיבור והארץ היא בפו\"מ שהוא אחרון מכל אבל מצד שרש כח הארץ בתחלתן שסוף מעשה עבמ\"ת הרי הארץ קדמה במחש' שבעצמות ממש ולכן יש לארץ כח החידוש מאין ליש יותר מעליונים עליה שעולי' ומקבלים עד בחי' ע\"ס דאצי' כו' וד\"ל (וכך הוא ענין התולדה שהיא ג\"כ כח החידוש מאין ליש ממש כנ\"ל מפני שיש בה מכח התחלה שהוא עצמות הנפש ממש כידוע שכח המוליד שבטיפה הוא נטוע בעצם הנפש ממש שלמעלה מרצון ושכל כו'). ומעתה יובן ענין הנ\"ל בפי' לרוקע הארץ על המים שתחלה קודם הבריאה היו המים מקיפים וסובבים לכדור הארץ ואח\"כ צוה ה' שיקוו המים כו' ותראה היבשה וירדו המים למטה ונעשה הארץ למעלה כנ\"ל דהנה ידוע מ\"ש במדרש שקודם שנברא העולם היה מים במים<sup data-n=\"1237\">16</sup> כו' שמ\"ע ומ\"ת היו ביחד ושניהם ע\"ג הארץ וצוה שיקוו המים תחתונים שמתחת השמים אל מקום א' ותראה היבשה הרי מ\"ת דוקא הוא שהיו מקיפים וסובבים לארץ וגער בהן בנזיפה<sup data-n=\"1238\">17</sup> שירדו למטה מן הארץ ותעמוד האר' ממילא למעלה כמ\"ש לרוקע הארץ ומ\"ע שמעל השמים עלו למעלה על ידי הבדל הרקיע כמ\"ש יהי רקיע בתוך המים כו' והענין הוא כידו' בפי' שמים אש ומים שזהו ענין אור מים רקיע ר\"ת אמ\"ר<sup data-n=\"1239\">18</sup> דאור הוא בחי' ח\"ע הרוחניות והוא אש ולא אש גשמי אלא מקור יסוד האש שנקרא אויר דק<sup data-n=\"1240\">19</sup> ומן האויר נעשה אור וכמשל אור מקור השכל שנעשה ונמשך בהתפשטות נק' התחכמו' שבא מכח המשכיל ההיולי ואח\"כ מתפשט לאורך ורוחב נק' מים שהחכ' נק' אור ונק' מים<sup data-n=\"1241\">20</sup> כידו' וז\"ש אל תאמרו מים מים<sup data-n=\"1242\">21</sup> כו' כמ\"ש במ\"א ואש ומי' יחד כמ\"ש",[["1236","15","<b>דארץ אפיקת</b>: ראה זהר בהקדמה יב, א. בראשית מו, ב."],["1237","16","<b>שקודם. . מים במים</b>: ראה ב\"ר פ\"ה, ב. שמו\"ר פט\"ו, ז. רפ\"נ. לקו\"ת שלח מב, ב. וש\"נ."],["1238","17","<b>וגער בהן בנזיפה</b>: להלן (סז, א): במדרש. ראה פדר\"א פ\"ה. חגיגה יב, א. רש\"י בראשית א, ו. תו\"ח תולדות קמג, ב ובהערה 30."],["1239","18","<b>אור מים. . אמ\"ר</b>: ראה זהר תרומה קלו, ב. קסז, א. ע\"ח (שער המלכים) שי\"א פ\"ו. סידור שחרית ע, א. הנסמן במאמרי אדה\"א שמות ח\"ב ע' שצד."],["1240","19","<b>אויר דק</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תנ ואילך וע' תע ואילך ובהנסמן במ\"מ לשם."],["1241","20","<b>שהחכ' נק' אור. . מים</b>: ראה מאמרי אדה\"א ויקרא שם ע' תעא ואילך. סידור שם."],["1242","21","<b>אל תאמרו מים מים</b>: חגיגה יד, ב."]]],[2800530110,"בס\"י טרף אש ומים<sup data-n=\"1243\">1</sup> ובללן יחד והוא הרקיע שנק' שמים אש ומים היינו בחי' הרוח שמורכב מאש ומי'<sup data-n=\"1244\">2</sup> יחד וזהו שמים כו' והוא מים שנעשו רקיע דאגלידו מיא<sup data-n=\"1245\">3</sup> שזה נחשב הכל מבחי' הרוחניות כהשגת שכל הרוחני כו' וזהו מ\"ד שמים קדמו דתחלה הי' הבריאה דרקיע ושמים ונשתלשל עוד למטה והוא בחי' מ\"ת שמתחת השמים שזהו בחי' ח\"ת שיורדת בדיבור ונקרא חכמה שבדיבור העליון והוא מה שכתוב ורוח אלקים מרחפת כו' שזהו ע\"פ מ\"ת שמתחת לשמים ורקיע גם אחר ההבדלה אע\"פ כשהארץ היתה תהו היו מ\"ע ומ\"ת יחד מקיפי' עליהם אבל גם אח\"כ שהבדיל הרקיע יש מבחי' רוח אלקים במ\"ת הללו והוא אמ\"ר דרוח זה מורכב מאש ומים כו' וד\"ל ואח\"כ צוה ה' שיקוו המים הללו ג\"כ ותראה היבשה והטעם הוא לפי שכ\"ז הסדר היינו בבחי' ההשתלשלות הרוחניו' דעו\"ע מחכמה עילאה עד חכמה שבדיבור אבל הגם שהיו מקיפים מכל צד לארץ לפי שצריכים להיות בהקדם זהו כמו שעלה ברצונו וחכמתו כו' ששמים קדמו ודאי כנ\"ל אבל אח\"כ הכח היותר עליון מכל בחי' מ\"ע עד מ\"ת והוא הכח דמח' תחלה שבסוף מעשה דוקא שמפני זה הארץ קדמה כנ\"ל והוא הכח העצמות דא\"ס שבכתר שלמעלה מח\"ע וח\"ת כו' וזהו הטעם שצוה ה' שיקוו המ\"ת ותראה היבשה דוקא לפי שביבשה שנק' ארץ יצא כח החידוש מאין ליש ממש להיות ברואים חדשים לגמרי כנ\"ל שאין זה במ\"ע ומ\"ת כלל ע\"כ צוה שתראה היבשה השפל במדריגה מכולם לפי שנעוץ תחלה בסוף דוקא שבארץ שהוא היבשה שם נמצא כח התחדשות יש מאין והוא צריך להוציא ממנה וע\"י דוקא כל חי וכל צומח כו' כמ\"ש תדשא הארץ תוצא הארץ דגם שבדבר ה' נעש' שמי' כו' מ\"מ בשביל בריאה חדשה לגמרי צוה הכל לארץ דוקא משום שיש בה כח התחל' דוקא וז\"ש לרוקע הארץ על המים כל\"ח שזהו חסד עליון שבמהו\"ע ממש שמחדש מאין המוחלט כו' שאין זה באמצען רק בסופן שנעוץ בתחלתן כנ\"ל ע\"כ צוה שירדו המים למטה ויתגלה היבשה למעלה מן המים כמ\"ש יורדי הים כנ\"ל וזהו כמו משפיל גאים ומגביה שפלים<sup data-n=\"1246\">4</sup> כמשי\"ת וד\"ל ובכ\"ז יובן מ\"ש במדרש בטעם קריאת שם ארץ דווקא שרצתה<sup data-n=\"1247\">5</sup> לעשות רצון קונה ועוד מלשון מרוצה<sup data-n=\"1248\">6</sup> כמו ארוץ גדוד<sup data-n=\"1249\">7</sup> רץ לבך<sup data-n=\"1250\">8</sup> והחיות רצוא<sup data-n=\"1251\">9</sup> שיש בארץ לשון מרוצה ול' רצון ושניהם אמת עפ\"י הנ\"ל וכן אני אענ' את השמי' והם יענו כו' וכן והרוה הארץ<sup data-n=\"1252\">10</sup> מגשמים דשמים וכה\"ג דהנה לפעמים אמר השמים כסאי<sup data-n=\"1253\">11</sup> והארץ הדום רגלי דמשמע שהארץ למטה מן השמים שאינו אלא הדום רגליו והשמים נק' כסא וכן אמר השמים שמים לה'<sup data-n=\"1254\">12</sup> והארץ נתן לבנ\"א שהוא רחוק הערך מאד כמו מבלתי בע\"ג לב\"ג כו' וכן שמים לרום<sup data-n=\"1255\">13</sup> וארץ לעומק וכגבוה השמים כו'<sup data-n=\"1256\">14</sup> וכה\"ג ולפעמים אמר הודו על ארץ ושמים<sup data-n=\"1257\">15</sup> וכן ביום עשות ארץ ושמים וכמו והארץ אזכור<sup data-n=\"1258\">16</sup> והארץ לעולם עומדת<sup data-n=\"1259\">17</sup> וכה\"ג אך שניהם אמת לפ\"ד מ\"ד שמים קדמו השמים כסאי כו' ולפ\"ד מ\"ד ארץ קדמה הודו על ארץ כו' ומטעם זה עולה במ\"ת<sup data-n=\"1260\">18</sup> שלפני מח' ורצון לבריאת העולמות וזהו מצד בחי' או\"ח דארץ ל' מרוצ' שתרוץ למקור חוצבה בעצמו' שהוא במח' הקדומה שנק' קדמון לכל הקדומים כנ\"ל לפי שנעוץ סופן בתחלתן דוקא כנ\"ל ואז יהיה בה כח המחדש ומוליד יש מאין בלי שיעור כלל כנ\"ל מה",[["1243","1","<b>בס\"י טרף אש ומים</b>: נסמן לקמן קכד, ב."],["1244","2","<b>הרוח שמורכב מאש ומי'</b>: ראה זהר וארא כד, א. סה\"מ תקס\"ט ע' רכז."],["1245","3","<b>דאגלידו מיא</b>: ראה זהר לך עז, א."],["1246","4","<b>משפיל גאים ומגביה שפלים</b>: ע\"פ נוסח התפלה (עזרת אבותינו)."],["1247","5","<b>ארץ. . שרצתה</b>: ב\"ר פ\"ה, ח. ראה סה\"מ תקס\"ה ח\"ב ע תקפ. (שם ע' א'ל ואילך. נדפס גם ב)מאמרי אדה\"א במדבר ח\"א ע' צה ואילך ובהנסמן במ\"מ לשם בע' שה. ויקרא ח\"ב ע' תשיז. הנחות תקע\"ז ע' צט."],["1248","6","<b>ארץ. . מרוצה</b>: ראה המאמרים שנסמנו בהערה שלפנ\"ז."],["1249","7","<b>ארוץ גדוד</b>: תהלים יח, ל."],["1250","8","<b>רץ לבך</b>: ס\"י פ\"א מ\"ח. ת\"ז בהקדמה (ז, א)."],["1251","9","<b>והחיות רצוא</b>: יחזקאל א, יד."],["1252","10","<b>והרוה הארץ</b>: ישעי' נה, י [ושם: כי אם הרוה את — ראה מאמרי אדה\"א הנחות תקע\"ז ע' רכ. וש\"נ]."],["1253","11","<b>השמים כסאי</b>: ישעי' סו, א."],["1254","12","<b>השמים שמים לה'</b>: תהלים קטו, טז."],["1255","13","<b>שמים לרום</b>: משלי כה, ג."],["1256","14","<b>וכגבוה השמים</b>: תהלים קג, יא [ושם: כגבה שמים]."],["1257","15","<b>הודו על ארץ ושמים</b>: תהלים קמח, יג."],["1258","16","<b>והארץ אזכור</b>: בחוקותי כו, מב."],["1259","17","<b>והארץ לעולם עומדת</b>: קהלת א, ד."],["1260","18","<b>במ\"ת</b>: במחשבה תחלה."]]],[2800530111,"שאין כח זה בשמי' כלל והיינו ג\"כ ל' רצון שרצתה לעשות רצון קונה שהוא עצמות הרצון שעלה ברצון ומחשבה הקדומה כנ\"ל והוא בחי' רצוא כמו אם רץ לבך כו' כגודל התשוק' ברשפי אש שלהבת שהניצוץ נמשך אחר השלהבת כמו אחריך נרוצ'<sup data-n=\"1261\">19</sup> ולכך נק' רצון מלשון מרוצ' וזהו למעל' מבחי' ראשי' דחכ' כנ\"ל ולכך נא' והארץ אזכור כו' וכה\"ג וד\"ל (וכמ\"כ בנש\"י כמו שעלו במח'<sup data-n=\"1262\">20</sup> הקדומה הנה נק' ארץ חפץ<sup data-n=\"1263\">21</sup> לע\"ל שרצתה לעשות רצון קונה בביטול כל עצמות שלמעל' מבחי' ביטול דחכמ' שבנפש האלקית כו' שזהו מצד העפר דגוף החומרי דוקא שמעפר יסודו<sup data-n=\"1264\">22</sup> כשעושה תשובה ומעשים טובים בעולם הזה דוקא שאז נק' כנ\"י כלה לשון כלתה נפשי<sup data-n=\"1265\">23</sup> בבחי' או\"ח דרצוא עד בחי' מהותו ועצמותו דוקא שלא תגיע הנשמ' לזה מצד עצמה בשרש' בח\"ע מטעם הנ\"ל בארץ שקדמה לשמים וד\"ל):\n(לב) <b>ואחר</b> כל זה יובן ענין המאמר דלעיל שקשה לזווגם כקי\"ס דוקא דהנה בקי\"ס נאמ' הפך ים ליבשה<sup data-n=\"1266\">24</sup> כו' דהיינו ע\"ד הנ\"ל כמו שהמים היו מקיפים על הארץ ושרשם למעלה היינו ענין שמים שקדמו לארץ בסדר ההשתלשלות וא\"כ כאשר הפך ים ליבשה זהו כמו שצוה יקוו המים כו' וירדו למטה שהגבוה הושפל וירד למטה להיות התגלות היבשה שהוא הארץ למעלה שזהו הגבהת השפל שעלה למעלה וכך הי' בקי\"ס שהפך ים ליבשה הרי הים שהוא הגבוה הושפל למטה להיות התגלות היבשה בתוך הים שזהו העלאת והגבהת השפל ונמצא זהו כמשפיל גבוהים ומגביה שפלים בבת אחת ולמעלה הרי הוא ענין הגבהת השפל במדרגה שהוא הארץ עילאה וירידת הגבוה והשפלתו שהן השמים שקדמו לארץ מפני שהארץ קדמה במח' תחלה כנ\"ל וע\"כ אמר שקשה לזווגם כקי\"ס לפי שנס דקי\"ס היה קשה מכל הנסים מפני שקשה הדבר מאד להשפיל הגבוה ולרומם ולהגביה הנמוך ברגע אחת וזהו כמו עד\"מ שקש' הדבר להגבי' את המקבל שהוא התלמיד ולהשפיל את<sup data-n=\"1267\">25</sup> המשפיע שהוא הרב שיקבל מן התלמיד וכה\"ג (כמו שמואל דיתיב קמיה ר\"י תלמידו<sup data-n=\"1268\">26</sup> ) או כמו שקשה הדבר להגבי' ולרומם את האשה ולהוריד להשפיל האיש המשפיע שיהי' כמו בחינת מקבל מאשתו שזהו היפך הסדר דהשתלשלות העולמות בבחי' עו\"ע שהוא בחינת משפיע ומקבל שהמשפיע ודאי למעלה והמקבל למטה כמ\"ש והוא ימשול בך<sup data-n=\"1269\">27</sup> ולהיות כל איש שורר בביתו<sup data-n=\"1270\">28</sup> ולהפוך זה הדבר שיהי' המקבל מושל במשפיע זהו קשה מאד אע\"פ שראוי להיות כן מצד שיש יתרון מעלה במקבל שהמשפיע צריך לקבל הימנו כענין ארץ קדמ' דאו\"ח דארץ נעוץ בתחלתן שלמעלה מן המשפיע וכמו שיהי' לע\"ל דא\"ח יהי' עט\"ב<sup data-n=\"1271\">29</sup> נקבה תסובב גבר<sup data-n=\"1272\">30</sup> (וכמו שאמר לאברהם כל אשר תאמר<sup data-n=\"1273\">31</sup> אליך שרה שמע בקול' אע\"פ ששר' בחי' מקבל בחי' ב\"ן הגביה' למעל' להיות אברהם בחי' מ\"ה<sup data-n=\"1274\">32</sup> שומע בקולה והוא לפי ששלשה האבות הטעימן מעין העוה\"ב<sup data-n=\"1275\">33</sup> שאז יהי' א\"ח עט\"ב כו' כמ\"ש במ\"א וד\"ל) אך לפי סדר ההשתלשלות דעכשיו שהמשפיע עיקר והמקבל טפל וכמו שמים שנק' משפיע לארץ לפי שקדמו כמ\"ש בראשית ברא כו' כנ\"ל ע\"כ הי' קשה מאד נס דקי\"ס להשפיל",[["1261","19","<b>אחריך נרוצ'</b>: שה\"ש א, ד."],["1262","20","<b>בנש\"י כמו שעלו במח'</b>: נסמן לעיל לז, ב."],["1263","21","<b>בנש\"י. . ארץ חפץ</b>: מלאכי ג, יב."],["1264","22","<b>דגוף. . שמעפר יסודו</b>: ראה בראשית ב, ז."],["1265","23","<b>כלתה נפשי</b>: תהלים פד, ג."],["1266","24","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["1267","25","<b>את</b>: ניתוסף ע\"פ דפו\"ר."],["1268","26","<b>שמואל. . ר\"י תלמידו</b>: תוד\"ה עליונים ב\"ב י, ב. ערוך מערכת נגד הא'."],["1269","27","<b>והוא ימשול בך</b>: בראשית ג, טז."],["1270","28","<b>ולהיות. . שורר בביתו</b>: אסתר א, כב."],["1271","29","<b>דא\"ח יהי' עט\"ב</b>: ע\"פ משלי יב, ד."],["1272","30","<b>נקבה תסובב גבר</b>: ירמי' לא, כא."],["1273","31","<b>כל אשר תאמר</b>: וירא כא, יב."],["1274","32","<b>ששר'. . ב\"ן. . אברהם בחי' מ\"ה</b>: ראה גם ביאוה\"ז שמיני סו, א. מאמרי אדה\"א בראשית ע' רכ. וש\"נ. תו\"ח לך פו, ד ובהערה 16."],["1275","33","<b>ששלשה האבות. . העוה\"ב</b>: ב\"ב טז, סע\"ב ואילך. ראה סה\"מ תקס\"ט ע' נ' וע' ע. ד\"ה להבין המאמר דר' בנאה הוה מציין מערתא תקע\"א (נמצא בדפוס). לקו\"ת שה\"ש טו, ג. תו\"ח ח\"ש קכא, א ובהערה 10."]]],[2800530112,"ולהוריד הים המשפיע ולהעלות לארץ ואע\"פ שארץ קדמ' זה יהי' לע\"ל ולא עכשיו דעכשיו מה שנעוץ תחלתן בסופן דוקא וסוף כו' זהו בהעלם עדיין ושיבא לידי גלוי קשה הדבר יותר מכל הנסים שהן בהיפוך הטבע (דזהו למשול בשם אלקי' בחי' ב\"ן) וזהו שאמר דקש' לזווגן כקי\"ס דהזיווג עכשיו לזווג נשמות זכרים בנשמות נקבות קשה ג\"כ עכשיו כמו שהי' קשה נס דקי\"ס דוקא לפי ששרש נשמות הזכרים מבחי' דכר שם מ\"ה העליון ונשמות הנקבות מבחי' נוקבא בחי' ב\"ן דאצי' שזהו סופא דכל דרגין כמו בחי' ארץ לגבי שמים או ים כנ\"ל (וכמו שאמר' אסתר קרקע עולם היתה<sup data-n=\"1276\">1</sup> כו'<sup data-n=\"1277\">2</sup> ע\"כ עכשיו בחי' הנוק' מקבל מדכורא אך מה שיש בה כח להוליד במ\"ן שלה כמ\"ש אשה כי תזריע וילדה<sup data-n=\"1278\">3</sup> שהוא בחי' חידוש יש מאין ממש כידוע שכל תולד' הוא בבחי' התחדשות גמורה מאין כמו שכח הצומח שבארץ מחדש הצמיח' מאין כנ\"ל זהו יש בהעלם בעצמ' מצד שנעוץ תחלתן כו' כנ\"ל בארץ וא\"כ בזווג נשמות זו\"נ צריך להעלות לבחי' הנוק' כמו שהיא בשרש' למעל' מהזכר בכח חידוש התולד' וא\"א להיות עליה זאת כ\"א שיורידו וישפילו לבחי' הדכר שהוא הגבו' עכשיו דנוק' בחינת מקבל מדכורא כי א\"א לאשה שתזריע ותלד בלי קבלת מ\"ד דדכורא וכן אמר והוא ימשול בך כנ\"ל ע\"כ הזיווגים קשה כקי\"ס דוקא כי צריך להשפיל המשפיע ולהעלות המקבל כמו קי\"ס שנתגל' היבש' ע\"י שהוריד ובקע הים כמ\"כ צריך בזווג זו\"נ להעלות לנוק' שיהי' בה כח להוליד מצד שרש' למעל' שנעוץ סופן בתחלתן כנ\"ל ולהשפיל הגבו' שהוא הדכר אז יזדווגו (ואחר הזווג להיפך שלא תמשל הנקב' בזכר ותקבל כח המוליד במ\"ן שלה מבחי' כח המוליד דמ\"ד דוקא) וזהו שאמר דרכו של איש<sup data-n=\"1279\">4</sup> לחזר אחר אשה מפני שבשרשה היא עיקר המשפיע והוא נמשך אחריה כמקבל אל המשפיע כמו לע\"ל דא\"ח עט\"ב נקב' תסובב גבר כו' וד\"ל (אך אין זה מתיישב לנכון עדיין דעכשיו עכ\"פ נוקבא מקבל מדכורא ומ\"ש אשה כי תזריע וילד' בחידוש גמור מאין זהו רק מכח המוליד שבטיפת מ\"ד א\"כ למה קשה לזווגן להעלות לנמוך ולהוריד לגבוה הרי אין כאן יריד' לגבו' כלל ולא העלא' לנמוך אם לא שנאמר להיפוך מפני שהאש' בשרש' גבו' מן הזכר גם עכשיו כמו שיהי' לע\"ל ובזווג הרי יורדת למט' להיות מקבל זהו יריד' לגבו' והעלא' לנמוך שהוא הזכר שיהי' משפיע וא\"כ אין זה כקי\"ס אדרב' בהיפוך ממש אלא צ\"ל דיריד' לגבוה הוא מה שאין שלימות לדכר בלא נוק' משום דלע\"ל א\"ח עט\"ב וכח המוליד יהי' מכח עצמו וכן אין נותנין פרנס'<sup data-n=\"1280\">5</sup> לדכר רק בשביל אשתו זו ביתו<sup data-n=\"1281\">6</sup> כו' והעלא' לנמוך היינו בנוק' שתסובב לגבר במ\"ן שלה גם עתה דמ\"ד מברר למ\"ן עד שאין שלימות לאדם בלא נוק' וכמ\"ש ויקרא שמם אדם<sup data-n=\"1282\">7</sup> כללא דדכר ונוק'<sup data-n=\"1283\">8</sup> והיינו מפני שנעוץ תחלתן בסופן דאו\"ח למעלה מאו\"י כו') (ויובן זה ע\"פ המבואר במ\"א בענין גן נעול<sup data-n=\"1284\">9</sup> כו' דבינ' יתיר'<sup data-n=\"1285\">10</sup> ניתנ' באש' יותר מבאיש שהוא בבחי' מל' שנק' אשה יראת ה'<sup data-n=\"1286\">11</sup> ותשבע\"פ מל' קרינן לה<sup data-n=\"1287\">12</sup> וכן בבחי' הירא' שע\"ז אמר בזאת יבא<sup data-n=\"1288\">13</sup> והוא בחי' הדיבור כו' דמובן משם עכ\"פ שנעש' תוס' מרוב' על העיקר מצד כח המל' עצמה וכתורה שבע\"פ שמתחדשים בה דינין הרב' נוספים",[["1276","1","<b>אסתר קרקע עולם היתה</b>: סנהדרין עד, ב."],["1277","2","<b>כו'</b>: אוצ\"ל: כו')."],["1278","3","<b>אשה כי תזריע וילדה</b>: תזריע יב, ב. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תר. וש\"נ. תו\"ח נח עב, א ובהערה 2."],["1279","4","<b>דרכו של איש</b>: קידושין ב, ב."],["1280","5","<b>אין נותנין פרנס'</b>: ראה ב\"מ נט, א."],["1281","6","<b>אשתו זו ביתו</b>: ראה יבמות סב, ב. יומא ב, א."],["1282","7","<b>ויקרא שמם אדם</b>: בראשית ה, ב [בהשמטת תיבת ”את\" — ראה הנסמן במאמרי אדה\"א נ\"ך ע' קכה]."],["1283","8","<b>כללא דדכר ונוק'</b>: ראה זהר בהקדמה יג, ב. מאמרי אדה\"א נ\"ך ס\"ע קכד ואילך. וש\"נ."],["1284","9","<b>בענין גן נעול</b>: שה\"ש ד, יב. ראה מאמרי אדה\"ז תקס\"ד ע' מט ואילך. [הנחת כ\"ק אדה\"א ומקבילו ב]פרשיות התורה ח\"א ע' נה ואילך."],["1285","10","<b>דבינ' יתיר'</b>: ראה נדה מה, ב."],["1286","11","<b>מל' שנק' אשה יראת ה'</b>: משלי לא, ל. ראה ת\"ז בהקדמה (ו, א)."],["1287","12","<b>ותשבע\"פ מל' קרינן לה</b>: ת\"ז בהקדמה (יז, א)."],["1288","13","<b>הירא'. . בזאת יבא</b>: אחרי טז, ג. נסמן לעיל מה, א."]]],[2800530113,"על תושב\"כ שאין זה בתור' שבכתב כלל וכציור הולד באברים בתוס' מרובה על עיקר כח טיפת מ\"ד וכן התוס' חדש בדיבור כו' ע\"ש) והנ' עכשיו בזמן הגלות עדיין לא עלת' המל' סופא דכל דרגין הנק' ארץ וכה\"ג להיות נעוץ בתחלתו ממש כנ\"ל (אע\"פ שכל יו\"כ עול' המל'<sup data-n=\"1289\">14</sup> בפנימיות הכתר כידוע וכן מ\"ש ותרם התיב'<sup data-n=\"1290\">15</sup> כו' ותנח כו' בחדש הז'<sup data-n=\"1291\">16</sup> כו' זהו בבחי' הפנימיות שלה לבד מפני שכל יו\"כ הוא מעין דלע\"ל<sup data-n=\"1292\">17</sup> שהרי נק' שבת שבתון<sup data-n=\"1293\">18</sup> כו' אבל בחיצוניות היא בחי' מקבל מז\"א והוא בחי' יחוד דזו\"נ כל השנ' דמ\"ה מברר לב\"ן<sup data-n=\"1294\">19</sup> דוקא כידוע וגם בשבת וי\"ט כו') אלא בחי' המלכות מקבלת מבחינת ז\"א שבו מוחין דאבא כמ\"ש מה שמו ומה שם בנו<sup data-n=\"1295\">20</sup> כו' וכמו משל הדבור שמקבל מן המדות שבלב שבהם אור השכל וחכמה שברא' וזהו מגיד מראשית אחרית<sup data-n=\"1296\">21</sup> פי' מגיד ל' המשכ'<sup data-n=\"1297\">22</sup> מההעלם לגלוי והחכמ' הגם שמאין תמצא ליש מ\"מ נק' ראשית כמ\"ש ראשית חכמה<sup data-n=\"1298\">23</sup> לפי שבה ראשית הגלוי<sup data-n=\"1299\">24</sup> אור דא\"ס שבהעלם אור הכתר כידוע והוא הנק' מקור הראשון להאיר ולהמשיך אור ושפע עד בחי' המל' שנק' אחרית סופא דכולא וא\"כ לא תעל' המל' יותר ממקור הראשון שהוא החכמ' שנק' ראשית וז\"ש מגיד מראשית אחרית ונק' שרותא וסיומא כו' והיינו בכלל ענין שם מ\"ה שמשפיע לב\"ן כנ\"ל והמופת לזה הנה<sup data-n=\"1300\">25</sup> אנו רואים למטה בארץ התחתונ' דאע\"פ שיש בה כח החידוש לחדש ולהצמיח יש מאין ממש כנ\"ל מ\"מ לא תוציא צמחה מצד עצמה רק כשיומשך עליה מטר מן השמים והרוה את הארץ והולידה והצמיחה (רק הספיחים שמאליהם יבאו כו') וכמו מי התהום שעולה ומשקה<sup data-n=\"1301\">26</sup> כו' (וגם בג\"ע הרי נהר יוצא מעדן<sup data-n=\"1302\">27</sup> להשקות את הגן כו') והיינו כמו בחי' מ\"ד שהמה עיקר הגורמים בחי' התולדה של הולד אע\"פ שיש כח במ\"ן דאשה להוליד מצד עצמה כמ\"ש אשה כי תזריע כו' כנ\"ל (וכן בלבנה שמקבלת מאור השמש אז יש בכח אורה לפעול פעולתה בארץ כמ\"ש במ\"א בענין סיהרא<sup data-n=\"1303\">28</sup> לית לה מגרמה כלום<sup data-n=\"1304\">29</sup> וד\"ל) וכך בלא מטר לא תוציא הארץ צמחה כלל אע\"פ שיש בכחה להצמיח כו' כמו שהנקבה לא תוליד מעצמה אע\"פ שיש בה כח המוליד בלתי שתקבל ממ\"ד דדכורא מטעם הנ\"ל וזהו מגיד מראשית אחרית דוקא דמ\"ה מברר לב\"ן והוא עיקר המשפיע ועל כן אמר והוא ימשול בך כו' וכמו בשמים וארץ עכשיו דשמים נק' משפיע והארץ מקבל וכמ\"ש אני אענה את השמים והם יענו את הארץ וכמו והרוה את הארץ והולידה כנ\"ל וד\"ל:\n(לג) <b>ומקדם</b> אשר לא נעשו<sup data-n=\"1305\">30</sup> כו' פי' מקדם מקדמונו ש\"ע<sup data-n=\"1306\">31</sup> כו' שזהו מקדם לחכמה שנק' ראשית דמ\"ש מגיד מראשית אחרית היינו כאשר המל' שנק' אחרית מקבל מן החכמ' שנק' ראשית וידוע דכל ראשית יש לו שני ושלישי כו' כמו שסופר אב\"ג כו' אבל דבר יחידי שאין שני לו כלל אינו בגדר מספר ולא שייך לקרותו ראשית אחר שאין מה לספור אחריו כלל וכך הוא בחי' קדם שנקרא קדמון לכל כו' שלא היה לו שני וזהו ההפרש בין ראשון לקדמון ולא כמו שסוברים בל' קדימה שהוא",[["1289","14","<b>יו\"כ עול' המל'</b>: ראה גם לקמן קמג, ב ובהנסמן במ\"מ לשם."],["1290","15","<b>ותרם התיב'</b>: נסמן לקמן קכז, ב."],["1291","16","<b>ותנח כו' בחדש הז'</b>: נח ח, ד."],["1292","17","<b>יו\"כ. . דלע\"ל</b>: ראה לקו\"ת להאריז\"ל נח (ו, יג). סידור שער יוכ\"פ רמט, ד. תו\"ח נח מו, א ובהערה 11."],["1293","18","<b>שבת שבתון</b>: אחרי טז, לא. אמור כג, לב."],["1294","19","<b>דמ\"ה מברר לב\"ן</b>: נסמן לקמן קלג, א."],["1295","20","<b>מה שמו. . בנו</b>: משלי ל, ד."],["1296","21","<b>מגיד מראשית אחרית</b>: ישעי' מו, י."],["1297","22","<b>מגיד ל' המשכ'</b>: ראה סה\"מ תקס\"ה כאן ע' רכד וע' רלב: כמ\"ש נהר דינור נגיד ונפיק. אמ\"ב שער הק\"ש כא, א. מאמרי אדה\"א קונטרסים ע' תקמז ובהערה 27."],["1298","23","<b>ראשית חכמה</b>: תהלים קיא, י. ראה לקמן סא, א ובהנסמן במ\"מ לשם."],["1299","24","<b>שבת ראשית הגלוי</b>: ראה תניא פל\"ה בהגהה."],["1300","25","<b>הנה</b>: ניתוסף ע\"פ דפו\"ר."],["1301","26","<b>מי התהום שעולה ומשקה</b>: ראה ירושלמי ברכות פ\"ט, סה\"ב. ב\"ר פי\"ג, יז."],["1302","27","<b>נהר יוצא מעדן</b>: בראשית ב, י."],["1303","28","<b>כמ\"ש במ\"א בענין סיהרא</b>: ראה סידור שחרית קפב, ד. מאמרי אדה\"א דברים ח\"ג ע' תתפג. וש\"נ. קונטרסים ע' רו. וש\"נ."],["1304","29","<b>סיהרא. . כלום</b>: ראה זהר תולדות קלה, סע\"ב. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' כד."],["1305","30","<b>ומקדם אשר לא נעשו</b>: המשך הכתוב מגיד מראשית אחרית."],["1306","31","<b>מקדם מקדמונו ש\"ע</b>: ראה ב\"ר פל\"ח, ז. פמ\"א, ז. וראה גם תו\"א ויקהל פז, ד ובהנסמן במ\"מ לשם הערה ד\"ה מבחי' ראשית. לקו\"ת ראה יח, ד. מאמרי אדה\"ז תקס\"ה ח\"א ריש ע' קכח. לקמן עד, א. קב, א."]]],[2800530114,"קודם לבא אחריו אלא קדמותו היינו שקדם להיות לבדו בלי שיתוף עמו דבר כלל (אך לא שגם עתה הוא לבדו שזהו הנק' יחיד אלא כשהי' לבדו בלי דבר מה זולתו ואח\"כ במשך זמן נמשך ממנו עוד הרבה אבל הכל ממנו זהו שנק' קדמון בל' הקדש כמו איש שהיה קדום בתושבי העיר שלא היה שום איש זולתו ואח\"כ מיוצאי חלציו דור אחר דור נתרבו עוד תושבים רבים נקרא הוא קדמון ולא ראשון או כמו הנהר שהיה לבדה ואחר כך נמשך ממנה לחפירות רבות וכה\"ג לא שייך לקרות לנהר ראשון אלא קדום מאחר שנבדל הנהר לבדו טרם שנמשך ממנה וגם מה שנמשך הכל מן הנהר כו' כך יובן עד\"מ בבחינת א\"ק למעלה שנקרא קדמון שקדם לכל מה שנסתעף ממנו המשכות אורות שהיה לבדו והכל ממנו כו' משא\"כ ראשון ושני שהראשון בערך מספר לבדו ויש לו שני שיוסיף עליו וכן השלישי דחסר כאן ב' דברים א' שאינו לבדו גם בהיותו בלא השני כי יש שני לו במציאות נבדל ממנו ונספר לאחדים כמוהו ונקרא אחד המנוי<sup data-n=\"1307\">1</sup> שכללותו מספר קצוב עשרה וכה\"ג שכל א' יש לו מקו' בפ\"ע שבלעדו לא יושלם המספר (ולקדמון אין שני במציאות כלל בתחלה וגם בסוף הכל ממנו עד שכל התחלקו' וריבוי שמסתעף כלולי' בו ממש כנ\"ל) והב' שלא נק' קדום בקדימה חלוטה לכל הבאי' אחריו אעפ\"י שהיה אחד לבדו תחלה כי בהכרח ודאי קדם לו המקו' העצמי שנק' קדמון שממנו יצא הכל רק שנק' ראשון במספר כבן הנולד ראשון לגבי השני שנולד אחריו לפי שהוא ראשית אונו<sup data-n=\"1308\">2</sup> והאב הוא מקו' העצמי שהוליד לכל הבנים וכל א' שרשו במוח האב<sup data-n=\"1309\">3</sup> מיוחד בפ\"ע ואין לבן הראשון שום תוס' כלל לפי שלא ממנו נולדו הבאים אלא מן האב משא\"כ במשל הנהר והחפירו' או אזרח הארץ הנ\"ל הרי כל החפירות מן הנהר ומה שזה ראשון ואחריו שני הן הכל הסתעפו' המשכו' שמן הנהר אעפ\"י שהוא באופן שחפירה ראשונ' ממשכת לשניה ושניה לשלישית הרי השניה קבלתה מראשונ' מ\"מ מי הנהר הוא גם ביותר אחרון וכך הוא במשל אזרח תושב העיר שהיה לבדו בקדימ' חלוטה שלא היה קודם לו מקור בעיר זה היינו בחי' קדמון בעיר באופן דגם הבן שהוליד שם נק' דור ראשון ולא קדמון לנולד ממנו מאחר שקדם לו אב הראשון שלא הי' שם מקור המולידו ע\"ד דוגמא אדה\"ר הי' לבדו ושת בנו נק' דור ראשון ואנוש דור שני וכך עד סוף כל הדו' אבו' ובני' כולם נק' במספר המנוי ראשון ושני עד דור האלף אע\"פ שכל דור נק' אב לבניה' אחריהם שבדור הבא אחריו שנמצא כל דור כלול בדור שלפניו ואין זה כמספר האחים שהשני נבדל בפני עצמו בשרש מיוחד ולא שנמשך התהוותו מן הראשון וכן השלישי והרביעי כו' מ\"מ גם זה נק' מספר ראשון ושני עד אלף דור אבל אדה\"ר עצמו לא שייך לקרותו דור ראשון כי ממנו נמשכו כל הדורות וכמו שלא שייך לקרו' לנהר ראשון רק היוצא ממנו תחלה נקרא דור ראשון כו' אלא נקרא קדמון שקדם לכל הדורו' בקדימה חלוטה בענין זה שבא במספר הדורות אעפ\"י שגם אדה\"ר הי' לו מקור כי נברא יש מאין שהוא כח אלקי כמ\"ש ויפח באפיו נשמת חיים<sup data-n=\"1310\">4</sup> אבל נשמתו בבחי' נשמת אדם קדומה לכל באין קדימ' אדם תחלה לו וכולל הכל כי ממנו הכל (ואין כ\"ז רק להבין מזה למעלה בבחי' א\"ק",[["1307","1","<b>אחד המנוי</b>: ראה חובת הלבבות שער היחוד פ\"ח. פרדס (שער עצמות וכלים) ש\"ד פ\"ה. תו\"ח נח סז, א ובהערה 1."],["1308","2","<b>ראשית אונו</b>: תצא כא, יז."],["1309","3","<b>הבנים. . ששרשו במוח האב</b>: תניא פ\"ב."],["1310","4","<b>ויפח באפיו נשמת חיים</b>: בראשית ב, ז."]]],[2800530115,"שנקרא אדם דבריאה שממנו כל ההשתלשלות דאבי\"ע כידוע בענין קורא הדורות מראש<sup data-n=\"1311\">5</sup> שלזה נקרא אדם קדמון ולא ראשון מפני ב' דברים הללו שאין קדימה לו בבחי' אדם רק היה לבדו וגם מה שיסתעף הכל ממנו ואינו כנוסף על עצמו כמספר האחדים<sup data-n=\"1312\">6</sup> אך מ\"מ באמת הרי אדה\"ר נקרא ראשון<sup data-n=\"1313\">7</sup> ולא קדמון כי בלה\"ק נקרא אדה\"ר רק בזוהר נקרא אדם קדמאה<sup data-n=\"1314\">8</sup> וראיה שבמספר הדורות בד\"ה<sup data-n=\"1315\">9</sup> התחיל מאדה\"ר באמרו אדם שת אנוש דלפי הנ\"ל לא היה לו למנותו אלא מוכרח דגם שהוא כולל כל הדורות וממנו נסתעפו מ\"מ נקרא ראשון ובנו שת נקרא שני כו' וכך הוא בכל תולדות אבות ובנים כאבות אחד היה אברהם<sup data-n=\"1316\">10</sup> ויצחק שני וכה\"ג משא\"כ בנהר שאין למנותו במספר ראשון ובמשל אזרח הארץ ראוי לקרותו ראשון כפי משל הדורות מאדה\"ר אע\"פ שהי' לבדו ממש מאחר שיש לו מקור שהולידו נקרא דור הראשון בתולדה כו' וד\"ל ונמצא מובן מכ\"ז שיש ב' מדריגות בענין קדמון הא' שקדם בתולדה שכל הבאים נמשכו ממנו וכולל הכל אבל יש לו מקור שהולידו כמו אדה\"ר וכה\"ג וזהו למעלה בחי' א\"ק או מח' הקדומה אבל מה שאמר צופה ומביט בסקירה<sup data-n=\"1317\">11</sup> כו' כל הדורות יחד מאדה\"ר עד דור האחרון שהו בחי' מחשב' העצמית שבבחי' מל' דא\"ס עצמו שלא יש לו תחלה כלל שמשם נמשך נשמת אדה\"ר בכלל ונתחלקה לפרטיי' דור אחר דור כו' כנ\"ל שלגבי מח' זו נקרא א\"ק אדם דבריאה כאדה\"ר ממש ומדריגה הב' בקדמון שנקרא קדמונו ש\"ע והוא באמת בחי' יחיד שהוא לבדו ממש ואין לו תחלה ואמנם גם מה שעלה במח' זו כל הדורות דאדה\"ר נקרא מל' דא\"ס שאנו אומרים ע\"ז אדון עולם<sup data-n=\"1318\">12</sup> אשר מלך בטרם כל יצור כו' דלכאורה איך מלך בטרם כל יצור דמשמע גם קודם שנמשך הקו\"ח להיות בחי' א\"ק אלא היינו בחי' מל' דא\"ס בחי' מח' שצופה בעצמו כו' ואח\"כ יצא לגלוי להיות בבחי' גלוי רצון נקרא רצון הקדום או מח' הקדומה והוא מ\"ש לעת נעשה בחפצו כל בבחי' כללות דכל הדורות וכל העולמות דאבי\"ע כבר נעשה שיצא ההעלם בגלוי הרצון ומח' זו שזהו ענין ב\"ש במח' הקדומ' והי' העולם<sup data-n=\"1319\">13</sup> ומה שבא אח\"כ לגלוי גמור באבי\"ע אין כל חדש כלל כך לעת נעשה בחפצו ורצונו כל אזי מלך שמו נק' מן ההעלם לגלוי והיינו מל' דא\"ס כאשר ירד למטה להיות מלך מתנשא על ימות עולם<sup data-n=\"1320\">14</sup> דאבי\"ע ותחלה הי' מלך מרומם לבדו מל' וזהו ההפר' בין יחיד חי העולמים מלך למלך יחיד<sup data-n=\"1321\">15</sup> חי העולמים דיחיד היינו כמו שהוא לבדו ממש קודם שצופה כו' וחה\"ע בחי' מחשבה אחת שצופה כנ\"ל שזהו חה\"ע בהעלם או אדון עולם כו' ובבואו לגלוי הוא מל' דא\"ס שבא בגלוי בקו\"ח שנקרא מתנשא על ימ\"ע כנ\"ל אבל מלך יחיד פירושו שמלכותו<sup data-n=\"1322\">16</sup> ביחידות שזהו ענין מלך מרומם לבדו שהוא מל' דא\"ס קודם הגלוי ואח\"כ חה\"ע בגלוי דסובב וממלא דקו\"ח והכל עולה לענין א' וג' מדריגות הן מלמעלה למטה יחיד חה\"ע מלך וד\"ל) וזהו לפני אחד מה אתה סופר<sup data-n=\"1323\">17</sup> שהוא יחידי ואין לספור אחריו כלל והיינו למעלה מן החכמ' שנקראת ראשית במספר והוא הנקרא אחד שבא במספר רק",[["1311","5","<b>קורא הדורות מראש</b>: נסמן לקמן קכג, ב."],["1312","6","<b>האחדים</b>: אוצ\"ל: האחדים)."],["1313","7","<b>אדה\"ר נק' ראשון</b>: סנהדרין לז, סע\"א (במשנה). ברכות לא, א."],["1314","8","<b>אדם קדמאה</b>: זהר בראשית לא, ב. לד, א."],["1315","9","<b>בד\"ה</b>: ( בדברי הימים) בתחלתו."],["1316","10","<b>אחד היה אברהם</b>: יחזקאל לג, כד."],["1317","11","<b>צופה ומביט בסקירה</b>: נסמן לקמן קכא, ב."],["1318","12","<b>אדון עולם</b>: נוסח תפלת השחר. ראה גם לקמן עז, א."],["1319","13","<b>ב\"ש. . והי' העולם</b>: נוסח ברוך שאמר. ראה גם לקמן קיח, א."],["1320","14","<b>מלך. . עולם</b>: ע\"פ ברכת יוצר. ראה גם עט\"ר שער ר\"ה ע' ו."],["1321","15","<b>ההפר' בין יחיד. . למלך יחיד</b>: ברכת ברוך שאמר וישתבח. ראה גם לקמן עז, א. עט\"ר שם."],["1322","16","<b>שמלכותו</b>: ניתוסף ע\"פ דפו\"ר."],["1323","17","<b>לפני אחד מה אתה סופר</b>: ראה ס\"י פ\"א מ\"ז."]]],[2800530116,"שכולם מתאחדים אבל מי שאין לו תחיל' ואין לו תכלה<sup data-n=\"1324\">1</sup> זהו למעל' מבחי' ראשית ואחרית דע\"ס שאין שם בחי' מספר דע\"ס עשר ולא תשע<sup data-n=\"1325\">2</sup> ולא י\"א אלא מה אתה סופר והכתר אינו נמנ' עם הספי' ע\"כ נק' החכמ' ראשית במספר אבל כאשר הכתר נמנ' ראשון כמו שאנו אומרים אחת שהוא הכתר אחת ושתים<sup data-n=\"1326\">3</sup> כתר חו\"ב אחת ושלש חב\"ד הרי אח' כולל הכל לפי שמן הכתר נסתעפו כולם וכמ\"ש בע\"ח דע\"י וא\"א מלובש תוך כל ספי'<sup data-n=\"1327\">4</sup> ומקיף כולם כו' זהו כמשל מספר הדורות זה מסתעף מזה כך החכמ' נאצל מאור הכתר שנקרא ראשון והחכמה שני ובינה שמקבלת מחכמה שלישי וכה\"ג מ\"מ בגדר מספר הוא כנ\"ל ולכך נקרא בלשון תחלה עכ\"פ שז\"ש נעוץ תחלתן בסופן וסופן בתחלתן שזהו כתר שנקרא תחילתן והמל' סופן וא\"כ לכאורה מהו ההפר' בין ראשית ואחרית או תחלה וסוף לגבי מי שאין לו תחילה ואין לו תכל' דהיינו למעל' מבחי' תחל' וסוף ומה שאמר דעצמות אא\"ס אין לו שיעור למעלה<sup data-n=\"1328\">5</sup> אין זה למעלה ומט' ממש כענין תחל' וסוף שהתחל' נק' מעל' והסוף נקרא מטה אלא זהו שם המושאל כי עצמות אא\"ס נבדל מערך ובחי' מעלה ומטה כלל רק שרוצה לפרש כחו של א\"ס עד אין שיעור בעצמות שזהו ממש ענין אין לו תחל' כלל מאחר שאין שיעור וקץ לעילוי אחר עילוי בעצמותו כו' וכן פי' אין לו תכלית למטה שזהו ענין אין לו תכל' ולפ\"ז התחל' וסוף דכתר ומל' שוין ממש וזהו מ\"ש שצופה ומביט מראש לסוף בסקיר' אחת היינו בחינת יריד' והשפל' להיות עכ\"פ כולל תחל' וסוף כאחת כנ\"ל ונמצא יובן זה ע\"ד הנ\"ל בג' מדריגות דיחיד חה\"ע מלך דיחיד למעלה מאחד וגם למעלה מקדמון<sup data-n=\"1329\">6</sup> כו' ומ\"ש לפני אחד מה אתה סופר מובן בב' אופנים א' שמדבר בבחינת מחשב' שצופ' כו' שכולל תחלה וסוף עכ\"פ שע\"ז שייך לומר מה אתה סופר ראשון ושני מאחר שכוללם יחד כא' ממש מבלי קדימה לתחל' כו' אבל עכ\"ז בגדר מספר הוא כאדה\"ר שכלול מכל הדורות שיצאו מן ההעלם כו' והאופן הב' בבחי' יחיד עצמו שלמעלה גם מקדמון שבמקור התולד' כו' שלמעלה גם מהיות כולל תחל' וסוף מאחר שהוא למעל' עד אין שיעור שאין לו תחל' כו' שם לא יתכן לומר גם ענין נעוץ תחלתן בסופן וסופן כו' אחר שנבדל ומושלל לגמרי מבחי' זו דתחל' וסוף גם בהעלם כו' וע\"ז אמר לפני אחד מה אתה סופר שמושלל מכל בחי' מספר גם מן מספר דתחל' וסוף ונקרא לפני אחד הקדום כו' וכמ\"כ יתפר' בב' אופנים הנ\"ל מ\"ש אנת הוא חד<sup data-n=\"1330\">7</sup> ולא בחושבן י\"ס שזהו לשלול מספר אחד המנוי דראשון ושני כנ\"ל והב' ולא בחושבן לשלול גם מספר דתחל' וסוף שנק' אחד הקדום שהי' לבדו ואח\"כ נסתעף ממנו הריבוי כנ\"ל וד\"ל וזהו ומקדם אשר לא נעש' כו' דהנ' לע\"ל כתיב הנני בורא חדשה בארץ<sup data-n=\"1331\">8</sup> נקב' תסובב גבר פי' חדש' חדש' לגמרי שזהו כח המחדש יש מאין ממש שבארץ דוקא משום דנעוץ תחלתן בסופן וסופן כו' ובתחלה ובסוף דוקא יש כח זה המחדש יש מאין וכנ\"ל דהחכמ' מאין ליש תמצא וכח החידוש זה דחכמה מאין זהו דוקא בתחלה דהיינו אור הכתר<sup data-n=\"1332\">9</sup> וידוע",[["1324","1","<b>מי שאין לו תחיל'. . תכלה</b>: ראה חובת הלבבות שער היחוד ספ\"ה. המשך תרס\"ו ע' כ."],["1325","2","<b>עשר ולא תשע</b>: ס\"י פ\"א מ\"ד."],["1326","3","<b>שאנו אומרים אחת. . ושתים</b>: במוסף (סדר העבודה) ליוה\"כ."],["1327","4","<b>דע\"י. . תוך כל ספי'</b>: נסמן לקמן קכו, ב."],["1328","5","<b>אא\"ס אין לו שיעור ומעלה</b>: נסמן לעיל ל, א."],["1329","6","<b>דיחיד למעלה מאחד. . מקדמון</b>: ראה לקמן קטז, ב."],["1330","7","<b>אנת הוא חד</b>: ת\"ז בהקדמה (יז, א)."],["1331","8","<b>הנני בורא חדשה בארץ</b>: ירמי' לא, כא [ושם: כי ברה ה' — ראה לקמן נח, א. ס, א. מאמרי אדה\"א ויקרא ח\"ב ע' תערב. וש\"נ. תו\"ח וישב ריא, ד ובהערה 52]."],["1332","9","<b>הכתר. . מבחי' אחרונ'</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב פ\"א."]]],[2800530117,"שיש בו מבחי' אחרונ' שבעצמות א\"ס ב\"ה והוא מל' דא\"ס וגם הוא שרש וראש לנאצלים והיינו פנימית וחיצוניות שבכתר שהוא ע\"י וא\"א דבפנימית הוא נחשב מעצמות א\"ס שנקרא קדמון לכל כו' שלמעלה גם מהיות בחי' מקור מחדש מאין ליש דחכמ' וכמ\"ש עושה פלא<sup data-n=\"1333\">10</sup> אותיות אלף<sup data-n=\"1334\">11</sup> דמה שמן ההעלם דכתר נמשך מאין ליש דחכמה זהו רק אין של היש לבד והוא עושה פלא דחכמה כמו אאלפך חכמה<sup data-n=\"1335\">12</sup> אבל פנימית הכתר יש בו מבחי' אין העצמות ממש הנ\"ל שלמעל' מבחינת תחל' וסוף כי אין לו תחל' ואין לו תכל' כו' כנ\"ל ואין עליית המל' שנקרא סופן רק בתחלתן שהוא חיצוניות הכתר כשנקרא ראש ושר' לנאצלים והוא שנקרא מקור המוליד ומחדש החכמ' מאין ליש ולא למעלה מתחלתן כו' ויש עליה ב' למל' במל' דא\"ס עצמו שהוא בחי' אחרונ' שבעצמות שנקרא מחשבה הקדומה כנ\"ל וזהו כאשר המל' מבחינת קדם קדמונו של עולם כו' שלמעלה גם מתחלתן דכתר כו' משום דאור חוזר חוזר לקדמותו<sup data-n=\"1336\">13</sup> ממש דהיינו לבחינת קדם שלפני אחד דעשר ספירות דאצי' שבהעלם הכתר כשהוא מקור וראש לנאצלים אז נאמר הנני בורא חדשה בארץ דוקא ופי' חדשה לגמרי והוא אשר נקבה תסובב גבר שמלבד שאין הנוק' מקבל מדכורא בדרך מ\"ד ומ\"ן כמטר השמים שמרוה הארץ וכאשה כי תזריע שמקבל ממ\"ד כח המוליד כנ\"ל אלא שתסובב לגבר בבחי' עטרת ומקיף למקיף בראשו וכמ\"ש אבן מאסו הבונים<sup data-n=\"1337\">14</sup> היתה לראש פינה וכן מ\"ש מאת ה' היתה זאת<sup data-n=\"1338\">15</sup> שהיא בחי' המל'<sup data-n=\"1339\">16</sup> שנבנית משם הוי\"ה דז\"א ובעלי' הב' הנ\"ל היא נפלאת בעינינו בבחי' סדכ\"ס<sup data-n=\"1340\">17</sup> דלית מחשבה ת\"ב כלל<sup data-n=\"1341\">18</sup> והוא מ\"ש יצאו מ\"ח מירושלים<sup data-n=\"1342\">19</sup> חצים אל הים הקדמוני דבחי' קדמונו של עולם הנ\"ל וד\"ל:\n(לד) <b>וזהו</b> אשר לא נעשו כו' דהנה כתיב כל אשר חפץ<sup data-n=\"1343\">20</sup> ה' עשה בשמים ובארץ בימים כו' דידוע שחפץ זה הוא בחי' הרצון הקדום וכתרגום בראשית ברא בקדמין ברא<sup data-n=\"1344\">21</sup> כו' הרי פי' לראשי' דחכמ' מאין דכתר תמצא בבחי' קדם דקדמון הנ\"ל וידוע ג\"כ דפי' רצון הקדו' היינו ג\"כ ענין רצון הפשוט<sup data-n=\"1345\">22</sup> כמו כשעלה ברצונו הפשוט<sup data-n=\"1346\">23</sup> כו' והענין הוא דכאשר יש טעם לרצון אפי' בהעלם נק' רצון מורכב אבל כאשר הרצון למעלה מן טעם לרצון נק' רצון פשוט וזהו פנימי' הכתר הנ\"ל שיש בו מבחי' אחרונה שבעצמות והוא ג\"כ ענין פי' רצון הקדום שקדם הרצון בעצמותו ממש מבחי' אחדו' הפשוט' שלמעל' מבחי' אחד המנוי הנ\"ל שבא לכלל מספר בהעלם ובגלוי (כמ\"ש למעל' בענין לפני אחד מה אתה סופר בב' אופנים כו') ונק' רצון המוחלט כמו עד\"מ שהוחלט רצון באדם לבנות בנין ולא בא לגלוי גם לעצמו רק בעת ידוע כו' כמ\"ש במ\"א<sup data-n=\"1347\">24</sup> וכמ\"כ ענין כשעלה ברצונו הפשוט שעלה הרצון המוחלט זה לבוא מהעלם העצמות לגלוי בעצמו עדיין וזהו פי' ברוך שאמר והיה העולם כמ\"ש במ\"א<sup data-n=\"1348\">25</sup> דהיינו ענין המאמר בריש הורמנא דמלכא גליף גליפו<sup data-n=\"1349\">26</sup> כו' וא\"כ יש להבין מ\"ש כל אשר חפץ ה' עשה דמשמע מזה דעוש' בשמים וארץ בחפץ ה' הפשוט וקדום הנ\"ל ולמעל' מבואר בבחי' קדם שהוא למעל' מהיות בחי' מקור לחכמ' וגם למעלה",[["1333","10","<b>עושה פלא</b>: בשלח טו, יא."],["1334","11","<b>פלא אותיות אלף</b>: ראה ת\"ז ת\"ע (קלה, א). הנסמן במאמרי אדה\"א נ\"ך ע' תקסו־ קונטרסים ע' ז."],["1335","12","<b>אאלפך חכמה</b>: נסמן לעיל לא, ב."],["1336","13","<b>דאור חוזר חוזר לקדמותו</b>: נסמן לעיל כט, א."],["1337","14","<b>אבן מאסו הבונים</b>: תהלים קיח, כב. ראה גם מאמרי אדה\"א בראשית ע' שנט. שמות ח\"ב ע' תלב. וש\"נ."],["1338","15","<b>מאת ה' היתה זאת</b>: תהלים שם, כג."],["1339","16","<b>זאת. . המל'</b>: נסמן לעיל לה, א."],["1340","17","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["1341","18","<b>דלית מחשבה ת\"ב כלל</b>: ת\"ז בהקדמה (יז, א)."],["1342","19","<b>יצאו מ\"ח מירושלים</b>: זכרי' יד, ח."],["1343","20","<b>כל אשר חפץ</b>: תהלים קלה, ו. ראה גם לקמן קלב, א."],["1344","21","<b>בראשית. . ברא</b>: ת\"א לבראשית א, א."],["1345","22","<b>רצון הקדו'. . הפשוט</b>: ראה סידור שער המילה קלט, ד."],["1346","23","<b>כשעלה ברצונו הפשוט</b>: נסמן לקמן קטו, א."],["1347","24","<b>רצון המוחלט. . במ\"א</b>: ראה גם לקמן קכא, ב."],["1348","25","<b>ברוך שאמר. . במ\"א</b>: ראה שע\"ת ח\"א כו, א."],["1349","26","<b>בריש. . גליף גליפו</b>: ראה זהר בראשית טו, א."]]],[2800530118,"ממחשבה שצופ' כו' שכולל תחלת וסוף כו' להיותו בפנימית הכתר בכלל שהוא מבחי' אחרונ' שבעצמות שאין לו תחלה וסוף כו' אלא צ\"ל דיש ב' מדרגות בקדם כנ\"ל א' שכולל תחלה וסוף דכל אשר נעשה אח\"כ בגלוי דע\"ס דאבי\"ע והוא בחי' מחשבה הקדומ' שצופה כו' בסקירה א' שכולל' יחד עכ\"פ וזהו לעת נעש' בחפצו כבר בהעלם המחשב' זו כל אשר יבא בגלוי וזהו שקדם את הכל בהעלם כו' ונק' חה\"ע<sup data-n=\"1350\">1</sup> כו' וזהו שאמר והי' העולם כו' כנ\"ל באריכות וזהו ג\"כ ענין כל אשר חפץ ה' כבר בהעל' מחשב' הקדומ' עשה בפועל באבי\"ע בשמים וארץ סובב וממלא<sup data-n=\"1351\">2</sup> כו' והב' הוא קדמונו ש\"ע ממש שנקר' יחיד לבדו מלך מרומם לבדו ממש קודם שבא לכלל העלם המח\"ק להיות צופה כו' הנק' חי העולמים כו' שע\"ז אמ' לפני אחד לפני אחד הקדום שכולל הכל מה אתה כו' וכנ\"ל באופן הב' דלפני אחד כו' וזהו למעלה מכל אשר חפץ ה' עשה כו' אחר שלא בא לכלל בחי' חפץ ורצון שנק' מח' גם לא בדרך כלל לכלול הכל כא' כו' כי הוא למעל' מבחי' תחלה וסוף כי אין לו תחלה וסוף כלל וזהו ענין ומקדם אשר לא נעשו פי' במדריג' הב' דקדם הנ\"ל שנק' יחיד לבדו ממש אשר לא בא עדיין גם בהעל' הרצון הנק' רצון קדום או מחשב' קדומ' כי הוא למעל' עדיין מרצון הקדום ופשוט הנ\"ל שעלה מכבר בעצמותו להאציל ולברוא שז\"ש בקדמין ברא כו' (אלא הוא כמו רצון המוחלט שבהעלם עצמותו כלול לגמרי טרם שעלה רצון זה גם בעצמו לגלוי כו' דלא כדלעיל שזהו כמו שא' כשעלה ברצונו הפשוט דעלי' זו גלוי העלם עצמותו הוא כו' אלא כמו שאמרו ז\"ל קודם שנברא העולם<sup data-n=\"1352\">3</sup> הי' הוא ושמו בלבד שמ\"ו גי' רצון<sup data-n=\"1353\">4</sup> שכלול בעצמותו ממש) וזהו אשר לא נעשו בבחי' עשי' דכל אשר חפץ עשה הנ\"ל גם לא בבחי' הכלל דתחלתן וסופן דכל עשי' שנק' סוף שרשו הוא מגיע בתחלתו אבל מקדם זה שהוא למעלה מתחלה וסוף זהו שלא נעשו שלא בא לכלל עשי' עדיין מן הרצון שבתחלה מפני שהוא למעלה הרבה מכל מקור חידוש העולם בכלל ובפרט מטעם הנ\"ל וד\"ל. אך מ\"ש ומקדם הרי קאי אדסמיך לי' מגיד מראשית וגם מקדם ומשמע שגם מקדם אשר לא נמשך בהעלם וגלוי עדיין בהשתלשלות דבקדמין ובחוכמתא שנק' תחלה וסוף ראשית ואחרית כנ\"ל גם משם יומשך רק שיהי' דבר חדש לגמרי אשר עדיין לא נעשו ונמשכו מעולם ברצון הקדום ומח\"ק הנ\"ל והיינו בחי' עלי' הב' דמל' שלמעלה מתחלתן ג\"כ והוא מ\"ש הנני בורא חדשה בארץ חדשה לגמרי שלא הי' עדיין חידוש כזה בחידוש דרצון הקדום וחכמ' הקדומה שנק' תחלתן דרך כלל להיות שמקדם זה אשר לא נעשו הנ\"ל הוא שמאיר בסוף הכל שהוא הארץ אז גם שם יהי' חדשות שלא היו מעולם וזהו חדשה בארץ דוקא משום דאו\"ח וחוזר לקדמותו ממש שהוא לבחי' קדם הנ\"ל אשר לא נעשו ונמשכו משם מעולם והיינו בבחי' מל' דא\"ס שלפני הצמצום ממש כמו שהוא בעצמות שנק' מלך מרומם לבדו טרם שעל' ברצונו ומחשבתו כו' והנה כמו שיש קשר וחבור בענין תחלה וסוף דקו\"ח דנעוץ תחלתן בסופן וסופן בתחלתן כך יש חיבור וקשר גם במה שלמעלה מבחי' תחלה וסוף והוא בא\"ס עצמו שאין לו תחל' ואין לו תכל' כנ\"ל מ\"מ הרי יתכן לשון למעל' ולמט' רק שלמעל' עד אין",[["1350","1","<b>חה\"ע</b>: חי העולמים."],["1351","2","<b>בשמים וארץ סובב וממלא</b>: ראה גם לקו\"ת נשא כא, ג. מאמרי אדה\"א הנחות תקע\"ז ע' שכט. קונטרסים ע' תקצג. תו\"ח ויגש רל, ד. לקמן קמו, א. לעיל לז, ב."],["1352","3","<b>קודם שנברא העולם</b>: נסמן לעיל יב, א."],["1353","4","<b>שמ\"ו גי' רצון</b>: נסמן לקמן קכב, ב."]]],[2800530119,"שיעו' ולמט' עד אין תכלי' (ונק' עמ\"ר ועמ\"ת<sup data-n=\"1354\">5</sup> בלי שיעור וגבול כלל למעלה מעמ\"ר ועמ\"ת דשמי' לרו'<sup data-n=\"1355\">6</sup> כו' שהוא רק כעיגול מוגבל כנ\"ל<sup data-n=\"1356\">7</sup> בענין כי גאה גאה כו') אלא שהוא שם המושאל ויהיה איך שיהי' יש חיבור וקש' לאא\"ס שלמעל' עד אין קץ ושיעור עם אא\"ס שיורד למטה עד אין תכלית דהיינו כמו שהוא בעצמו אין לו תחלה כו' שהכל מכח א' באו מפני היותו בלתי בע\"ג בעצם כידוע רק שכלול מב' כחות עליי' וירידה בחי' העילוי עד אין שיעור למעל' וזהו בחי' למעלה שהוא נעוץ בסופו שהוא בחי' התפשטות דא\"ס למטה עד כו' וסופו בתחילתו אע\"פ שאינם בבחי' תחלה וסוף מוגבל מ\"מ לענין קשר וחיבור זה בזה גם בהם יתכן זה החיבור מטעם א' שיש קשר וחיבור בתחלה וסוף ממש וד\"ל:\n<b>(וזהו</b> דכמו שאני ראשון ואני אחרון<sup data-n=\"1357\">8</sup> בבחי' תחל' וסוף דכתר ומל' כך אני אני הוא<sup data-n=\"1358\">9</sup> במל' דא\"ס שעולה למעלה עד אין שיעור עם בחי' מל' דאצי' במל' דמל' דעשי' שיורד למט' בלי שיעור דהכל א' וזהו כי רם ה' בעצמות שלו ממש ושפל יראה<sup data-n=\"1359\">10</sup> באין שיעור למטה דוקא משום דהא בהא תליא כמו בענין נעוץ תחל' בסוף וסוף כו' וכן מ\"ש מרום וקדו' אשכון<sup data-n=\"1360\">11</sup> כו' וכה\"ג אך באמת גם זה שאא\"ס למעלה ולמט' בלתי גבול אין זה רק בבחי' התפשטות של כח עצמותו ומהותו שהרי נקרא מלך מרומם לבדו או גאה גאה כו' וכמשל עיגול בלתי מוגבל למעלה ולמטה כו' שעכ\"פ נופל ל' עיגול אבל במהו\"ע כמו שהוא גם לשון זה לא יתכן שהרי הוא במהו\"ע ממש קדוש ומובדל מבחי' התפשטות כח עצמותו כו' וכן מאמרז\"ל שהיה הוא ושמו בלבד שמו רצון המוחלט בעצמו זהו בכלל בחי' כח התפשטו' דמהותו ועצמו' ממש ונק' הוא ושמו רק שהו' ושמו היה לבד כנ\"ל ונקרא עכ\"פ העלם וגלוי עליה וירידה רק בבלתי גבול כו'. וזהו מ\"ש השמים ושמי השמים<sup data-n=\"1361\">12</sup> לא יכלכלוך פי' השמים עיגול דכולל תחל' וסוף דקו\"ח כנ\"ל ונק' טה\"ת וגם שה\"ש טה\"ע<sup data-n=\"1362\">13</sup> מה שאין לו שיעור למעלה ולמטה גם הוא לא יכלכלוך מטעם הנ\"ל וד\"ל) וזהו הנני בורא חדשה ממש בארץ שזהו מקדם אשר לא נעשו הנ\"ל ואז נקבה תסובב גבר כו' דהנה מבואר למעלה דכח החידוש אשר בארץ דוקא בא מכח התחלה דכתר שיש שם מכחו של א\"ס לחדש חכמ' מאין ומשום דאו\"ח חוזר לקדמותו ממש אמ' יצאו מ\"ח אל הים הקדמוני זהו עלי' הב' דמל' לבחי' קדם הנ\"ל אז יהי' בריאה חדשה בארץ שלמעלה גם מכח זה החידוש שיש בארץ עכשיו מכח התחלה והיינו חדשה לגמרי כו' והוא מה שנקבה תסובב גבר כו'. ולהבין זה מהו החידוש הנפלא שיש בזה שהנקבה תסובב גבר יותר מחידוש יש מאין שיש בארץ מכבר מצד שנעוץ סופן בתחלתן כנ\"ל אך הנה יש להקדים בזה מאמרז\"ל עתידה הארץ שתוצי' גלוסקאות וכלי מילת<sup data-n=\"1363\">14</sup> כו' ולכאורה זהו פלא גדול דגם אם יהי' בארץ כח חידוש יש מאין ממש בלי אמצעי' מי גשמי' ומזל המגדל<sup data-n=\"1364\">15</sup> כו' רק מכח עצמ' לבד מטעם הנ\"ל מ\"מ איך אפשר שתוציא גלוסקאות אפויות בטעם לחם כלחם אפוי דלא יתכן רק לומר שתצמח תבואה וכל פרי בלי השקאה כמו שתוציא צמחה בעשבי' עכשיו אבל גלוסקאות וכלי מילת זהו פלא מאד כו'. (ועוד כלי מילת זה פלא גדול יותר מה ענין לארץ ללבוש שתצמיח לבוש משי דכלי מילת הוא מן המשי",[["1354","5","<b>עמ\"ר ועמ\"ת</b>: ס\"י פ\"א מ\"ה."],["1355","6","<b>דשמי' לרו'</b>: משלי כה, ג."],["1356","7","<b>כנ\"ל</b>: לעיל לה, ב ואילך."],["1357","8","<b>שאני ראשון ואני אחרון</b>: ישעי' מד, ו."],["1358","9","<b>אני אני הוא</b>: האזינו לב, לט. ראה גם לעיל מח, א."],["1359","10","<b>כי רם ה'. . ושפל יראה</b>: תהלים קלח, ו."],["1360","11","<b>מרום וקדו' אשכון</b>: ישעי' נז, טו."],["1361","12","<b>השמים ושמי השמים</b>: מלכים-א ח, כז."],["1362","13","<b>השמים. . טה\"ת. . שה\"ש טה\"ע</b>: נסמן לעיל לד, ב."],["1363","14","<b>עתידה. . וכלי מילת</b>: ראה שבת ל, ב. וראה גם שע\"ת ח\"א סו, א. תו\"ח בראשית לא, ד ובהערה 33."],["1364","15","<b>ומזל המגדל</b>: נסמן לקמן קמו, א."]]],[2800530120,"שנמשך מן התולעת החי ואיך יצמח בציור לבוש שלם ככלי מילת כו' הל\"ל כשני תולעת כך תצמח הארץ משי כו') (ואם שיהי' צומח דארץ כצומח דחי כצמר ושני תולעת שצומח מן החי כך תצמיח עפר הארץ א\"כ מהו דוקא המשי ובציור לבוש להתלבש בו מיד כמו הגלוסקא שראוי לאכילה מיד כו') (ובאמת כמ\"כ יש להבין מאמרז\"ל שאמ' עתידה אשה שתלד בכל יום<sup data-n=\"1365\">1</sup> דזה ג\"כ פלא מאד ע\"ד הנ\"ל בגלוסקאות וכלי מילת דאם מצד שלא תצטרך האשה לקבל טיפת מ\"ד דדכורא אלא תזריע מכח עצמה ותלד מטעם הנ\"ל בארץ שיש בה כח חידוש יש מאין מכח עצמה לבד אבל מהו שלא יעוכב הולד ט\"ח אלא תלד בכל יום שזה מורה השלימות בתולדה זו שאין בתולדה דעכשיו כלל כענין צמיחת כלי מילת נגמרין במלאכתן או כמו גלוסקא אפוי' בטעמה כו' בלי עיכוב תחילה בארץ כמו הזריעה עכשיו שתתעכב בארץ זמן רב עד שתצמח כו' ולזה אמר תלד בכל יום וכמו קין והבל שנולדו ביום אחד כמו שאמרו עלו למטה שנים וירדו ד'<sup data-n=\"1366\">2</sup> כו' וזה היה קודם חטא עה\"ד כו' דבאמת גם זה אינו מובן כלל דאם יהיה כדוגמתו לע\"ל לאחר הבירור דעה\"ד כמו קודם למה אמר שתלד מעצמה לבד וד\"ל):\n(לה) <b>אך</b> הנה יש להקדים לכ\"ז בענין נש\"י שעלו במחשבה תחילה כמאמר ישראל עלה במחשבה<sup data-n=\"1367\">3</sup> ומחשבה זו מה היא דהנה ידוע דכנ\"י הוא בחי' מל'<sup data-n=\"1368\">4</sup> דאצי' למעלה והוא שעלה במחשבה תחלה תחלה לחכמה שנקרא ראשית כו' והענין הוא כידוע שכל נשמה יש בה שני מדרגות בבחי' הביטול לאין האלקי הא' בבחי' כח מ\"ה חכמה<sup data-n=\"1369\">5</sup> שמאין תמצא<sup data-n=\"1370\">6</sup> ובזה נעשה הבירורים דעה\"ד טו\"ר דבחכמה אתברירו<sup data-n=\"1371\">7</sup> דוקא והוא כמו ע\"י תו\"מ ועבודה שבלב ומוח באוי\"ר שכליים וזהו שאמר יעקב אם יהיה אלקים עמדי כו' ונתן לי לחם לאכול ובגד ללבוש<sup data-n=\"1372\">8</sup> והיה ה' לי לאלקים<sup data-n=\"1373\">9</sup> פי' לחם לאכול הוא בחי' הבירורים שע\"י התורה שבחכמה אתברירו והיינו עד\"מ הלחם שצריך תיקון ובירור תחלה עד שנעש' לחם מאכל כזריעה וקציר' ואח\"כ טחינה וליש' ואפיה כסידורא דפת<sup data-n=\"1374\">10</sup> כו' וכ\"ז התיקון וההכנה מפני שמעורב טו\"ר מעה\"ד טו\"ר והיינו ל\"ט מלאכו' דבמאכל וכן בלבוש כטווה ואורג כו' עד שנעשה לבוש והן תו\"מ שנק' מזון ולבוש<sup data-n=\"1375\">11</sup> שנעשים בבחינת בירור דוקא וכ\"ז היה ביעקב י' עקב<sup data-n=\"1376\">12</sup> לברר לעקביים כידוע וזהו שאמר ונתן לי לחם לאכול כו' וכך הוא בכאו\"א מישראל בצל ימינו עלי ארץ<sup data-n=\"1377\">13</sup> שבתו\"מ ואוי\"ר דחכמה כח מ\"ה שבנפשו מברר בעה\"ד טו\"ר בבחי' ביטול היש לאין אלקי שהוא עושה מזון ולבוש לנשמתו בג\"ע וכמ\"ש במ\"א וד\"ל וז\"ש והיה הוי' לי לאלקים שזהו יחוד הוי' באלקי' דמ\"ה דהוי' מברר לב\"ן<sup data-n=\"1378\">14</sup> דאלקי' ואחר הבירור עול' בחינת ב\"ן להיות בחי' ס\"ג<sup data-n=\"1379\">15</sup> שהוא אלקי' דבינ'<sup data-n=\"1380\">16</sup> שזהו עלי' דהוי' להיות בבחינת אלקי' כידוע בענין כי ה' הוא האלקים<sup data-n=\"1381\">17</sup> כו' וכמ\"ש במ\"א וד\"ל והמדריג' הב' בנשמ' היינו בחינת הביטול עצמי מכח עצם הנפש בבחינת אין העצמי שזהו לא כמו ביטול שמצד החכמ' שנקרא ביטול דיש לאין עכ\"פ כפי' מ\"ה כו' אבל המשכות והתכללות",[["1365","1","<b>עתידה אשה. . יום</b>: שבת שם. ראה אגה\"ק סכ\"ו. תו\"ח נח נג, ג ובהערה 39."],["1366","2","<b>עלו למטה. . ד'</b>: סנהדרין לח, ב."],["1367","3","<b>ישראל עלה במחשבה</b>: נסמן לעיל לז, ב."],["1368","4","<b>דכנ\"י. . מל'</b>: ראה זהר בלק קצז, א."],["1369","5","<b>כח מ\"ה חכמה</b>: זהר (רע\"מ) צז, כח, א. לד, א."],["1370","6","<b>חכמה שמאין תמצא</b>: איוב כח, יב."],["1371","7","<b>דבחכמה אתברירו</b>: נסמן לקמן קלג, א."],["1372","8","<b>אם יהי'. . ללבוש</b>: ויצא כח, כ."],["1373","9","<b>והי' ה' לי לאלקים</b>: ויצא שם, כא."],["1374","10","<b>כסידורא דפת</b>: שבת עד, ב (עג, א)."],["1375","11","<b>תו\"מ שנק' מזון ולבוש</b>: ראה תניא פ\"ה."],["1376","12","<b>ביעקב י' עקב</b>: ע\"ח (שער סדר אצי') ש\"ג פ\"ב. ראה סה\"מ תקס\"ב ח\"א ע' קכז וע' קלא. מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח בראשית לא, ד ובהערה 39."],["1377","13","<b>בצל ימינו עלי ארץ</b>: איוב ח, ט."],["1378","14","<b>דמ\"ה. . מברר לב\"ן</b>: נסמן לקמן קלג, א."],["1379","15","<b>עול'. . ב\"ן. . ס\"ג</b>: נסמן לקמן קמא, ב."],["1380","16","<b>ס\"ג. . דבינ'</b>: נסמן לקמן קכח, ב."],["1381","17","<b>כי ה' הוא האלקים</b>: ראה מאמרי אדה\"א בראשית ע' קעג. וש\"נ. ויקרא ח\"ב ע' תתז."]]],[2800530121,"עצמיות הנפש שלמעל' מכח מ\"ה שבה ה\"ז בבחי' יחיד' שבה (כמס\"נ העצמי וכבע\"ת אמיתי כראב\"ד שיצא' נשמתו<sup data-n=\"1382\">18</sup> בבכי' וכה\"ג) זהו בחי' אין אלקי שבה העצמי וזהו למעל' מבחינת הבירורים דכח מ\"ה ואין כו'. וזה יהי' לע\"ל שיקראו כנ\"י בשם ארץ חפץ וכן חפצי בה<sup data-n=\"1383\">19</sup> מלמעל' למט' לפי שיהי' בהם הביטול דרץ לבך<sup data-n=\"1384\">20</sup> בבחי' עצמיות ממש שנבדל בערך מביטול דכח מ\"ה הנ\"ל שאין הבירורים דלחם לאכול כו' יכול להגיע שם כלל והוא למעלה מיחוד ה' אלקים שבתו\"מ ואז נאמר א\"ח עט\"ב<sup data-n=\"1385\">21</sup> וכן נקב' תסובב גבר<sup data-n=\"1386\">22</sup> לפי שכל שעכשיו עוש' פרי למעל' ע\"י עבוד' דבירורים דרפ\"ח כו' בתו\"מ ואוי\"ר כו' יהי' כ\"ז מכח כנ\"י עצמם רק מצד כח העצמי בחי' יחיד' שבנשמתם וכנ\"ל ולזה יקראו בשם ארץ חפץ שכל חפץ נמצא בה מצד עצמ' שא\"צ לעשות בארץ שום עבוד' ותיקון כלל וזהו מאמר הנ\"ל דעתידה הארץ שתוציא גלוסקאות וכלי מילת פי' גלוסקאות היינו כמו ענין לחם לאכול שנקרא מזון לנשמה ע\"י בחינת החכמ' כח מ\"ה כנ\"ל וכלי מילת הן לבושים דמצו' שנק' בגד ללבוש לנשמ' שכ\"ז עתה בא ע\"י תו\"מ ואוי\"ר כנ\"ל ולע\"ל תוציא הארץ כ\"ז מכח עצמ' שלא ע\"י עבוד' ותיקון כלל מטעם הנ\"ל וזהו שתקרא ארץ חפץ שכל חפץ העליון דתו\"מ עכשיו נמצא בה הכל מכח עצמ' לבד שלמעל' מבחי' הבירורי' דתו\"מ עכשיו כנ\"ל וד\"ל. אך עדיין אינו מובן מה שתוציא גלוסקא אפוי' דליש' ואפי' לא שייך לארץ כלל כנ\"ל. והנה מבואר למעל' בפי' חדש' בארץ שהוא למעל' מכח החידו' יש מאין שיש עכשיו בארץ כו' והוא משום דאו\"ח חוזר לקדמותו ממש לבחי' קדם הנ\"ל והוא עלי' הב' דמל' שלמעל' מעלי' הא' שע\"י הבירורים דתו\"מ שאינו עול' רק ברצון שבתחל' וסוף מעש' לבד כנ\"ל בענין כל אשר חפץ עשה כו' וזהו ענין הגלוסקאות שהוא כמו לחם שאינו נעשה בידי אדם בלישה ואפי' אלא גם טעמו כמו שהוא גדל וצומח מן הארץ כמו שגוף צמיחת החטה עכשיו תצמח מן הארץ כך תצמיח לחם בטעמו בדרך בריאה טבעי' ולא שטעמו מחודש על ידי אפייה שא\"צ לאפותו כלל וכן כלי מילת יצמח כמשי שיומשך מן התולעת כך יצמיח לבוש מילת כמו שניתקן כל צרכו בטויה ואריג' בדרך בריאה ותולדה טבעי' ואין זה פלא כל כך שכבר היה לעולמים מעין זה קודם חטא אדם הראשון בעה\"ד כו' דכתיב ויצמח ה' אלקים גן בעדן<sup data-n=\"1387\">23</sup> מקדם והי' צומח שם כל עץ כו' וטוב למאכל וכמ\"כ גם תבואת שדה יצמח שם לחם בטעמו שזה הי' מאכל ומזון לאדם ואשתו דאם לא כן במה הי' ניזון אחר שלא עבד אדמה בחרישה וקצירה ולישה ואפיה כלל עד שגורש מן הג\"ע דכתיב וישלחהו לעבוד את האדמה<sup data-n=\"1388\">24</sup> כו' (ומ\"ש לעבדה ולשמרה לא עבודת האדמה אלא ברוחניות העבודה להמשיך אור מעדן בגן מקדם הנ\"ל) ועל<sup data-n=\"1389\">26</sup> ידי בירורים דתו\"מ ארז\"ל לעבדה זו רמ\"ח<sup data-n=\"1390\">27</sup> כו' וכעובדות דאבות בבארות<sup data-n=\"1391\">28</sup> ומקלות<sup data-n=\"1392\">29</sup> כידוע ומבואר במ\"א<sup data-n=\"1393\">25</sup> ) וכן משה בהר דכתיב לחם לא אכל<sup data-n=\"1394\">30</sup> לחם שבא ע\"י בירור דל\"ט מלאכות אלא לחם עליון<sup data-n=\"1395\">31</sup> שהוא מבחי' עה\"ח שלמעלה מעה\"ד וכלחם דמן שא' הנני ממטיר לכם<sup data-n=\"1396\">32</sup> לחם מן השמים",[["1382","18","<b>כראב\"ד שיצא' נשמתו</b>: ע\"ז יז, א. ראה סה\"מ תרמ\"ו ע' יט."],["1383","19","<b>כנ\"י. . ארץ חפץ. . חפצי בה</b>: מלאכי ג, יב. ישעי' סב, ד. ראה גם שע\"ת ס, ד ואילך ובהנסמן במ\"מ לשם."],["1384","20","<b>דרץ לבך</b>: ס\"י פ\"א מ\"ח. ת\"ז בהקדמה (ז, א)."],["1385","21","<b>א\"ח עט\"ב</b>: משלי יב, ד."],["1386","22","<b>נקב' תסובב גבר</b>: ירמי' לא, כא."],["1387","23","<b>ויצמח. . גן עדן</b>: חיבור שני כתובים — בראשית ב, ט. ח."],["1388","24","<b>וישלחהו. . האדמה</b>: בראשית ג, כג [בדילוג]."],["1389","26","<b>הנ\"ל) ועל</b>: אוצ\"ל: הנ\"ל ועל־ הנ\"ל) (ועל."],["1390","27","<b>לעבדה זו רמ\"ח</b>: ראה זהר בראשית כז, א. תרומה קסה, ב. הנסמן במאמרי אדה\"א בראשית ע' עג־ קונטרסים ע' שי."],["1391","28","<b>דאבות בבארות</b>: ראה סה\"מ תקס\"ח ח\"א ע' קל ואילך. תו\"א ויקהל פט, סע\"ד ואילך."],["1392","29","<b>דאבות. . ומקלות</b>: ראה מאמרי אדה\"א שמות ח\"א ע' רנט. וש\"נ."],["1393","25","<b>לעבדה ולשמרה. . במ\"א</b>: בראשית ב, טו. ראה מאמרי אדה\"א בראשית ע' סט ואילך ובהנסמן בריש המאמר שם."],["1394","30","<b>לחם לא אכל</b>: תשא לד, כח."],["1395","31","<b>לחם עליון</b>: ראה יומא עה, ב. וראה גם סה\"מ תקס\"ה ח\"ב ע' תקצו ואילך. שם ע' תרלט. ע' תתקיח ואילך. ע' תתלא. סה\"מ תש\"א ע' 154 ובהערה לשם. לקו\"ש (בהעלותך) כרך ד ע' 1037 בשולי הגליון."],["1396","32","<b>הנני ממטיר לכם</b>: בשלח טז, ד."]]],[2800530122,"כו' וכך לע\"ל יוציא לחם כזה מן הארץ ונק' לחם פנג כמ\"ש במדרש<sup data-n=\"1397\">1</sup> וכדוגמא דלחם זה הי' בלחם הפנים שבבהמ\"ק שכולו פנים<sup data-n=\"1398\">2</sup> בחי' פנימי' ולא חיצוניו' כלל להיותו בשבת<sup data-n=\"1399\">3</sup> בבחי' לחם שיהי' ביום שכולו שבת<sup data-n=\"1400\">4</sup> לע\"ל שלמעלה מעה\"ד כו' וד\"ל (ויותר עליון מלחם הפנים והמן שנק' לחם מן השמים כי יהי' לחם הגלוסקא מן הארץ בגשמיות כלחם דעכשיו שיש בו כח עליון יותר מבחי' התחלה והוא כמו לחם פנג שעונג וטעם העצמות בא בהגשמת לחם כו') וכ\"ז מפני שיהי' עליי' הארץ שהוא בחי' המל' להיות בחי' ארץ חפץ כנ\"ל וזהו הנני בורא חדשה בארץ נקב' תסובב גבר שבחי' המל' יהי' בה כח נפלא בחידוש כמו בארץ להוציא לחם בטעמו שאין בה עכשיו כלל חידוש כזה כנ\"ל כך יהי' בבחי' חידוש התולדה דנשמות שיקראו אז נשמות חדשות לגמרי כמ\"ש בע\"ח<sup data-n=\"1401\">5</sup> והוא מעצמו' אא\"ס שנק' מקדם מקדמונו ש\"ע אשר לא נעשו כנ\"ל שעדיין לא באו למטה כלל באדה\"ר שכולל כל הנשמות<sup data-n=\"1402\">6</sup> עד ימהמ\"ש להיותם מבחי' מל' דא\"ס כמו שהוא בבחי' עליי' המל' בקדם שע\"ז אמר נקבה תסובב גבר גבר הוא בחי' א\"ק דאדם גי' מ\"ה<sup data-n=\"1403\">7</sup> אבל עליי' הנוק' תסובב בבחי' מקיף למקיף לגבר זה וע\"כ יהיו משם נשמות חדשות לגמרי כנ\"ל אע\"פ שעכשיו היא בחי' מקבל ממ\"ד דדכורא משום דאו\"ח חוזר לקדמותו ממש שלמעלה מתחלתן כו' וזהו ענין ישראל עלה במחש' לא במחש' שצופה כו' אלא בבחי' מח' ורצון שבהעלם עצמותו ממש כנ\"ל שלא בא מעולם לגלוי גם לעצמו וע\"כ תסובב גבר בבחי' מקיף דנק' סדכ\"ס דלמת\"ב אפי' מחשבה דא\"ק ולכך נק' חדשה בארץ דוקא שהוא בחי' ארץ חפץ הנ\"ל וע\"כ בריא' זו שנקבה כו' חדשה לגמרי מטעם הנ\"ל וד\"ל וזהו המשך הפסוק דמגיד מראשית אחרית היינו כשהמל' מקבל ממ\"ד שזהו החכמה שנקרא ראשית שמגיד וממשיך לאחרית כנ\"ל ואח\"כ עליי' המל' בכתר שנקרא תחלתן ועליי' הב' בבחי' קדם אשר לא נעשו שהוא במהו\"ע שנק' יחיד שלמעלה מחה\"ע כו' כנ\"ל וכל ירידה זו דמל' היה לצורך עלי' זו השנית דוקא וז\"ש אהיה אשר אהיה<sup data-n=\"1404\">8</sup> אהיה בבחי' הכתר<sup data-n=\"1405\">9</sup> דבחי' תחלתן שזהו במשיח אשר אהי' זמין לאתגלאה<sup data-n=\"1406\">10</sup> עוד כמו שהוא בעצמות ממש כמו לעוה\"ב שיאמר אלקינו זה<sup data-n=\"1407\">11</sup> וכן כתיב יקימנו ונחי' לפניו<sup data-n=\"1408\">12</sup> שזהו אחר תח\"ה דוקא וכן מ\"ש עד יעבור עמך ה' כו' שלמעל' משם הוי' דתו\"מ בגשמיו' לתו\"מ ברוחניות בימוהמ\"ש ועד יעבור הב' בעוה\"ב<sup data-n=\"1409\">13</sup> עם זו קנית ממש והוא ארץ חפץ חפצי בה וד\"ל (ולפ\"ז לא יפלא ג\"כ מארז\"ל עתידה אשה שתלד בכל יום שאינה כתולדה דעכשיו כלל כי יהי' עליי' הנוק' למעלה כ\"כ שתסובב גבר כנ\"ל וגם שיהיו גופים לנשמות בעוה\"ב<sup data-n=\"1410\">14</sup> יהיה יותר עליון מאדה\"ר ואשתו קודם החטא<sup data-n=\"1411\">15</sup> שעלו למטה ב' וירדו ד' כנ\"ל וכמ\"ש יקימנו ונחיה לפניו וע\"כ תלד אשה בכל יום בלי עיכוב כלל והיינו לפי שיהיה התולדה טבעית כמו שהיא כתולדה וגידול הגלוסקא מן הארץ כעשב כו' גם שיהיה ע\"י יחוד זו\"נ וד\"ל) וזהו שמסיים בפסוק זה<sup data-n=\"1412\">16</sup> האומר עצתי תקום<sup data-n=\"1413\">17</sup> וכל חפצי אעשה דהנה פי' עצתי היינו עצת ה' היא תקו'<sup data-n=\"1414\">18</sup>",[["1397","1","<b>לחם פנג. . במדרש</b>: ראה זהר ויחי רלה, ב. רמו, א. מאמרי אדה\"א דברים ח\"א ע' קג. וש\"נ. בראשית ע' קכד. וש\"נ. תו\"ח לך צו, ג ובהערה 24."],["1398","2","<b>בלחם הפנים. . שכולו פנים</b>: ויקהל לה, יג. פקודי לט, לו. תרומה כה, ל. ראה מנחות צו, א. מאמרי אדה\"א דברים ח\"ג ע' א'קיח. וש\"נ."],["1399","3","<b>בלחם הפנים. . בשבת</b>: ראה אמור כד, ח."],["1400","4","<b>ביום שכולו שבת</b>: תמיד בסופה."],["1401","5","<b>נשמות חדשות. . בע\"ח</b>: ראה פע\"ח (שער התפלה) ש\"א פ\"א בהגה (א) קול הרמ\"ז. הנסמן בלקו\"ת צו ז, ג. סה\"מ תקס\"ה כאן ע' רלו. לקמן קד, ב."],["1402","6","<b>באדה\"ר שכולל כל הנשמות</b>: ראה אגה\"ק ס\"ז. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקצא. מאמרי אדה\"א דברים ח\"ג ע' תתיא. ח\"ד ע' א'שצה ובהנסמן בהנ\"ל."],["1403","7","<b>דאדם גי' מ\"ה</b>: ראה ע\"ח (שער התיקון) ש\"י פ\"ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן לשם. תו\"ח בראשית ט, א בהערה 14."],["1404","8","<b>אהי' אשר אהי'</b>: שמות ג, יד."],["1405","9","<b>אהי' בבחי' הכתר</b>: זהר ויקרא יא, א. ראה מאמרי אדה\"א דברים ח\"א ע' רכו. וש\"נ."],["1406","10","<b>אהי' זמין לאתגלאה</b>: ראה זהר שם. אחרי סה, ב."],["1407","11","<b>אלקינו זה</b>: ישעי' כה, ט."],["1408","12","<b>יקימנו ונחי' לפניו</b>: הושע ו, ב."],["1409","13","<b>עד יעבור. . בימוהמ\"ש. . בעוה\"ב</b>: בשלח טו, טז. ראה גם מאמרי אדה\"א שמות ח\"א ע' סא. וש\"נ."],["1410","14","<b>גופים לנשמות בעוה\"ב</b>: ראה שער הגמול להרמב\"ן [כתבי הרמב\"ן ח\"ב ע' שט]. מאמרי אדה\"א הנחות תקע\"ז ע' קכה. וש\"נ."],["1411","15","<b>בעוה\"ב. . עליון. . קודם החטא</b>: ראה גם שע\"ת ח, א. תו\"ח בראשית לב, ג. ויחי רלז, ג."],["1412","16","<b>בפסוק זה</b>: מגיד מראשית."],["1413","17","<b>האומר עצתי תקום</b>: ישעי' מו, י [ושם: אומר — ראה אוה\"ת (יהל אור) תהלים ע' תרכג]."],["1414","18","<b>עצת ה' היא תקו'</b>: משלי יט, כא [ושם: ועצת]."]]],[2800530123,"שהוא בחי' הבירורים דרפ\"ח כו' שע\"י תו\"מ שהתורה נקרא עצת ה'<sup data-n=\"1415\">19</sup> כידוע והיא תקום לע\"ל שזה גורם מה שכל חפצי אעשה כו' דהנה ירידה זו דבחי' המל' בכנ\"י עצת ה' היא שיהיה הבירור ע\"י בחי' מ\"ד דתו\"מ בעוה\"ז לצורך עלי' שיעלו במח' הקדומה שבבחי' קדם הנ\"ל שהוא עלי' הב' דלע\"ל משום דהא בהא תליא דלפי שבזמן הגלות היתה בחי' מקבל מדכורא בבחי' רצוא שע\"י החכמה כח מ\"ה כמו ואל אישך תשוקתך<sup data-n=\"1416\">20</sup> כו' וכמו למה נקרא שמה ארץ<sup data-n=\"1417\">21</sup> שרצתה לעשות רצון קונה הרי היה רצון ותשוקה דכנ\"י שנקרא ארץ רק לעשות רצון קונה שבתו\"מ דוקא בהעלאת מ\"ן דאל אישך תשוקתך מזה דוק' נעשה לע\"ל בחי' ארץ חפץ או חפצי בה שזהו מבחי' קדם הנ\"ל דאו\"ח חוזר לקדמותו ממש כנ\"ל וזהו כל חפצי אעשה פי' כל חפצי שלא הי' בא מהעלם עצמות לגלוי עדיין באבי\"ע וכנ\"ל בפי' אשר לא נעשו כו' זהו כל חפצי הפנימי' והעצמי' כו' עד שלא נשאר בהעלם מה שלא הביא לגלוי אין זה רק ע\"י עצתי דוקא בירידה זו לצורך עליה הב' והיינו עצת ה' שבתו\"מ עכשיו שהיא דוקא תקום גם לעתיד לבא להיות כל חפצי אעשה מה שלא נעשו בכל אשר חפץ ה' שעשה בשמים וארץ כו' והיינו ג\"כ ענין מה שבגלות נא' והוא ימשל בך<sup data-n=\"1418\">22</sup> דמ\"ה מברר לב\"ן והוא עצמו הגורם דוקא שיהי' לע\"ל א\"ח עט\"ב ונקבה תסובב גבר ע\"ד הנ\"ל משום דהא בהא תליא מטעם הנ\"ל וד\"ל:\n(לו) <b>ולהבין</b> שרש כל הדברים הנ\"ל הנה שרש ענין מגיד מראשית אחרית הנ\"ל יובן בתוס' ביאור כפי פשוטו שמגיד מראשית מה שיהי' באחרית משו' דראשית ואחרי' שוין לפניו ונסקרי' בסקירה א' ממש כמו צופה ומביט בסקירה א'<sup data-n=\"1419\">23</sup> עד סוף כל הדורות במחשב' א' לפי ששם הוי\"ה היינו היה הוה ויהיה כא'<sup data-n=\"1420\">24</sup> ממש שעבר והוה ועתיד נכללים כאחד וא\"כ הרי מה שהיה בראשית ומה שיהיה בסוף נכלל כא' וד\"ל ויובן זה עפ\"י הידוע שו' אלפי שני<sup data-n=\"1421\">25</sup> דהו' עלמ' היינו מוימ\"ב יום א' יהי אור אלף שני' ראשוני' של חסד<sup data-n=\"1422\">26</sup> ויום ב' יהי רקיע אלף הב' של דין<sup data-n=\"1423\">27</sup> כו' עד יום הו' וכמ\"ש כי אלף שנה<sup data-n=\"1424\">28</sup> כיום כו' והיינו מו\"ק העליונים ו' מדות דאצי' שמאירים בוימ\"ב וכל מדה כלולה מכל המדות כמו החסד כלול מגבורה ונצח והוד כו' וכן הגבור' כלול מחסד ונצח כו' וכך כל מדה כלולה מכל המדות וע\"כ יש בחי' התכללו' בו' אלפי שנה שכ\"א כלול מכל המדריגות וכ\"ז מפני שבחי' הע\"ס דאצי' מתחלקי' כ\"א לרבבות מדריגות דכל ספי' נחלק לי' וי' לי'<sup data-n=\"1425\">29</sup> וכך המדה זולתה מתחלק לי' וי' לי' ע\"כ ימצא בהן ריבוי ההתכללות בכמה אופנים שונים לאלפים רבבות מדריגות ומחמת זה אור ושפע שנמשך מאצי' לבי\"ע בזמן ומקום יש בהן רבבות מדריגות בכ\"א כמו מחנה מיכאל שמקבלים מבחי' החסד דאצי' מתחלק לק\"פ אלפים<sup data-n=\"1426\">30</sup> כו' וכן מחנה גבריאל כו' וכך בזמן דאלף שנה של חסד מתחלק לכמה זמנים שונים כלולים מכל כו' עד אין שיעור לאופני המדריגות דמלאכים דבי\"ע עד שגם בשפע דצח\"מ דעשי' שהוא היותר אחרון בהשתלשלו' ימצא ריבוי אופני מיני ברואים שונים לאין שיעור עד שאין זה דומה לזה כלל גם במין א' כמו",[["1415","19","<b>שהתורה נקרא עצת ה'</b>: ראה ספרי האזינו לב, כח. שהש\"ר פ\"ח, ה. תו\"ח ח\"ש קלג, סע\"ג."],["1416","20","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["1417","21","<b>למה נקרא שמה ארץ</b>: נסמן לעיל נד, א."],["1418","22","<b>והוא ימשל בך</b>: בראשית שם."],["1419","23","<b>צופה ומביט בסקירה א'</b>: נסמן לקמן קנא, ב."],["1420","24","<b>ששם הוי\"ה. . כא'</b>: נסמן לעיל א, א."],["1421","25","<b>שו' אלפי שני</b>: ראה ר\"ה לא, א. הנסמן במאמרי אדה\"א בראשית ע' נג."],["1422","26","<b>יהי אור. . חסד</b>: נסמן לקמן קמד, א."],["1423","27","<b>אלף שני'. . חסד. . דין</b>: נסמן שם."],["1424","28","<b>כי אלף שנה</b>: נסמן לקמן שם."],["1425","29","<b>דכל ספי' נחלק. . לי'</b>: ראה ע\"ח (שער פרקי הצלם) שכ\"ד פ\"א."],["1426","30","<b>מחנה מיכאל. . לק\"פ אלפים</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' רכד. וש\"נ. הנחות תקע\"ז ע' לד. וש\"נ."]]],[2800530124,"צומח דעשבים יש בהן עשבים מרים ומתוקים ממיתי' ומחיי' כו' שהוא מורה על בחי' חו\"ג לפי שרש שרשן במזלות שחלוקי' לחו\"ג בכמה אופנים שונים מצד ריבוי ההתכללו' כו' וכן בדומם אבנים מיסוד המים<sup data-n=\"1427\">1</sup> דחסד יש בהן ריבוי אופנים ומתכת מיסוד האש<sup data-n=\"1428\">2</sup> בריבוי אופנים שכ\"א כלול מהיפוכו שיש באבנים מיסוד האש ובמתכת מיסוד המים לפי שרבו מיני המזיגות וההתכללות בשרשם העליון עד רום המעלות שהוא כמו בחו\"ג דאצי' שא' טרף אש ומים<sup data-n=\"1429\">3</sup> ובללן יחד כו' כידוע וד\"ל (וזהו שאמר בס\"י ה' אבנים<sup data-n=\"1430\">4</sup> בונות ק\"ך בתים היינו ה' אותיות בונים ק\"ך צירופים וכל צירוף מתחלק לרבוא רבבות כו' ע\"כ א' מכאן ואילך צא וחשוב<sup data-n=\"1431\">5</sup> עד אין שיעור כו' והכל ענין אחד עם הנ\"ל בע\"ס שהן י\"מ<sup data-n=\"1432\">6</sup> כידוע) והנה נמצא מובן מזה עכ\"פ שכל מה שאנו מוצאים ריבוי שינויי האופנים בנבראים כל אחד למינהו הכל הוא מחמת שרש שרשן הראשון שהן ע\"ס דאצי' שמתחלקים ומתכללים בריבוי אופנים לאין שיעור כנ\"ל ואמנם כפי מספר הע\"ס ואופן ריבוי התכללותם כך ימצא במציאות הנבראים כמו כמה אופנים של מציאות נבראים שהן בבחי' החסד או של בחי' דין וכה\"ג אבל אם היה מספר הע\"ס יותר מזה המספר דעשר ודאי היה נמצא בהתהוות נבראים במהות ומציאות אופנים אחרים לגמרי מה שלא יש במציאות עכשיו כלל כמו אם היו הע\"ס י\"א היה נמצא מציאות נברא שאינו לא בחינת חסד או דין ולא במהות שכל וכה\"ג לא בבחי' דצח\"מ כלל מאחר שאינו בא מכח ע\"ס דחב\"ד חג\"ת כו' כלל וכן גם בע\"ס שנאצלו אם היו פחות מע\"ס היה חסר מציאות שנמצא עכשיו כו' וזהו שאמר בס\"י ע\"ס עשר ולא תשע עשר ולא י\"א<sup data-n=\"1433\">7</sup> כו' לפי שנאצלו במספר ונשקלו במשקל ומדה ע\"פ מאמר קו המדה באו\"כ באופנים שונים וגם באופן התכללותם זה עם זה כנ\"ל אשר ע\"כ ימצא כדוגמת זה למטה במציאת הנבראים עד דצח\"מ בלי שינוי כלל כנ\"ל וד\"ל וזהו מה רבו מעשיך<sup data-n=\"1434\">8</sup> ה' כולם בחכמה עשית פי' מה רבו בחי' ההתחלקות מיני אופנים שונים לאין שיעור בנבראים ובדצח\"מ עד המלאכים ועולמות העליונים וכ\"ז מצד רבוי התחלקות בשרש שרשם ומקורם שבאצי' כנ\"ל אך הנה כולם בחכמה עשית פי' מפני שכולם כלולים בחכמ' למעלה ע\"כ כולם בחכמה נעשו ונתהוו למטה והענין הוא כידוע דהחכמה נקרא ראשית<sup data-n=\"1435\">9</sup> לפי שבבחי' הגלוי אור מן המאציל הרי אור החכמה נאצל ראשון ומפני שהוא ראשית שפע אור הנמשך מאין האמיתי וכמ\"ש והחכמה מאין<sup data-n=\"1436\">10</sup> כו' ע\"כ היא הכוללת כל ההשתלשלות דע\"ס דאצי' באו\"כ וכל מיני אופני התכללותם זע\"ז כנ\"ל הכל כלולים בחכמה וע\"כ גם למטה כולם בחכמה עשית וד\"ל וזהו בראשית ברא בחוכמתא<sup data-n=\"1437\">11</sup> כו' ברא הכל שמים וארץ וכל צבאם יחד כולם כלולים בו (עד\"מ חכמה אחת שבדבור שכולל כל רבוי רבבות הצרופים שמתחלקים ויוצאים בי' מאמרות עד אין שיעור כנ\"ל) ואמנם הנה אמרו דבראשית נמי מאמר הוא<sup data-n=\"1438\">12</sup> פירוש דגם שהחכמה נקרא ראשית לכל ההשתלשלות דע\"מ וכוללם יחד כנ\"ל מ\"מ גם החכמ' נתהוו' יש מאין כמ\"ש והחכמ' מאין תמצא והוא בחינת מאמר דבראשית ולא עוד אלא שהתהוות",[["1427","1","<b>אבנים מיסוד המים</b>: ראה ביאוה\"ז ויצא יח, ד. סה\"מ תקס\"ז ע' קסח. מאמרי אדה\"א ויקרא ח\"א ע' כו. ח\"ב ע' תרמד. הנחות תקע\"ז ע' לד וע' שמז. דברים ח\"ג ע' א'קיא. וראה סה\"מ קונטרסים ח\"ב ע' תלו."],["1428","2","<b>ומתכת מיסוד האש</b>: ראה סה\"מ תקס\"ז ומאמרי אדה\"א ויקרא ח\"ב־ הנחות תקע\"ז־ דברים ח\"ג בהערה שלפנ\"ז."],["1429","3","<b>טרף אש ומים</b>: נסמן לקמן קכד, ב."],["1430","4","<b>בס\"י ה' אבנים</b>: פ\"ד מי\"ב [הלשון שמובא בפנים הוא במהדורת מנטובא שכ\"ב — צילום ירושלים תשכ\"ב — פ\"ד מ\"ד]."],["1431","5","<b>מכאן ואילך צא וחשוב</b>: ראה ס\"י שם."],["1432","6","<b>בע\"ס שהן י\"מ</b>: ראה לקו\"ת מטות פב, רע\"ג. וש\"נ. סה\"מ תקס\"ה כאן ע' רכו. לקמן קב, ב."],["1433","7","<b>בס\"י ע\"ס עשר. . ולא י\"א</b>: ראה שם פ\"א מ\"ד."],["1434","8","<b>מה רבו מעשיך</b>: תהלים קד, כד."],["1435","9","<b>דהחכמה נקרא ראשית</b>: ראה רקאנטי ר\"פ בראשית. מאמרי אדה\"א בראשית ע' א. וש\"נ. לעיל נה, ב."],["1436","10","<b>והחכמה מאין</b>: איוב כח, יב."],["1437","11","<b>בראשית ברא בחוכמתא</b>: ראה תרגום ירושלמי לבראשית א, א."],["1438","12","<b>דבראשית נמי מאמר הוא</b>: ר\"ה לב, א."]]],[2800530125,"החכמה מאין בא בדילוג הערך מאין המוחלט ליש משא\"כ בשאר מאמרים שמסתעפים מן החכמה הכל הוא בבחי' יש מיש שנקרא עו\"ע כנ\"ל באריכות כמו משכל למדות וממדות למו\"ד כו' אך הנה יש להבין בזה דלכאורה מצינו מפור' דהחכמה שרשה היא מקדם ונק' חכמה הקדומה<sup data-n=\"1439\">13</sup> דהיינו שהיא כלול' במהו\"ע המאציל שנקרא חכים ולא בחכמה ידיעא<sup data-n=\"1440\">14</sup> כו' שהרי נאמר ונהר יוצא מעדן<sup data-n=\"1441\">15</sup> ועדן זה הוא מקדם הנ\"ל כמ\"ש ויטע גן בעדן מקדם<sup data-n=\"1442\">16</sup> וידוע שהעדן הוא בחינת הח\"ע<sup data-n=\"1443\">17</sup> שנאמר בו עין לא ראתה<sup data-n=\"1444\">18</sup> כו' שעדיין לא בא מן ההעלם לגלוי כלל והוא העוה\"ב שנברא בי' דחכמה<sup data-n=\"1445\">19</sup> דוקא כידוע ואיך אמר כאן במע\"ב דבראשית נמי מאמר הוא שנתהווה החכמה מאין ליש כנ\"ל (ועוד ראיה מח\"ע דאורייתא נפקת<sup data-n=\"1446\">20</sup> מיניה דהתור' קדמ' לעולם<sup data-n=\"1447\">21</sup> כמ\"ש ואהיה אצלו אמון<sup data-n=\"1448\">22</sup> כו' ונקרא משל הקדמוני<sup data-n=\"1449\">23</sup> וכן ח\"ע נקרא ים הקדמוני<sup data-n=\"1450\">24</sup> דוקא כידוע) והנ' יש להקדים לזה ענין א' והוא שהעדן נקרא עונג באמת ויש בו ב' מדריגות א' עונג הנעלם ונקרא עדן עילאה סתימאה<sup data-n=\"1451\">25</sup> והב' ענג הנרגש הבא בגלוי מן ההעלם בג\"ע ועל עדן עילא' הנעלם אמר עין לא ראת' כו' כמו שהוא כי הוא סתום ונעלם בבחי' סדכ\"ס דלמת\"ב כלל רק בעוה\"ב יתגלה והוא הנקרא שעשועי המלך בעצמותו<sup data-n=\"1452\">26</sup> ממש כידוע ועדן שבגן שנטעו ה' לגן בעדן שיבא בו גלוי אור עדן עילא' אפס קצהו רק מדי חדש ושבת לבד לנשמות בג\"ע העליון וג\"ע התחתון ומשם נמשך ויורד בהשתלשלות עו\"ע עד המלאכים דבי\"ע וכל צבא השמים שאומרים שירה<sup data-n=\"1453\">27</sup> שהשיר הזה הוא בחינת הענג האלקי הבא בירידת המדריגה כ\"כ ברבוי צמצומים עד שיש לכל מלאך ענג אלקי בשיר שלו וזהו עיקר ומקור חיותו<sup data-n=\"1454\">28</sup> וקיום מציאותו מאין כו' אבל העדן עצמו עין לא ראתה עדיין גם בג\"ע ולמעל' מעל' עד רום המעלות ולהיותו בשרשו בקדם קדמונו ש\"ע שנקרא שעשועים העצמיי' כנ\"ל שנקרא מקור כל התענוגים עליונים ועונג שבחו\"ב ומדות ומחו\"ד הכל רק מבחינת ירידת העונג הבא במורגש ובגלוי אפס קצהו לבד (וכידוע שזהו ההפר' בין עתיקא קדישא עונג שבחכמה המורג' לבין עתיקא סתימא'<sup data-n=\"1455\">29</sup> שזה עת\"ס מסוף עולם הא\"ס וע\"ק בחי' מקור לחכמה ומדות כו' והן רק ז\"ת דע\"י שמלוב' בנאצלים שע\"ז אמר וקראת לשבת עונג<sup data-n=\"1456\">30</sup> וכה\"ג):\n(לז) <b>ויובן</b> זה בנפש האדם שכלול מנרנח\"י<sup data-n=\"1457\">31</sup> כידוע הרי יש בנפש ב' מדריגות בעונג אחד בעונג שהנפ' נמשך בו בבחי' גלוי אור וחיות עכ\"פ כמו בהמשכת הנפש באיזה רצון לדבר מה אז נגלה בזה עונג פרטי ששייך לאותו רצון לפי מה שהוא בענין גדול או קטן או בדבר והיפוכו בחסד או דין או תפארת וניצוח וכה\"ג וכן בשכל בא העונג בגלוי לפי אופן השכל וצמצומו לבד וכן בפרטי חלקיהם בחו\"ג שבחכמ' כו' עד שיורד העונג ומתלבש גם במח' כל דהו יהי' מה שיהי' וכן בדבור בדרך פרט אם בדברי אהב' או שנא' או דברי התפארות ונצוח כו' וכן עד בחינת המעשה שמתענג בפועל ידיו דוקא בדרך פרטי פרטיות שבו וכמ\"כ במע\"ב דכתיב וירא אלקים<sup data-n=\"1458\">32</sup> את כל אשר עשה בפו\"מ והנה טוב מאד טוב זה הוא בחי'",[["1439","13","<b>חכמה הקדומה</b>: ת\"ז תס\"ט (קטז, ב)."],["1440","14","<b>חכים ולא בחכמה ידיעא</b>: ז\"ח יתרו לד, ד. ת\"ז בהקדמה (יז, ב)."],["1441","15","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["1442","16","<b>ויטע גן עדן מקדם</b>: בראשית שם, ח [בדילוג]."],["1443","17","<b>שהעדן. . הח\"ע</b>: ראה גם עט\"ר ע' נט. מאמרי אדה\"א דרושי חתונה ח\"א ע' טז. וראה גם לקמן צ, א ובהנסמן במ\"מ לשם."],["1444","18","<b>שהעדן. . עין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג. ראה גם לקמן פח, ב."],["1445","19","<b>העוה\"ב שנברא בי' דחכמה</b>: מנחות כט, ב ראה גם מאמרי אדה\"א בראשית ע' קנב. וש\"נ. שמות ח\"ב ע' תנו."],["1446","20","<b>מח\"ע דאורייתא נפקת</b>: נסמן לעיל כג, א."],["1447","21","<b>דהתורה קדמ' לעולם</b>: פסחים נד, א."],["1448","22","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["1449","23","<b>דהתו'. . משל הקדמוני</b>: שמואל-א כד, יג וברש\"י שם. ראה מאמרי אדה\"א דברים ח\"ב ע' תב. וש\"נ. שמות ח\"ב ע' שפג. וש\"נ."],["1450","24","<b>ח\"ע נק' ים הקדמוני</b>: ראה גם שע\"ת ח\"א כג, ג. תו\"ח מקץ ריג, א ובהערה 17."],["1451","25","<b>עדן עילאה סתימאה</b>: ראה גם לקמן פט, א. צה, ב. מאמרי אדה\"א ויקרא ח\"א ע' מד. וש\"נ. תו\"ח נח עח, ד ובהערה 30."],["1452","26","<b>שעשועי המלך בעצמותו</b>: נסמן לעיל לו, א."],["1453","27","<b>צבא השמים שאומרים שירה</b>: ראה סידור שער המילה קמב, ג. סה\"מ תקס\"ה (כאן) ע' רל. מאמרי אדה\"א בראשית ע' נז. וש\"נ."],["1454","28","<b>בשיר. . עיקר ומקור חיותו</b>: ראה טעמי המצות להרח\"ו פ' ואתחנן. סה\"מ תקס\"ה שם."],["1455","29","<b>ההפר' בין עתיקא קדישא. . סתימא'</b>: ראה זהר בשלח נב, ב. יתרו פח, א-ב. פט, א-ב. ועוד. בשלח סג, ב. סד, ב. ועוד. וראה גם לעיל כט, ב. תו\"ח לך פא, ב."],["1456","30","<b>וקראת לשבת עונג</b>: ישעי' נח, יג."],["1457","31","<b>מנרנח\"י</b>: נסמן לעיל ט, ב."],["1458","32","<b>וירא אלקים</b>: בראשית א, לא."]]],[2800530126,"אור העונג האלקי העליון כאדם שמתענג בפעלו הטוב וידוע שבחי' עונג זה שנמשך בכל פרט מן המדות וכחות הוא עיקר קיומו וחיותו הנצחי כמו גם בהילוך ברגל ועבודה קשה בחומר ולבנים אם מתענג בזה זהו חיותו וקיומו וכ\"ש ברוחניות דשכל ומדות ומדו\"מ שבלתי העונג המלובש בזה היה נפסק אור מציאותם ונמצא מובן מזה למעל' דבחי' העונג העליון שבא בגלוי מן ההעלם מתגלה תחלה בחכמה שנקרא ראשי' לכל השתלשלות דאבי\"ע כנ\"ל ומשם יורד ומשתלשל עונג זה בכל פרט ופרט שבהתחלקות ע\"ס דאצי' באו\"כ וכל פרטי התכללותם זב\"ז כנ\"ל כמו בחסד שבגבור' עם גבור' שבחסד יש עונג פרטי שהוא חיותו וקיומו ע\"ד הנ\"ל באדם ולפי זה יובן שבחינת עונג העליון יורד ונמשך בכל פרטי ההשתלשלות עולמות שמקבלים מאו\"כ דאצי' בכל פרט ופרט שבמציאות הנבראי' בכל ג' העולמות בכל מלאך ומלאך בפרט עד גם בדצח\"מ דעשיה שלנו שגם בהם מאיר מבחינת עונג העליון הנזכר למעלה רק שבא אחר רוב הצמצומים מאד בדרך ירידת המדריגה בעו\"ע במלאכים עד המזלות שמשפיעים הרוחניות דדצח\"מ כו' וזהו שאמ' שגם הדצ\"ח אומ' שירה כמו שהשמים אומ' שירה<sup data-n=\"1459\">1</sup> כמ\"ש השמים מספרים כבוד אל<sup data-n=\"1460\">2</sup> כו' כמו חטה מה אומרת<sup data-n=\"1461\">3</sup> כו' פיל מה הוא אומ'<sup data-n=\"1462\">4</sup> כו' ופי' השמים אומרי' לשון הוה שאומ' תמיד בלי הפסק כלל לפי שאם יופסק יופסק אור חיות' ומציאו' התהוותה מאין ליש כו' (וראיה משמש בגבעון דום<sup data-n=\"1463\">5</sup> כידוע) לפי שהשיר הזה הוא עיקר חיות הנברא כנ\"ל כי מקור כל החיים העליונים והתחתונים נמשך רק מעולם התענוג העליון כמ\"ש כי עמך מקור חיים<sup data-n=\"1464\">6</sup> פי' מקור כל התענוגים כידוע ולפי שמתחלק בכל מלאך ובכל נברא בכל חד לפום שיעורא דילי' לכך זה אומר שירה כך וזה כך כו' וזהו בעלי השיר יוצאין<sup data-n=\"1465\">7</sup> כו' כידוע וד\"ל (וראי' לזה הוא מה שאנו רואי' שאין עליי' כל עילה לגבי העליון הימנו רק ע\"י השיר דוקא כמו בג\"ע שעולין הנשמו' בשיר<sup data-n=\"1466\">8</sup> וכן המלאכים עלייתן דוקא בשיר וכמו השיר ע\"ג הקרבן<sup data-n=\"1467\">9</sup> שעיק' עליית הקרבן ע\"י השיר) והנה לפ\"ז הרי מובן דחכמה דאצי' גם היא נק' עדן מטעם זה שהרי החכמה היא ראשית ומקור לכל ההשתלשלות המסתעפים אח\"כ ויורדת ונמשכת בכל פרט ופרט ג\"כ כמ\"ש כולם בחכמה עשית לפי שכוללת הכל ע\"כ נמשכת בכל נברא בפרט (כמו אל אדון<sup data-n=\"1468\">10</sup> על כל המעשים ואפי' בדומם כמו ושמן מחלמיש צור<sup data-n=\"1469\">11</sup> כמ\"ש במ\"א) מריש כל דרגין עד סוף כל כו' והיינו לפי שבחי' העונג העליון שבעצמות המאציל ראשית הגלוי שלו הוא בחכמה דוקא להיותה בחי' ראשית הגלוי כנ\"ל וע\"כ נק' החכמ' עדן כנ\"ל והוא עונג המורגש ובא בגלוי בחכמ' ויורד ומתצמצם מחכמ' ולמטה עד סוף כל ההשתלשלות דאבי\"ע עד דצ\"ח דעשי' כנ\"ל אך הנה כ\"ז הוא בבחי' עונג שבחכמה ולמטה אבל למעלה מבחי' החכמ' הוא הנק' עדן עילא' סתימא' שאינו בא בדרך ירידה למטה כלל וכלל ונק' ענג הנעלם בעצמות המאציל כנ\"ל ושם גם בחי' החכמ' נק' עדן כי גם החכמ' שם בבחי' העלם העצמות ונק' חכמ' הקדומ' כמו אנת חכים<sup data-n=\"1470\">12</sup> ולא בחכ' ידיעא (כח\"ע דתורה דקדמ' לעולם הנאצל ונק' משל הקדמוני",[["1459","1","<b>שהשמים אומ' שירה</b>: פרק שירה."],["1460","2","<b>השמים מספרים כבוד אל</b>: תהלים יט, ב."],["1461","3","<b>חטה מה אומרת</b>: ועד\"ז בסה\"מ תקס\"ה כאן (ע' רל). ובפרק שירה: שבלת חטים אומרת."],["1462","4","<b>פיל מהו אומ'</b>: בפרק שירה: פיל אומר."],["1463","5","<b>משמש בגבעון דום</b>: יהושע י, יב. וברש\"י שם ובע\"ז כה, א (ד\"ה וידום הב')."],["1464","6","<b>כי עמך מקור חיים</b>: נסמן לקמן קכז, א."],["1465","7","<b>בעלי השיר יוצאין</b>: ראה שבת נא, ב. סה\"מ תקס\"ה כאן ע' רל."],["1466","8","<b>שעולין הנשמו' בשיר</b>: ראה סידור שער החנוכה ערה, ד. לקו\"ת ברכה צח, א [ובהנסמן במ\"מ לשם]. סה\"מ תקס\"ח ח\"א ע' תקנג. שע\"ת ח\"ב טו, א. תו\"ח בראשית לג, סע\"ד. מאמרי אדה\"א קונטרסים ע' סו. סה\"מ מלוקט ח\"ו ע' צה בהערה."],["1467","9","<b>השיר ע\"ג קרבן</b>: ראה ר\"ה ל, ב ואילך. ערכין יא, א. סה\"מ תקס\"ח שם ע' תקנד. תו\"א בראשית ז, ג. תו\"ח בראשית ג, ג. לה, ד. סה\"מ מלוקט שם. וראה גם מאמרי אדה\"א הנחות תקע\"ז ע' ל."],["1468","10","<b>אל אדון</b>: נוסח ברכת יוצר דשבת. ראה שע\"ת קכג, א ובהנסמן במ\"מ לשם."],["1469","11","<b>ושמן מחלמיש צור</b>: האזינו לב, יג. ראה מאמרי אדה\"א בראשית ע' רנב. וש\"נ."],["1470","12","<b>אנת חכים</b>: ת\"ז בהקדמה (יז, ב)."]]],[2800530127,"כנ\"ל) ומתורץ הקושי' דלעיל דלפעמים החכמ' בבחי' גלוי יש מאין והוא כמו מא' דבראשית כנ\"ל ושם גם הענג בא בגלוי בחכמ' כנ\"ל ולפעמי' החכ' בהעלם העצמות שהוא בפנימי' התענוג העליון (וכמ\"ש בע\"ח דפנימית אבא הוא פנימי' ע\"י<sup data-n=\"1471\">13</sup> ) ושניהם אמת ולק\"מ וד\"ל והנה ע\"ד הנ\"ל יובן בנש\"י שעלה במחשבה כנ\"ל שיש בזה ב' מדרגות בבחי' העונג א' בשרשם למעלה מעלה במחשבה ותענוג הנעלם שבעצמות ממש והב' מה שירדו בשפלות המדריג' עד נשמות דעשיה בגופי' שיש בכל א' לפום שיעורא דיליה ענג האלקי בעבוד' שבלב ומוח ובשמח' של מצוה גשמי' ובפרט בשבת וי\"ט שעולין כל הנשמות כנ\"ל וגם נשמות שבגופים שנאמר אז תתענג על ה'<sup data-n=\"1472\">14</sup> כו' וידוע דג' קשרין הן<sup data-n=\"1473\">15</sup> ישראל מתקשראן באורייתא ואורייתא בקוב\"ה דגם בתורה יש ב' מדריגות בעונג א' בבחי' שעשועים העצמיי' דא\"ס ב\"ה כמ\"ש בתורה ואהי' אצלו אמון שעשועי' יום יום<sup data-n=\"1474\">16</sup> כו' וכתיב ושעשועי את בנ\"א<sup data-n=\"1475\">17</sup> וכן משחקת לפניו<sup data-n=\"1476\">18</sup> כו' משחקת בתבל ארצו<sup data-n=\"1477\">19</sup> וכידוע בבחי' טנת\"א טעמים בתענוג<sup data-n=\"1478\">20</sup> הנעלם ומה שירד העונג שבחכמ' שבתורה בעונג ברזין דאורייתא לנשמות בג\"ע וכה\"ג וד\"ל (וכמ\"כ בח\"ע דתורה יש ב'<sup data-n=\"1479\">21</sup> מדריגות חכמ' הקדומ' שנק' ים הקדמוני משל הקדמוני כנ\"ל וחכמ' שברזין דאורייתא דאורייתא סתים וגליא בבחי' עונג וחכמ' וכמ\"כ קוב\"ה סתים וגליא בב' אלה כו' וד\"ל) (וכמ\"כ בחכמ' כח מ\"ה שבנשמו' יש ב' מדריגות סתים וגליא א' במח' וחכמ' הקדומ' שבעצמות כמ\"ש כי אתה אבינו<sup data-n=\"1480\">22</sup> אתה ממש והב' בירידת גלוי אור החכמ' בחי' כח מ\"ה שבכאו\"א עד בחי' נפש דעשי' כו') ובכ\"ז יובן מ\"ש מגיד מראשית אחרית בב' אופנים הא' בבחי' ממכ\"ע והב' בבחי' סובב כ\"ע שנק' או\"פ ואו\"מ והוא לפי הנ\"ל בירידת העונג והחכמ' מעדן עילא' מרא' לסוף הכל בכל עו\"ע בדרך פרט עד דצ\"ח דעשי' זהו בבחי' ממכ\"ע הנק' או\"פ שנמשך בקו\"ח בע\"ס דאבי\"ע והב' בבחי' סוכ\"ע שהרא' וסוף שוין ממש כמשל העגול שסובב מעלה ומטה כא' היינו במדריגה הב' דעונג העליון וחכמה עילא' שבמוה\"ע<sup data-n=\"1481\">23</sup> שההאר' משם סובב את הכל כא' מבלי חילוק בין ראש לסוף הכל והיינו ב' האופני' דמגיד מראשית אחרית א' שנמשך מראשית שהוא החכמה וענג שבחכמ' בראש דאצי' ע\"ס העשיה במל' דמל' דעשיה שנקרא אחרית והב' שמגיד מראשית מה שיהיה באחרית דראשית ואחרית שוין ממש ונסקרין בסקירה אח' כנ\"ל בפי' היה הוה ויהיה כאחד וד\"ל ודרך כלל היינו מ\"ש אני ראשון ואני אחרון<sup data-n=\"1482\">24</sup> כו' דכמו שבמל' דאצילות סופא דכולא הוא מהוה מאין ליש עד שאין ערך לנברא עם הבורא דאין ערוך לבע\"ג לבלתי בע\"ג כלל כידוע כך ממש אין ערוך באני ראשון שהוא בחי' החכמה בראש בנאצלים לגבי עצמות המאציל מאחר שגם החכמה מאין ליש תמצא כנ\"ל דבראשית נמי מאמר הוא וא\"כ הראשית והאחרית שניהם שוין לפני עצמותו וד\"ל אך הנה עדיין יש להבין בכ\"ז דא\"כ הי' בחי' אחרית ראוי להיות שוה עם הראשית לבד משום דקמיה שוין אבל למה דוקא באחרית בחי' המל' יש בה כח המחדש יש מאין ממש כמו בעצמות המאציל ממש שמאציל את החכמה מאין ליש מה שאין זה בחכמה שבראשית כלל שהיא נמצאת",[["1471","13","<b>דפנימית אבא. . ע\"י</b>: נסמן לקמן קכח, א."],["1472","14","<b>אז תתענג על ה'</b>: ישעי' נח, יד."],["1473","15","<b>דג' קשרין הן</b>: ראה זהר אחרי עג, א. מאמרי אדה\"א ויקרא ח\"א ע' צט. וש\"נ. דברים ח\"א ע' לט. וש\"נ. ח\"ג ע' תשעח ואילך וע' תשפג ואילך. הנחות תקע\"ז ע' שיח."],["1474","16","<b>ואהי' אצלו. . יום</b>: משלי ח, ל."],["1475","17","<b>ושעשועי את בנ\"א</b>: משלי שם, לא."],["1476","18","<b>משחקת לפניו</b>: משלי שם, ל."],["1477","19","<b>משחקת בתבל ארצו</b>: משלי שם, לא."],["1478","20","<b>טעמים בתענוג</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תע. וש\"נ."],["1479","21","<b>ב'</b>: ניתוסף ע\"פ דפו\"ר."],["1480","22","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["1481","23","<b>שבמוה\"ע</b>: נסמן לעיל ב, א."],["1482","24","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."]]],[2800530128,"עצמה יש מאין כנ\"ל וזה פלאי לכאורה אך הענין יובן בהקדים תחלה כללות ענין עגולים ויושר<sup data-n=\"1483\">1</sup> הנזכר בע\"ח דהנה ידוע שע\"ס דעגולים הן זה תוך זה כאשר יהיה האופן<sup data-n=\"1484\">2</sup> בתוך האופן כו' הן גבוהים מבחי' ע\"ס דאו\"י שהן זה תחת זה ובבחי' קוין כו' לפי שהעגולים הן בחי' מקיפים והן קרובים לעצמות המאציל יותר וא\"כ למה אמר בע\"ח דהעגולים הן בבחי' נפש<sup data-n=\"1485\">3</sup> והיושר בבחי' רוח והרוח גבוה במדריגה מן הנפש שמזה משמע שיש יתרון מעלה ביושר מה שאין בעגולים וכידוע דרוח ונפש רוח בחי' משפיע לנפש ואיך נעשה להיפך אחר שהעגולים קדמו לבחי' יושר בהשתלשלות כידוע בבחי' תהו ותיקון אך יש להבין תחלה בכללות ענין ההפרש בין בחי' עגולים ובין בחי' יושר ומבשרי אחזה דהנה נפש האדם למטה שהיא בצלם האלקים כלולה מב' מדריגות אלה דעגולים ויושר בהיות שאנו רואים בנפש האדם שכלולה היא מכל הכחות הנמצאים באברי הגוף בגשמיות כי הנפש רואה ושומעת ומדברת והולכת כנשמות בג\"ע שהולכים מחיל אל חיל כו' ומספרים זע\"ז ורואים בראיה שכלית וכל ציור תמונה דאדם שבגוף הכל נמצא בנפש עצמה רק שבנפש הם כלולים ומתאחדים זע\"ז בלי חילוק מדריגות כי אין לכל א' מקום וכלי משכן בפ\"ע כלל כמו כח הרצון וכח השכל וכח הראיה ושמיעה ודבור והילוך הכל כאחד שנמצא כלולים הכל בהעלם הרוחניות זה תוך זה ע\"ד דוגמא כשמשכיל טעם לרצון ובטעם זה כלולים המדות שבלב ובמדות כלולים המו\"ד ומעשה שנמצא כלולים הכל ברצון שלמעלה מן הטעם וכולם בהעלם ולא בגלוי מהות בפ\"ע כלל וזהו כדמיון העיגולים שעיגול כלול בתוך עיגול בהעלם עד עיגול העליון יותר כו' אבל בחי' התפשטות כחו' הנפש אח\"כ בבואה באברי הגוף שנעשה בפרצוף אדם הרי יש לכל אחד מקום וכלי בפ\"ע כשכל במוח וראיה בעין ודבור בפה והלוך ברגל וכה\"ג בכל לפי שהכחות מתפשטים כבר בגלוי מן העלם שבנפש כמו ג' חדרים במוח חב\"ד ומתפשטים למטה בחיצוניות בכלים מכלים שונים עוד כראיה בעין ממוח החכמה ושמיעה באזן ממוח הבינה<sup data-n=\"1486\">4</sup> ונתגשמו עוד בג' כלים בקנה ושט ורידין<sup data-n=\"1487\">5</sup> כידוע ובפנימית מתפשטים ג' אלה במדות חג\"ת שבלב כו' ונמצא נעשה ציור קומת אדם ראש ולב וידים ורגלים שהן חב\"ד חג\"ת נה\"י בפנימית וחיצונית דוקא עד הרגלים שהן נה\"י בגשמיות וגופא חזה הלב כו' וראש גשמי זהו הנקרא אדם בפרצוף דבחי' יושר שבא האור וחיות הנפש בהשתלשלות להתגשם מלמעלה עד למטה כמו בהילוך ברגל ונמצא לא נקרא פרצוף אדם אלא בב' דברים אלו א' ההתחלקות אורות בכלים פרטים כל אחד בכלי בפ\"ע דוקא והב' כשהוא בציור קומה דוקא כמו מראש לרגל בגשמיות דוקא משא\"כ בכחות הרוחני' שבנפש שאין שם ב' דברים אלו שכולם מתכללים זע\"ז ולא נמשך בהשתלשלות והגשמ' בציור קומה כציור אדם בראש ורגל כו' אשר ע\"כ לא נקרא אדם בבחי' העגולים רק בבחי' היושר שהוא הנפש אשר באברי הגוף דוקא כידוע וד\"ל:",[["1483","1","<b>עגולים ויושר</b>: ראה ע\"ח (שער דרוש עגו\"י) ש\"א ענף ב' וג'. מאמרי אדה\"א קונטרסים ע' תלב. מאמרי אדה\"א בראשית ע' קעה. וש\"נ. הנחות תקע\"ז ע' קמג. וש\"נ."],["1484","2","<b>כאשר יהי' האופן</b>: יחזקאל א, טז. י, י."],["1485","3","<b>דהעגולים הן בבחי' נפש</b>: ראה ע\"ח שם ענף ג."],["1486","4","<b>כראי'. . החכמה ושמיעה. . הבינה</b>: ראה סה\"מ תקס\"ה כאן ע' רכח. לעיל מג, ב ובהנסמן במ\"מ לשם."],["1487","5","<b>בקנה ושט ורידין</b>: ראה גם סה\"מ תקס\"ה שם."]]],[2800530129,"(לח) <b>והנמשל</b> מכל זה יובן למעלה בבחי' ע\"ס דעגולים שתחלה נאצל אור הכתר שהוא הרצון שלמעלה מן החכמה שנכלל העיגול דחכמה בעיגול הכתר וכן הבינה בחכמה כו' עד בחי' המל' האחרון כולם כלולים בהעלם אור הכתר ואח\"כ נאצל בחי' ע\"ס דיושר בבחי' או\"כ בפרצוף אדם שהחכמה בראש שנקרא גלגלתא ומוחא כמו שאמר חכמה מוחא<sup data-n=\"1488\">6</sup> עד חסד דרועא וכה\"ג שנקרא אדם דאצילות בציור אברים (אע\"פ שאין לו גוף<sup data-n=\"1489\">7</sup> כו' כתיב ועל הכסא דמות כמראה אדם<sup data-n=\"1490\">8</sup> כו' כידוע) וע\"כ ודאי דבחי' ע\"ס דעגולים דתהו קרובים יותר לעצמות המאציל כו' מבחי' ע\"ס דיושר שהאורות מצומצמים בכלים מכלים שונים והיינו ענין ב' דברים הנ\"ל שנזכר במשל ציור אדם התחתון א' שהאור בא בכלי בגלוי בחלקי' פרטיי' והב' מה שבא בהגשמה מלמעלה עד למטה בחיצוניות האברים כמו הילוך ברגל גשמי כו' משא\"כ בבחי' העגולים שהכל כלול בהעלם וברוחניות כו' וא\"כ יש להבין למה בבחי' העגולים בחי' נפש והיושר בבחי' רוח כמ\"ש בע\"ח אלא צ\"ל שיש יתרון מעלה בבחי' היושר באו\"כ בחיצוניות דוקא שאינו בבחי' העגולים כנ\"ל והענין הוא לפי שבאמת הרי יש בבחי' יושר דפרצוף אדם בחיצוניות יותר מבחי' ההתכללות מה שאין בעגולים שהרי אנו רואים באברי האדם שיש מבחי' הראש ברגל ומבחי' הרגל בראש ואחוז וקשור ראש בסוף וסוף בראש כידוע דגידי המוח מתפשטים ברגל כו' וראיה שאם יקיזו ברגל יתרפא חולי הראש<sup data-n=\"1491\">9</sup> וכן כל אבר יש לו חיבור וקשר עם זולתו בגידים ועורקים עד שכלולים זמ\"ז והיו לאחדים ממש בהתכללות גמורה עד מבלי שימצא ראש וסוף דהיינו מפני שכל א' מקבל מתחתון הימנו עד שהראש מקבל מן הרגל וראיה מן העמידה שהראש עמידתו ג\"כ על הרגל שהוא המוליכו ומעמידו וכשיפול ברגל יפול הראש וכן מן המזון שבקיבה ילך אור וחיות אל המוח שבראש לחזקו כו' וכה\"ג שאין כמו זה בבחי' העגולים דגם שכלולים זה בזה הרי יש עכ\"פ בחי' ראש וסוף שהרצון הוא הראש והדבור והילוך הוא הסוף אלא שכלולים הכל בהעלם ברצון כנ\"ל (ואע\"פ שנזכר הילוך בנשמות זהו בא שלא בסדר ובהדרגה כמו בהילוך הרגל בגשמיות עד שיעמיד לראש ויוליכנו אלא שכולו הולך כאחת כחיות ואופנים בלכתן שיסובבו כאחד כהילוך הגלגל כו' משא\"כ באדם שירצה ברצון תחלה ואח\"כ יומשך ללב ומשם יומשך כח התנועה ברגל כסדר ציור קומה לפי שכל א' בפ\"ע וע\"כ יכול להיות להיפוך שהראש יומשך אחר תנועת הרגל להוליכו כו') ונמצא מובן עכ\"פ שיש יתרון מעלה בבחי' יושר דאדם בב' דברים הנ\"ל דמפני זה דוקא יומשך כח ההילוך והעמידה ברגל בפ\"מ ולא ימצא כן בהעלם דעיגולים אע\"פ שכלול כח ההילוך בראש כו' וכן יש יתרון מעלה בזה במה שהרגל יעמיד לראש שכל הסיבה לזה אינו רק מצד ב' דברים הנ\"ל מפני שבא האור וחיות בחלקים פרטים בסדר קומה והב' מה שיורד האור וחיות ומתגשם מלמעלה למטה כנ\"ל וד\"ל (ויובן זה בנשמה שבגוף כל הנ\"ל דהנה נשמה בלא גוף ודאי יש בה כל הכחות",[["1488","6","<b>חכמה מוחא</b>: ת\"ז בהקדמה (יז, א)."],["1489","7","<b>שאין לו גוף</b>: ע\"פ פיוט יגדל. רמב\"ם פיה\"מ סנהדרין פ\"י היסוד הג'."],["1490","8","<b>ועל הכסא. . אדם</b>: יחזקאל א, כו [בדילוג — ראה לקמן עה, א. מאמרי אדה\"א הנחות תקע\"ז ע' קפט. וש\"נ. הנסמן במ\"מ לשע\"ת יד, א]."],["1491","9","<b>יקיזו ברגל. . הראש</b>: ראה גם סה\"מ תקס\"ה ח\"ב ע' תשי. ס\"ע תשיט. ע' תשסא. מאמרי אדה\"א במדבר ח\"א ע' רד. וש\"נ. ח\"ג ע' תתקפה. וש\"נ."]]],[2800530130,"הנמצאים בה בהיותה בגוף כמו הענג ורצון ושכל ומדות אוי\"ר ומו\"ד עד בחי' המעשה שילך בדרכי ה' ה\"ז ירידת אור האלקי דנשמה בחלקים רבים ויורד ומתגשם האור בסדר ציור קומת אדם מלמעלה למטה תחלה נתפעל ברצון ושכל ואח\"כ מתגשם במדות שבלב באוי\"ר ואח\"כ במו\"ד עד שבא לכלל מעשה שהוא בחי' ההילוך הטוב בדרכי ה' בפו\"מ להיות סומ\"ר ועש\"ט כו' עד ששמח במצוה ומואס ברע שמאיר מן פנימית הרצון בסוף מעשה כא' אבל תחלה כל אחד בפ\"ע דוקא ומתכללים אח\"כ עד שימצא בסוף מה שאין בראש כלל והוא ההילוך בדרכי ה' שבמעשה זו יתרון מעלה מכל פנימית הרצון ועונג וחכמה שבראש כו' עד שמעמיד ומוליך הראש שיוכל להתקיים בחכמה כח מ\"ה כו' וכמאמר כל שיראת חטאו<sup data-n=\"1492\">1</sup> קודמת לחכמתו חכמתו מתקיימת הרי החכמה כח מ\"ה דאין שבראש מתקיימת דוקא ע\"י יראת חטא שבסוף מעשה בפו\"מ משום דזהו יתרון מעלה בציור אדם בחיצוניות האברים שיורד האור דנשמה האלקי' ממוחין שבראש עד ההילוך שברגל שהוא בהגשמה גדולה שמפני זה נעשה הסוף בחי' ראש והראש סוף וראיה ממ\"ש סוף דבר כו' את האלקים ירא כו' כי זה כל האדם<sup data-n=\"1493\">2</sup> שבראש כו' וכמו הרגל שמעמיד הראש ואין הרא' מעמיד ומקיים לרגל כנ\"ל באריכות וד\"ל משא\"כ הנש' בלא גוף כלל הגם שבודאי כחו' שלה המה רוחניי' בבחי' האלקו' ממש כידוע שכל נשמה כמו שהיא למעלה היא חלק אלוה ממש כו' ויש בה כל הכחות עונג ורצון ושכל ומדות הכל בעילוי הרוחני הנבדל מן הגשם בתכלית כידוע ועכ\"ז אין בה יתרון מעלה הנ\"ל להיות כי כל הכחות הם כלולים זב\"ז כנ\"ל בבחי' העגולים דגם שנז' לשון הילוך בנשמות היינו שהרצון והעונג הוא העולה עיקר וממילא עולה גם השכל והמדות כו' עד שנמצא שעיקר לשון הילוך זה כמו ילכו מחיל<sup data-n=\"1494\">3</sup> כו' היינו בעצם אור הנשמה הרוחניות שנתעלי' כולה מדרגא לדרגא כמו מג\"ע התחתון לג\"ע העליון שהוא עילוי הרצון והשכל בבחי' השג' עליונ' יותר וממילא התפעלות אוי\"ר ומו\"ד הכל עולין כנ\"ל בענין ההתכללות דעיגולים אבל לא הילוך בפועל וכן האופנים וחיו' בלכתן<sup data-n=\"1495\">4</sup> אע\"פ שיש להן רגל כמו שאמר ורגליה' ישרות<sup data-n=\"1496\">5</sup> ואמרו שוקי החיות<sup data-n=\"1497\">6</sup> כו' וכה\"ג אך אין זה כמעלת הילוך באדם שיש בו יתרון מעלה שהראש מקבל מסוף אלא שבחי' רגל שלהם כלול בהילוך כל עצמו כעוף שיעופף כו' כמ\"ש בשתים יכסה פניו<sup data-n=\"1498\">7</sup> ובשתים יכסה רגליו ובשתים יעופף וכה\"ג וד\"ל (וע\"כ עיקר דסוף דבר כו' היום לעשותם<sup data-n=\"1499\">8</sup> כשהנשמה בגוף דוקא שנק' אדם בחיצוניות האברים ולא בנשמה שבלא גוף ברוחניות וראיה מתשובה ומע\"ט שהיא בעוה\"ז דוקא וכמ\"ש אשרי מי שבא לכאן<sup data-n=\"1500\">9</sup> כו') והנה בכל זה יובן הטעם שאמ' בע\"ח דעגולים בבחי' נפש ויושר בבחי' רוח דהנה כמו שבחי' נפש מקבל מבחי' רוח כך בחי' נפש דעגולים מקבל מבחי' רוח דיושר מטעם הנ\"ל כמו שהרא' מקבל מן הרגל שעמידתו על הרגל אעפ\"י שיש כח העמידה ברא' כידוע דגידי המוח שברא' הן שרש כללי לכל תנועה והרגש' מ\"מ הרי לא יוכל לעמוד על הרא' והוא לפי שכח העמיד' ברא' הוא רק ברוחניות דהיינו בהעלם ולא בגלוי במורג' והגשמה כמו ברגל",[["1492","1","<b>כל שיראת חטאו</b>: אבות פ\"ג, מ\"ט."],["1493","2","<b>סוף דבר. . כל האדם</b>: קהלת יב, יג."],["1494","3","<b>ילכו מחיל</b>: תהלים פד, ח."],["1495","4","<b>האופנים וחיו' בלכתן</b>: יחזקאל פ\"א."],["1496","5","<b>ורגליה' ישרות</b>: יחזקאל א, ז [ושם: ורגליהם רגל ישרה]."],["1497","6","<b>שוקי החיות</b>: חגיגה יג, א."],["1498","7","<b>בשתים יכסה פניו</b>: ישעי' ו, ב."],["1499","8","<b>היום לעשותם</b>: ואתחנן ז, יא."],["1500","9","<b>אשרי מי שבא לכאן</b>: פסחים נ, א. ראה גם לקמן פח, ב ובהנסמן במ\"מ לשם."]]],[2800530131,"כך יובן בדרך כלל שכל בחי' ההעלם בנפ' בכחותי' הגם שהן יותר נעלי' מכחו' האברים שבגוף מ\"מ עיקר קיומן ועמידתם הוא על החיות שבגוף דוקא כי נעוץ תחלתן בסופן דוקא ויש כח בסוף מה שאין ברא' ע\"כ בחי' יושר ישפיע ויחי' לבחי' עיגולים כמו שרוח יחי' וישפיע לנפ' וכ\"ז מפני שירד האור בגלוי ובהגשמ' בגוף וראי' לזה הוא מה שאין הילוך ברוחניות בהעלם דעגולים הנ\"ל או לעמוד אע\"פ שיש שם כל הכחות לפי שכולם כלולי' יחד בהעלם וכ\"ש שלא יקבל הרא' מן הסוף שאין זה רק בגוף אדם שהוא בא בגלוי ולא בהעלם יוכל לעמוד ולהלוך ממש וגם הרא' יעמוד על הרגל כנ\"ל ועדיין אין זה מתיישב לנכון דלמה עיגולים בבחי' נפש שהוא בבחי' הקטנות ויושר בבחי' רוח שהוא בחי' הגדלות אחר שמ\"מ עיקר העצם הוא ברוחניות שבנפ' ובגוף אינו רק הארה בעלמא כידוע ואיך יקבל העצם מן ההתפשטות שלו כו' אך הנה ידוע דבחי' העיגולים אינו רק בבחי' כתרים שהן בחי' נקודות בלתי מתחלקי' כלל כמו אור וכח הרצון אע\"פ שכלול מי' משכל ומדות כו' אינו רק אור א' פשוט וכן כח החכמ' שבנפ' אע\"פ שכלול' מי' וי' מי' אינה רק נקודה א' וכן המדות חסד הוא כח פשוט בלתי נגלה בו התחלקות לי' וכן גבו' ות\"ת כו' לפי שכולן כלולים זב\"ז בהעלם כנ\"ל וע\"כ הוא בבחי' הקטנות דבחי' נפש לבד אבל בחי' יושר בפרצוף אדם בגוף הרי כל אור מתחלק לי' וי' לי' כו' וכידוע בענין נקוד' ספי' פרצוף<sup data-n=\"1501\">10</sup> שהנקודה בלתי מתחלק לי' והספי' מתחלק לי' ופרצוף י' לי' ובריבוי כלים היינו ג' כלים<sup data-n=\"1502\">11</sup> פנימי ואמצעי וחיצון שהן עור ובשר גידין ועצמות<sup data-n=\"1503\">12</sup> והיינו חיצוניות האברים שבאדם שזהו עיקר שלימות האדם בבחי' הגדלות וראי' מן התולדה שבגוף דוקא יתהווה כח התולדה כשיגדל התינוק ויהי' בן ט' דוקא כי יש בו גידול המוחין גשמיי' בבחי' מותרות דוקא שאז ראוי להוליד<sup data-n=\"1504\">13</sup> ולד כמ\"ש במ\"א משא\"כ ברוחניו' שבנפש שאין נפש מוליד נפש אע\"פ שיש זווג נשמו' ברוחניו' כמ\"ש במ\"א בענין והנפש אשר עשו<sup data-n=\"1505\">14</sup> כו' וד\"ל ובזה יובן ג\"כ בעיגולים שהן בבחי' קטנו' קבלו מבחי' יושר שהוא בבחי' הגדלות אע\"פ שזהו כמו שמן התפשטו' בהגשמה יקבל העצם הרוחני כמו שאנו רואי' בנשמה בגוף שע\"י התפשטותה בהגשמה בגוף יתעלה אור הנשמה הרוחניו' כידוע שירידה זו צורך עלי'<sup data-n=\"1506\">15</sup> היא וכנ\"ל דיפה שעה א'<sup data-n=\"1507\">16</sup> בתשו' ומע\"ט בעוה\"ז דוקא כו' וכנ\"ל באריכות בענין ראי' גשמיי' שבנשמה בגוף עושה יתרון אור בראי' רוחניות דנשמה כו' וד\"ל:\n(לט) <b>ובכל</b> הנ\"ל יובן ענין הידוע דכל עיקר הכונה היה בירידה רק לצורך עלי' כו' דלכאורה יש להבין בזה ב' דברים הא' איך יוכל להיות שהנשפל ויורד למטה מטה בתכלית הצמצום יוכל לבא לעילוי אחר עילוי למעלה דמאין יהיה לו כח זה מאחר שהורד למטה ואם יש בכחו לעלות אין זו ירידה כלל ועוד דלמה הורד כדי שיתעל' לא יורידו וישפילו אותו בתחלה ולא יצטרך לעלות כו' אלא צ\"ל דירידה זו כוללת ב' ענינים א' עלייה לעצמו שע\"י ירידה זו יתעלה בעצמו מה שלא היה עולה כ\"כ בלתי ירידה זו והב' עלייה לעליון הימנו דדוקא העליון יתעלה ע\"י התחתון שהושפל וירד כו' וזה",[["1501","10","<b>נקוד' ספי' פרצוף</b>: ראה לקמן קכד, א ואילך ובהנסמן במ\"מ לשם."],["1502","11","<b>ג' כלים</b>: ראה לקמן קכח, סע\"ב ובהנסמן לשם."],["1503","12","<b>ג' כלים. . עור ובשר גידין ועצמות</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' תתקטז ואילך."],["1504","13","<b>בן ט'. . ראוי להוליד</b>: ראה לקמן קלג, א ובהנסמן במ\"מ לשם."],["1505","14","<b>והנפש אשר עשו</b>: לך יב, ה [ושם: ואת הנפש]. ראה ביאוה\"ז בראשית ב, א ואילך. נח ה, ד. מאמרי אדה\"ז על ענינים ע' קנא ואילך. ובנסמן במ\"מ לשם. מאמרי אדה\"א ויקרא ח\"ב ע' תרטו."],["1506","15","<b>שירידה זו צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["1507","16","<b>דיפה שעה א'</b>: אבות פ\"ד, מי\"ז [בהוספת אות ד (דיפה) — ראה הנסמן בתו\"ח בראשית ה, ג הערה 25]."]]],[2800530132,"פלא איך יוכל העליון להתעלו' ע\"י התחתון ממנו ולמה יהי' ירידה זו בשביל עלייה שלמעלה הימנו ומוכרח לומר שיש כח נעלה ביריד' זו שירד התחתון עד שיוכל להעלו' את העליון וזהו ענין הב' שיש להבין והכל עולה לטעם וכונ' א' והוא מובן ע\"פ כל הנ\"ל בבחי' עיגולי' ויושר שבבחי' צמצו' האור והגשמתו וירידתו בכלים מכלים שונים בחיצוניות האברים דבחינת יושר דאדם בגופו הוא בחי' רוח שלמעלה מבחי' נפש דעגולים ולכך יש כח העמיד' ברגל בגוף דוקא כו' וא\"כ אנו רואים בזה ענין ירידה צורך עליה הנ\"ל בב' אופנים הנ\"ל הא' שהוא עליה לעצמו שלזה ירדה הנפש בגוף כו' והענין הוא דהושם מלמעלה כח בתחתון שיוכל לעלות מעלה מעלה וא\"ל לא היה ביכולתו לעלות עצמו כלל אלא היה נשאר מטה מטה לעולם וראיה מן התשובה שאע\"פ שירדה הנפ' כבר מטה מטה כו' יש בו כח נעלה כ\"כ שיוכל לעלות מעלה מעלה כ\"כ ע\"י התעוררות התשובה מעומקא דלבא פתאום עד שתעל' נפשו למעל' ממדריגת הצדיקים שהרי במקום שבע\"ת עומדין<sup data-n=\"1508\">1</sup> צ\"ג א\"י לעמוד וכנתן דצוציתא<sup data-n=\"1509\">2</sup> וכראב\"ד שנתקנא בו רבי ואמר יש קונה עולמו<sup data-n=\"1510\">3</sup> בשעה אחת וכן ע\"י מצות מעשיות בגשמיות דאלה המצות אשר יעשה אותם האדם וחי בהם<sup data-n=\"1511\">4</sup> היינו שחי' יחי' לנפשו במעל' ומדריג' יתיר' מכמו שהיא במקור חוצב' כידוע במ\"ש סוף דבר כו' כי זה כל האדם כו' ודוקא בתשוב' ומע\"ט בעוה\"ז שלזה ירד' הנפ' שבזה דוק' תעל' לעצמ' מצד יתרון האור שבא מן בירור החשך דק\"נ דוקא ומטעם שסוף מעשה דוקא עבמ\"ת שהוא למעלה ממקור כל הנשמות שנבראו בצלם אדם וז\"ש האדם וחי בהם שיחי' לנשמתו שנקרא אדם בצלם אלקים ונמצא ירידה זו לצורך עלי' לעצמו שאם לא היה ירידה זו לא היה מגיע לעלוי כזה כלל ואופן הב' ביריד' זו שתעל' לעליון כו' הענין הוא דהושם כח גדול ונעל' יותר ביריד' זו שמלבד שתעל' א\"ע כ\"כ כנ\"ל הנה יש ביכולתו להעלות לכל העליונים הימנו הרבה עד רום המעלות וראיה לזה מתו\"מ בגשמיות שמגיע למעל' ממצות הרוחניות דאבות כמ\"ש ושמי הוי' לא נודעתי להם<sup data-n=\"1512\">5</sup> כמ\"ש במ\"א וגם מן העוה\"ב שאינו אלא רק מן קיום המצות בגשמיות ולא ברוחניות דאף בימי משיח עיקר השלימות יהיה רק בקיום מצות בפ\"מ אע\"פ שיהיה לאחר הבירור דעה\"ד כמ\"ש במ\"א בענין ושם נעשה לפניך כמצות רצונך<sup data-n=\"1513\">6</sup> כו' דמצות אינן בטילות לע\"ל<sup data-n=\"1514\">7</sup> ועכ\"ז המצות הבאים אלינו הנגלות לנו ולבנינו לשמור ולעשות בפו\"מ יותר נעלה משום דסוף מעשה שבגשמיות דוקא הוא שעבמ\"ת וע\"כ גם אור הג\"ע אינו ניתוסף רק על ידי המצות שלנו<sup data-n=\"1515\">8</sup> יותר מהוספת האור בג\"ע שהי' ע\"י אדה\"ר ברוחניות עבודתו שם דכתיב ויניחהו בג\"ע<sup data-n=\"1516\">9</sup> לעבדה ולשמרה כידוע וגם זה הטעם עצמו צריך טעם למה סוף מעשה דוקא עבמ\"ת הרי ידוע לפי שהצמצום הראשון שנקרא מק\"פ<sup data-n=\"1517\">10</sup> והוא מ\"ש ישת חשך סתרו<sup data-n=\"1518\">11</sup> כשירד למט' מטה נקרא חושך וצמצום גמור עד שנעשה מסך מבדיל לגמרי והוא ק\"נ וכאשר יתברר החושך והרע דק\"נ ע\"י סו\"מ בפ\"מ ועש\"ט בטוב שבק\"נ בגשמיו' דוקא כמו ע\"י צמר גשמי דטלית וקלף דתפילין ובקבלת עומ\"ש פשוט'",[["1508","1","<b>במקום שבע\"ת עומדין</b>: ראה ברכות לד, ב. לקו\"ש (נצבים) כרך יד ע' 361 וע' 363. תו\"ח בראשית ו, ד הערה 32. שע\"ת ח\"א כט, ד."],["1509","2","<b>וכנתן דצוציתא</b>: ראה שבת נו, ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'שעז־ הנחות תקע\"ז ע' ריג. שע\"ת ח\"א נז, ב."],["1510","3","<b>וכראב\"ד. . יש קונה עולמו</b>: נסמן לעיל נט, ב."],["1511","4","<b>דאלה המצות. . וחי בהם</b>: נסמן לקמן סח, ב."],["1512","5","<b>ושמי הוי' לא נודעתי להם</b>: וארא ו, ג. ראה סה\"מ תקס\"ב ח\"א ס\"ע יב. מאמרי אדה\"א בראשית ע' קעט. שמות ח\"א ע' רנז ובהנסמן בהנ\"ל."],["1513","6","<b>ושם. . כמצות רצונך</b>: תפלת מוסף [בדילוג]. ראה [ד\"ה אוסרי לגפן תקס\"ד נדפס ב]תו\"ח ויחי רלו, א. רלח, ד ואילך. מאמרי אדה\"א שמות ח\"א ע' רכו. וש\"נ. במדבר ח\"ה ע' א'תרכד."],["1514","7","<b>דמצות אינן בטילות לע\"ל</b>: ראה נדה סא, ב. אגה\"ק סכ\"ו (קמה, סע\"א)."],["1515","8","<b>הג\"ע. . המצות שלנו</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' שצח. וש\"נ. ח\"ד ע' א'רפד. שמות ח\"ב ס\"ע שטו ואילך."],["1516","9","<b>ויניחהו בג\"ע</b>: בראשית ב, טו [בדילוג]. ראה גם לעיל נט, ב ובהנסמן שם."],["1517","10","<b>שהצמצום הראשון שנקרא מק\"פ</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב."],["1518","11","<b>ישת חשך סתרו</b>: תהלים יח, יב."]]],[2800530133,"כעבד גשמי דוקא הנה מזה יבא למעלה יתרון האור הרבה יותר מגופו של אור שאחר הצמצום הראשון וזה היה התענוג הנעלם הפשוט העצמי שיבא יתרון האור מן החשך שלמט' כדי שיאיר גם מבחי' החשך העליון דכתיב ישת חשך סתרו וכמ\"ש מגלה עמוקות מני חשך<sup data-n=\"1519\">12</sup> דוקא וע\"כ אמר בזהר בכמה דוכתי דכד אתכפיא סט\"א<sup data-n=\"1520\">13</sup> דוקא אסתלק יקרא דקב\"ה בכ\"ע דהיינו מבירור דק\"נ יבא למעלה עילוי גדול ביקרא דקב\"ה עד רום המעלות עד האור דעצמות שיאיר בתוס' מרובה מתוך ההעלם וחשך סתרו הנ\"ל וזהו אסתלק בעילוי גדול רק ממה דאתכפיא ס\"א בסו\"מ<sup data-n=\"1521\">14</sup> בפ\"מ אע\"פ שלא נהפך לגמרי וכך אמרו טוב זה מלאך חיים<sup data-n=\"1522\">15</sup> מאד זה מה\"מ לאחר שיבורר הרע והמות נקרא טוב מאד בלי גבול וכידוע שזהו טעם דבע\"ת גדולים מצ\"ג ולכך אם עושין תשובה<sup data-n=\"1523\">16</sup> דוקא נגאלין כו' וד\"ל ולפ\"ז הרי יובן דכל היחודים עליונים שנעשו ע\"י מצות שלנו למעלה אע\"פ שהן בהעלם למטה אבל למעלה הן מוסיפים אור מעצמות א\"ס ב\"ה מה שלא יהיה כן ע\"י כל יח\"ע שברוחניות דע\"ס דאצי' כו' וזהו שיבא יתרון אור מן בירור דק\"נ שזהו עולה על כל יח\"ע כו' וזהו טעם הנ\"ל שסוף מעשה דוקא עבמ\"ת שאין כל יח\"ע מגיעים לשם כלל רק המצוה ותשובה שבעוה\"ז דוקא כנ\"ל ולזאת לא יפלא כלל מה שיוכל להיות כח נעלה וחזק כ\"כ במעשה התחתונים בירידה זו הנ\"ל עד שיוכל להעלות כל העליונים עד רום המעלות מה שאין יכולים להגיע שם מכח יח\"ע הרוחניים העליונים מטעם הנ\"ל (וזהו כמשל כותל גבוה שכאשר ירצו להגביה אותו נותנין הכלי הגבה' (הנקרא ליבער<sup data-n=\"1524\">17</sup> ) תחת העץ התחתון<sup data-n=\"1525\">18</sup> שאז יתעלו ממילא כולם אבל אם יתנוהו בחצי הכותל ישאר חצי התחתון למטה כו'<sup data-n=\"1526\">19</sup> וזהו הטעם שירדה הנפ' בגוף חומרי כמ\"ש ויפח באפיו<sup data-n=\"1527\">20</sup> נשמת חיים כו' כדי שע\"י ירידה זו שאין למטה הימנה יתעלה כל מה שעליון הימנו שאין למעל' הימנו וכך היה התענוג העצמי שהעליון שאין למעלה הימנו יתעלה על ידי התחתון שאין למטה הימנו דוקא כמו הרא' שמקבל מן הסוף דוקא כנ\"ל בענין עמידת הראש ע\"ג<sup data-n=\"1528\">21</sup> הרגל שאין זה רק בחיצוניות אברים דבחינת יושר וזהו הטעם שיושר בחי' רוח להחיות לבחי' נפש דבחינת עיגולים כי ירידה זו מלבד עלי' לעצמו הנ\"ל עיקר הכונ' בה לעלות לעליון הימנ' שהוא בחינת עיגולים דתהו שקדם הרבה לבחינת יושר כי כך המד' שעל' במ\"ת כנ\"ל וד\"ל:\n<b>ואחר</b> כ\"ז יובן ענין הנ\"ל אשר יש כח הנעלה וחדש בארץ שיחוד' בה יש מאין ממש אשר אין זה בכח החכמה שנקרא ראשית שגם היא מאין תמצא וגם למעלה מן התחלה כו' כמ\"ש למעלה בענין הנני בורא חדשה בארץ דוקא נקבה תסובב גבר כו' שזהו מקדם אשר לא נעשו שלמעלה גם ממגיד מראשית אחרית דאופן הב' הנ\"ל דהנה כל ענין הנ\"ל בפי' מגיד מראשית אחרית היינו שיש כח באחרית כמו בראשית לפי ששניהם שוין לפני עצמותו ממש כנ\"ל אבל יש יתרון מעלה עוד באחרית אשר אין בראשית דחכמה כלל והיינו עפ\"י הנ\"ל בענין יתרון מעלה דיושר על בחינת העיגולים דירידה זו צורך עלי' להעלות לעליון כו' ולזה הטעם ימצא כח בארץ לחדש יש מאין שאין זה בראשית דחכמה",[["1519","12","<b>מגלה עמוקות מני חשך</b>: איוב יב, כב."],["1520","13","<b>דכד אתכפיא סט\"א</b>: נסמן לעיל מב, א."],["1521","14","<b>בסו\"מ</b>: ( בסור מרע) כ\"ה בדפו\"ר. ובמהדורת לעמבערג: בתו\"מ."],["1522","15","<b>טוב זה מלאך חיים</b>: בראשית א, לא. יל\"ש שם (רמז טז)."],["1523","16","<b>אם עושין תשובה</b>: סנהדרין צז, ב."],["1524","17","<b>ליבער</b>: כ\"ה גם בתו\"ח בראשית כ, ד. ובתו\"א ד, א: ליווע\"ר."],["1525","18","<b>תחת העץ התחתון</b>: במאמרי אדה\"ז על ענינים ע' תה ובאוה\"ת על ענינים ע' שכו מובא זה בשם הה\"מ."],["1526","19","<b>כו'</b>: אוצ\"ל: כו')."],["1527","20","<b>ויפח באפיו</b>: בראשית ב, ז."],["1528","21","<b>ע\"ג</b>: אוצ\"ל: ע\"י."]]]]});
